namespace ProjectAPI.Domain.Reservations.Entities;

/// <summary>
/// Reservation lifecycle (spec §12.4).
///
/// IMPORTANT — the numeric values 0..4 are already persisted in the database and
/// are part of the API contract. They MUST NOT be renumbered. New states are
/// appended with fresh values.
///
/// Spec name mapping: <see cref="Pending"/> is the spec's SUBMITTED and
/// <see cref="Sold"/> its CONVERTED. The historical names are kept to avoid a
/// breaking rename across the API, the seed data and the frontend.
/// </summary>
public enum ReservationStatus
{
    /// <summary>Spec `SUBMITTED` — submitted, awaiting administrative decision.</summary>
    Pending = 0,

    /// <summary>Spec `APPROVED` — approved; the unit is reserved.</summary>
    Approved = 1,

    /// <summary>Spec `REJECTED` — refused by the administrator. Terminal.</summary>
    Rejected = 2,

    /// <summary>Spec `CANCELLED` — cancelled after approval. Terminal.</summary>
    Cancelled = 3,

    /// <summary>Spec `CONVERTED` — converted into a sale. Terminal.</summary>
    Sold = 4,

    /// <summary>Spec `DRAFT` — agent draft. Does NOT block the unit (§12.1).</summary>
    Draft = 5,

    /// <summary>Spec `CHANGES_REQUESTED` — correction requested; unit stays blocked (§12.2).</summary>
    ChangesRequested = 6,

    /// <summary>Spec `EXPIRED` — expired at ExpiresAt. Terminal; releases the unit (§12.3).</summary>
    Expired = 7
}
namespace ProjectAPI.Domain.Immeubles.Entities;

/// <summary>
/// Commercial status of a unit — spec §3, the backbone of the sale workflow.
///
/// Persisted as the canonical UPPER_SNAKE_CASE code (§6.1: statuses are varchar
/// + CHECK constraint, not database enums). See <see cref="UnitStatusCodes"/>.
/// </summary>
public enum UnitCommercialStatus
{
    /// <summary>Selectable. The only status from which a reservation may start (§3).</summary>
    Available = 0,

    /// <summary>Held by a submitted reservation awaiting an administrative decision.</summary>
    HoldPendingApproval = 1,

    /// <summary>Reservation approved.</summary>
    Reserved = 2,

    /// <summary>
    /// Final contract validated (§3). No command in this codebase produces this
    /// state: the spec names it but never assigns it an owner, a command, a
    /// screen or an endpoint. The value exists so the matrix is complete and so
    /// data created elsewhere round-trips; the notary path goes RESERVED → SOLD
    /// directly, which §47.2 explicitly permits
    /// ("RESERVED ou CONTRACTED | Achat finalisé chez le notaire | SOLD").
    /// Open question for the client — see BACKEND_DOMAIN_AUDIT.md.
    /// </summary>
    Contracted = 3,

    /// <summary>Purchase completed at the notary (§5.7 PURCHASE_COMPLETED).</summary>
    Sold = 4,

    /// <summary>Keys handed over and handover report acknowledged (§5.8). Terminal.</summary>
    Delivered = 5,

    /// <summary>Withdrawn from sale by an administrator, with a reason (§3).</summary>
    Suspended = 6,

    /// <summary>Abandoned. Terminal (§3).</summary>
    Cancelled = 7
}

/// <summary>
/// Canonical string codes for <see cref="UnitCommercialStatus"/>.
///
/// These are the exact §3 codes. They are what the column stores and what the
/// API returns, so the frontend consumes them verbatim (its adapter already
/// accepts canonical codes ahead of the legacy PascalCase spellings).
/// </summary>
namespace ProjectAPI.Domain.Appointments.Entities;

/// <summary>
/// Result of a notary appointment — spec §5.7 / §18.
///
/// The outcome is deliberately SEPARATE from the appointment's status. Status
/// says what happened to the meeting (requested, confirmed, completed…);
/// the outcome says what the meeting decided. A COMPLETED appointment where the
/// buyer did not show and a COMPLETED appointment that finalised the purchase
/// are the same status and entirely different business events.
///
/// Only <see cref="PurchaseCompleted"/> changes anything: it converts the
/// reservation and sells the unit, atomically. Every other outcome leaves the
/// reservation and the unit exactly where they were, so the file can be retried
/// with a new appointment.
/// </summary>
public enum NotaryAppointmentOutcome
{
    /// <summary>Purchase finalised — reservation → CONVERTED, unit → SOLD (§5.7).</summary>
    PurchaseCompleted = 0,

    /// <summary>Dossier incomplete; nothing changes.</summary>
    IncompleteFile = 1,

    /// <summary>Buyer absent; nothing changes.</summary>
    BuyerAbsent = 2,

    /// <summary>Deferred to a later date; nothing changes.</summary>
    Postponed = 3,

    /// <summary>Any other reason the purchase did not complete; nothing changes.</summary>
    NotCompletedOther = 4
}

