        ClaimStatus.Submitted,
        ClaimStatus.UnderReview,
        ClaimStatus.MoreInfoRequired,
        ClaimStatus.Assigned,
        ClaimStatus.InProgress,
        ClaimStatus.WaitingCustomer,
        ClaimStatus.Resolved
    };
}

