// ============================================================================
// Shared fetch wrapper for both backends. Attaches the Bearer token (stored by
// AuthContext under TOKEN_STORAGE_KEY) on every request — most ProjectAPI
// endpoints don't enforce auth yet, but sending it now means nothing breaks
// when the backend locks them down later (see FRONTEND_BACKEND_INTEGRATION.md §3).
// ============================================================================
import { config } from "../../lib/config";

export const TOKEN_STORAGE_KEY = "gpia_token";

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_STORAGE_KEY);
}

export function setToken(token: string | null): void {
  if (token) localStorage.setItem(TOKEN_STORAGE_KEY, token);
  else localStorage.removeItem(TOKEN_STORAGE_KEY);
}

/**
 * Stable business error codes (backend `BusinessErrorCodes`, spec §31.7).
 * Branch on these — never on `message`, which is localised and may change.
 */
export type BusinessErrorCode =
  | "UNIT_NOT_AVAILABLE"
  | "APPOINTMENT_SLOT_CONFLICT"
  | "RESOURCE_VERSION_CONFLICT"
  | "IDEMPOTENCY_KEY_REUSED"
  | "INVALID_STATUS_TRANSITION"
  | "MISSING_REQUIRED_DOCUMENT"
  | "DISCOUNT_LIMIT_EXCEEDED"
  | "PROJECT_PROGRESS_INCOMPLETE"
  | "INVALID_REPORT_RESULT"
  | "NOTARY_NOT_ELIGIBLE"
  | "VALIDATION_FAILED"
  | "NOT_FOUND"
  | "UNAUTHORIZED"
  // §6.4 — authenticated and correctly roled, but outside the caller's project
  // perimeter / not their own dossier. Returned as HTTP 403.
