import type { HandoverAppointment } from "../../types";
import type { DeliveriesApi } from "../interfaces";
import { projectFetch } from "./client";
import { handoverStatusString } from "./enums";

export const deliveriesApi: DeliveriesApi = {
  async list() {
    // No GET /api/deliveries list/query endpoint exists on the backend today
    // (only create + update-status) — flagged as a backend gap in the integration doc.
    return [];
  },
  async schedule(data) {
    const id = await projectFetch<string>("/api/deliveries", {
      method: "POST",
      body: JSON.stringify({ report: "", ...data, status: undefined }),
    });
    // The legacy backend creates deliveries as "Scheduled" ⇒ CONFIRMED (§5.8).
    return { ...data, id, status: handoverStatusString.fromLegacy("Scheduled")! } as HandoverAppointment;
  },
  async updateStatus(id, status) {
    await projectFetch<boolean>(`/api/deliveries/${id}/status`, {
      method: "PATCH",
      body: JSON.stringify({ status: handoverStatusString.toLegacy(status), report: "" }),
    });
    return { id, status } as HandoverAppointment;
  },
};
