import { expect, request, type APIRequestContext, type APIResponse } from "@playwright/test";
import { ACCOUNTS, AUTH_API, E2E_PASSWORD, PROJECT_API, type RoleKey } from "./accounts";

export interface Session {
  key: RoleKey;
  userId: string;
  token: string;
  roles: string[];
}

export interface LoginResponse {
  accessToken: string | null;
  isAutheticated: boolean;
  roles: string[];
  user: { id: string; email: string; firstName?: string; lastName?: string };
}

export async function loginRaw(userName: string, password = E2E_PASSWORD): Promise<LoginResponse> {
  const ctx = await request.newContext();
  try {
    const res = await ctx.post(`${AUTH_API}/api/User/login`, { data: { userName, password } });
    expect(res.status(), `login ${userName}`).toBe(200);
    return (await res.json()) as LoginResponse;
  } finally {
    await ctx.dispose();
  }
}

const sessions = new Map<RoleKey, Session>();

/**
 * API session for a role, cached per worker. `fresh` re-logs in — needed when
 * the account's roles changed server-side (e.g. BUYER granted on approval),
 * because roles are baked into the JWT at login.
 */
export async function session(key: RoleKey, fresh = false): Promise<Session> {
  const cached = sessions.get(key);
  if (cached && !fresh) return cached;
  const body = await loginRaw(ACCOUNTS[key].userName);
  expect(body.isAutheticated, `login ${key}`).toBe(true);
  const s: Session = { key, userId: body.user.id, token: body.accessToken!, roles: body.roles };
  sessions.set(key, s);
  return s;
}

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly body: string,
    readonly call: string,
  ) {
    super(`${call} -> HTTP ${status}: ${body.slice(0, 400)}`);
  }
}

/** Thin JSON client over ProjectAPI (or AuthAPI) for one role. */
export class Api {
  private constructor(
    readonly ctx: APIRequestContext,
    readonly s: Session,
  ) {}

  static async as(key: RoleKey, fresh = false): Promise<Api> {
    const s = await session(key, fresh);
    const ctx = await request.newContext({
      extraHTTPHeaders: { Authorization: `Bearer ${s.token}`, Accept: "application/json" },
    });
    return new Api(ctx, s);
  }

  get userId() {
    return this.s.userId;
  }

  /** Raw call: never throws on HTTP status. Use for authorization assertions. */
  async raw(method: string, path: string, data?: unknown, base = PROJECT_API): Promise<APIResponse> {
    return this.ctx.fetch(`${base}${path}`, {
      method,
      data: data === undefined ? undefined : data,
      headers: data === undefined ? undefined : { "Content-Type": "application/json" },
    });
  }

  /** Call that must succeed (2xx); returns parsed JSON (or text when not JSON). */
  async ok<T = any>(method: string, path: string, data?: unknown, base = PROJECT_API): Promise<T> {
    const res = await this.raw(method, path, data, base);
    const text = await res.text();
    if (!res.ok()) throw new ApiError(res.status(), text, `${this.s.key} ${method} ${path}`);
    if (!text) return undefined as T;
    try {
      return JSON.parse(text) as T;
    } catch {
      return text as unknown as T;
    }
  }

  get<T = any>(path: string) {
    return this.ok<T>("GET", path);
  }
  post<T = any>(path: string, data?: unknown) {
    return this.ok<T>("POST", path, data ?? {});
  }
  put<T = any>(path: string, data?: unknown) {
    return this.ok<T>("PUT", path, data ?? {});
  }
  patch<T = any>(path: string, data?: unknown) {
    return this.ok<T>("PATCH", path, data ?? {});
  }
  del<T = any>(path: string) {
    return this.ok<T>("DELETE", path);
  }

  async dispose() {
    await this.ctx.dispose();
  }
}

/** Asserts the raw response is an authorization/business refusal, not a success. */
export async function expectRefused(res: APIResponse, allowed: number[] = [401, 403], what = "") {
  const body = await res.text();
  expect(allowed, `${what} expected refusal ${allowed.join("/")}, got ${res.status()} ${body.slice(0, 300)}`).toContain(
    res.status(),
  );
}

