  opts: { state?: "DRAFT" | "SUBMITTED" | "APPROVED"; buyer?: RoleKey; unitIndex?: number; agent?: RoleKey } = {},
): Promise<JourneyFixture> {
  const buyerKey = opts.buyer ?? "buyer";
  const agent = await Api.as(opts.agent ?? "agent");
  const buyer = await Api.as(buyerKey);
  const unitId = p.unitIds[opts.unitIndex ?? 0];
  const res = await agent.post<{ reservationId: string }>("/api/Reservations/create", {
    buyerId: buyer.userId,
    name: "Yasmine",
    lastName: `E2E-${buyerKey}`,
    cin: `E2E${uid().slice(0, 6)}`,
    email: `${buyerKey}.${uid()}@example.test`,
    phoneNumber: "+212600112233",
    unitId,
    agentId: agent.userId,
    totalPropertyPrice: 1250000,
    reservationAmount: 125000,
    isUnderConstruction: true,
    createAsDraft: opts.state === "DRAFT",
    discount: 0,
  });
  const j: JourneyFixture = { project: p, unitId, reservationId: res.reservationId, buyer: buyerKey };
  if (opts.state === "APPROVED") await approveReservation(j);
  return j;
}

export async function approveReservation(j: JourneyFixture) {
  const a = await admin();
  await a.post(`/api/Reservations/${j.reservationId}/approve`, {
    reservationId: j.reservationId,
    adminUserId: a.userId,
    adminNote: "Approuvé (E2E)",
    documents: [],
  });
}

/**
 * createFinalVisit(result): buyer requests, agent confirms, admin authorises
 * early completion, agent files the report, buyer acknowledges it. The land
 * title is moved to AVAILABLE so the dossier becomes notary-eligible.
 * Requires the project to be EN_LIVRAISON (§ final visit gate).
 */
export async function createFinalVisit(j: JourneyFixture, result: "COMPLIANT" | "REQUESTED" = "COMPLIANT") {
  const buyer = await Api.as(j.buyer, true);
  const agent = await Api.as("agent");
  const a = await admin();
  const fv = await buyer.post<{ caseId: string; appointmentId: string }>(`/api/final-visits/reservations/${j.reservationId}/request`, {
    reservationId: j.reservationId,
    startsAt: iso(daysFromNow(2 + Math.floor(Math.random() * 60), 9 + Math.floor(Math.random() * 8))),
  });
  j.finalVisitAppointmentId = fv.appointmentId;
  if (result === "REQUESTED") return j;

  await agent.post(`/api/final-visits/appointments/${fv.appointmentId}/transition`, { appointmentId: fv.appointmentId, targetStatus: AppointmentStatus.Confirmed });
  await a.post(`/api/final-visits/appointments/${fv.appointmentId}/transition`, {
    appointmentId: fv.appointmentId,
    targetStatus: AppointmentStatus.Completed,
    allowEarlyCompletion: true,
  });
  const report = await agent.post<{ reportId: string }>(`/api/final-visits/appointments/${fv.appointmentId}/report`, {
    appointmentId: fv.appointmentId,
    resultCode: 0,
    generalCondition: "Conforme",
    observations: "Aucune réserve (E2E)",
    snags: [],
  });
  j.finalVisitReportId = report.reportId;
  await buyer.post(`/api/final-visits/reports/${report.reportId}/acknowledge`, { reportId: report.reportId });

  await a.patch(`/api/construction/units/${j.unitId}/title`, { unitId: j.unitId, status: 1, reason: "Dépôt conservation foncière (E2E)" });
  await a.patch(`/api/construction/units/${j.unitId}/title`, { unitId: j.unitId, status: 2, reason: "Titre obtenu (E2E)" });
  return j;
}

export async function createDraftSale(j: JourneyFixture, as: RoleKey = "agent") {
  const api = await Api.as(as);
  const sale = await api.post<{ id: string; status: string }>("/api/sales", { reservationId: j.reservationId, notes: "Vente E2E" });
  j.saleId = sale.id;
  return sale;
}

/**
 * createNotaryAppointment(result): booked by the agent for this project's
 * notary; with a result, confirmed then completed by the notary.
 */
export async function createNotaryAppointment(j: JourneyFixture, result?: "PURCHASE_COMPLETED" | "POSTPONED") {
  const agent = await Api.as("agent");
  const notary = await Api.as("notary");
  const buyer = await Api.as(j.buyer);
  const na = await agent.post<{ id: string }>("/api/NotaryAppointments", {
    reservationId: j.reservationId,
    notaireId: notary.userId,
    agentId: agent.userId,
    buyerId: buyer.userId,
    appointmentDate: iso(daysFromNow(5 + Math.floor(Math.random() * 600), 8 + Math.floor(Math.random() * 9))),
    status: "Scheduled",
    taxFees: 25000,
    tahfidFees: 8000,
  });
  j.notaryAppointmentId = na.id;
  if (result) {
    await notary.put(`/api/NotaryAppointments/${na.id}`, { id: na.id, status: "Confirmed" });
    await notary.put(`/api/NotaryAppointments/${na.id}`, {
      id: na.id,
      status: "Completed",
      outcome: result,
      outcomeNote: result === "PURCHASE_COMPLETED" ? "Acte signé (E2E)" : "Reporté (E2E)",
    });
  }
  return j;
}

/** deliverUnit(): handover scheduled, confirmed, reported, acknowledged by the buyer. */
export async function deliverUnit(j: JourneyFixture) {
  const agent = await Api.as("agent");
  const buyer = await Api.as(j.buyer, true);
  const ho = await agent.post<{ id: string }>("/api/Handovers", {
    reservationId: j.reservationId,
    scheduledAt: iso(daysFromNow(9)),
    location: "Sur site",
    notes: "Remise des clés (E2E)",
  });
  j.handoverId = ho.id;
  await agent.post(`/api/Handovers/${ho.id}/confirm`);
  const rep = await agent.post<{ id: string }>(`/api/Handovers/${ho.id}/report`, {
    appointmentId: ho.id,
    participants: "Acquéreur, agent",
    observations: "Logement conforme (E2E)",
    items: [{ itemType: "Clés", quantity: 2 }],
  });
  await buyer.post(`/api/Handovers/reports/${rep.id}/acknowledge`, {});
  return j;
}

export async function createClaim(j: JourneyFixture, title = `Fuite ${uid()}`) {
  const buyer = await Api.as(j.buyer, true);
  const claim = await buyer.post<{ id: string }>("/api/after-sales/claims", {
    unitId: j.unitId,
    title,
    description: "Infiltration constatée (E2E)",
    category: 2,
    priority: 1,
  });
  j.claimId = claim.id;
  return { id: claim.id, title };
}

/** Full journey up to a given stage, in dependency order. */
export async function journey(
  upTo: "APPROVED" | "FINAL_VISIT" | "DRAFT_SALE" | "SOLD" | "DELIVERED" | "CLAIM",
  opts: { buyer?: RoleKey; warrantyMonths?: number } = {},
): Promise<JourneyFixture> {
  const p = await createProject({ phase: "SUR_PLAN", warrantyMonths: opts.warrantyMonths });
  const j = await createReservation(p, { state: "APPROVED", buyer: opts.buyer });
  if (upTo === "APPROVED") return j;
  await setConstructionPct(p, 100);
  await completeProject(p);
  await createFinalVisit(j);
  if (upTo === "FINAL_VISIT") return j;
  await createDraftSale(j);
  if (upTo === "DRAFT_SALE") return j;
  await createNotaryAppointment(j, "PURCHASE_COMPLETED");
  if (upTo === "SOLD") return j;
  await deliverUnit(j);
  if (upTo === "DELIVERED") return j;
  await createClaim(j);
  return j;
}

/**
 * Time travel for the warranty: no API can age a warranty, so this moves its
 * end date into the past directly in the QA database. Used only to reach the
 * "warranty expired" state; the rule itself is still asserted through the API/UI.
 */
export function expireWarranty(unitId: string) {
  const db = process.env.E2E_PROJECT_DB ?? "GPIA_Project_QA";
  const server = process.env.E2E_SQL_SERVER ?? ".\\SQLEXPRESS";
  execFileSync(
    "sqlcmd",
    ["-S", server, "-d", db, "-I", "-b", "-Q", `SET NOCOUNT ON; UPDATE Warranties SET StartsAt = DATEADD(month,-30,GETUTCDATE()), EndsAt = DATEADD(day,-1,GETUTCDATE()) WHERE UnitId = '${unitId}'`],
    { stdio: "pipe" },
  );
}

