import { expect, request, test as setup } from "@playwright/test";
import { ACCOUNTS, AUTH_API, E2E_PASSWORD, ROLE_PROJECTS, type RoleKey } from "./support/accounts";
import { loginRaw, session } from "./support/api";

/**
 * 1. Provisions the accounts the QA database lacks (second buyer, tech lead)
 *    through the real admin endpoint.
 * 2. Signs each UI role in through the login form and saves its storageState.
 */

setup("provision missing accounts", async () => {
  const admin = await session("globalAdmin");
  const ctx = await request.newContext({ extraHTTPHeaders: { Authorization: `Bearer ${admin.token}` } });
  try {
    for (const account of Object.values(ACCOUNTS)) {
      if (!account.provision) continue;
      const probe = await ctx.post(`${AUTH_API}/api/User/login`, { data: { userName: account.userName, password: E2E_PASSWORD } });
      const body = probe.ok() ? await probe.json() : null;
      if (body?.isAutheticated) {
        expect(body.roles, `${account.email} roles`).toContain(account.role);
        continue;
      }
      const res = await ctx.post(`${AUTH_API}/api/User/admin-create`, {
        data: {
          email: account.email,
          firstName: account.provision.firstName,
          lastName: account.provision.lastName,
          password: E2E_PASSWORD,
          phoneNumber: account.provision.phone,
          role: account.role,
        },
      });
      expect(res.status(), `admin-create ${account.email}: ${await res.text()}`).toBeLessThan(300);
    }
  } finally {
    await ctx.dispose();
  }
});

for (const role of ROLE_PROJECTS) {
  setup(`sign in ${role.key}`, async ({ page }) => {
    const account = ACCOUNTS[role.key as RoleKey];
    // Fails loudly if the account is missing or carries the wrong role.
    const probe = await loginRaw(account.userName);
    expect(probe.roles, `${account.email} must carry ${account.role}`).toContain(account.role);

    await page.goto("/login");
    await page.getByLabel("Email").fill(account.userName);
    await page.getByLabel("Mot de passe").fill(E2E_PASSWORD);
    await page.getByRole("button", { name: /connexion|se connecter/i }).click();
    await expect(page).not.toHaveURL(/\/login/);
    const token = await page.evaluate(() => localStorage.getItem("gpia_token"));
    expect(token, "token stored after login").toBeTruthy();
    await page.context().storageState({ path: role.storageState });
  });
}

