 * appointment history, and documents. Every call here resolves to the
 * signed-in buyer's own data only (GetMyReservationsQuery, and the API-side
 * scoping already enforced on FinalVisits/Notary/Payments reads).
 */
export default function BuyerFileDetailPage() {
  const { id = "" } = useParams();
  const [reservation, setReservation] = useState<Reservation | null | undefined>(undefined);
  const [title, setTitle] = useState<UnitTitleView | null>(null);
  const [notaryAppointments, setNotaryAppointments] = useState<NotaryAppointment[]>([]);

  useEffect(() => {
    let cancelled = false;

    reservationsApi.getMine().then((mine) => {
      if (cancelled) return;
      setReservation(mine.find((r) => r.id === id) ?? null);
    });

    return () => {
      cancelled = true;
    };
  }, [id]);

  useEffect(() => {
    if (!reservation) return;
    constructionApi.getUnitTitle(reservation.unitId).then(setTitle).catch(() => setTitle(null));
    notaryApi
      .listAppointments({ pageSize: 20 })
      .then((res) => setNotaryAppointments(res.data.filter((a) => a.reservationId === reservation.id)))
      .catch(() => setNotaryAppointments([]));
  }, [reservation]);

  if (reservation === undefined) return <Loading />;
  if (reservation === null) {
    return (
      <div>
        <PageHeader title="Dossier introuvable" />
        <Card>
          <p className="muted">
            Ce dossier n'existe pas ou ne vous appartient pas. <Link to="/my/properties">Retour à mes biens</Link>
          </p>
        </Card>
      </div>
    );
  }

  const canRequestFinalVisit = reservation.status === "APPROVED" || reservation.status === "CONVERTED";

  return (
    <div>
      <PageHeader
        title={reservation.unitDetails ?? `Bien ${reservation.unitId.slice(0, 8)}`}
        subtitle={`Réservé le ${formatDate(reservation.reservationDate)}`}
        actions={
          <Link to="/my/properties" className="btn btn-ghost">
            ← Mes biens
          </Link>
        }
      />

      <div className="stat-grid">
        <Card className="stat-card">
          <span className="stat-label">Statut</span>
          <span className="stat-value">
            <StatusBadge status={reservation.status} label={RESERVATION_STATUS_LABEL[reservation.status]} />
          </span>
        </Card>
        <Card className="stat-card">
          <span className="stat-label">Prix</span>
          <span className="stat-value">{formatMAD(reservation.totalPropertyPrice)}</span>
        </Card>
        {title && (
          <Card className="stat-card">
            <span className="stat-label">Titre foncier</span>
            <span className="stat-value">
              <StatusBadge status={title.status} label={TITLE_STATUS_LABEL[title.status]} />
            </span>
          </Card>
        )}
      </div>

      <BuyerPaymentSummary reservationId={reservation.id} />

      {canRequestFinalVisit && <FinalVisitPanel reservationId={reservation.id} />}

      <BuyerFinalVisitReportCard reservationId={reservation.id} />

      <BuyerHandoverCard reservationId={reservation.id} />

      {notaryAppointments.length > 0 && (
        <Card>
          <h3>Rendez-vous notaire</h3>
          <Table
            keyField={(a) => a.id}
            rows={notaryAppointments}
            columns={[
              { header: "Date", render: (a) => formatDateTime(a.appointmentDate) },
              { header: "Statut", render: (a) => <StatusBadge status={a.status} /> },
              { header: "Résultat", render: (a) => a.outcome ?? "-" },
