1	import { execFileSync } from "node:child_process";
2	import { Api } from "./api";
3	import type { RoleKey } from "./accounts";
4	
5	/**
6	 * Business-state fixtures built through the API, so a UI test only exercises
7	 * its own rule and never re-drives the whole upstream journey in the browser.
8	 *
9	 * Every helper creates fresh data (unique `e2e-…` names): tests never share a
10	 * project, unit or reservation, and never depend on execution order.
11	 */
12	
13	export const uid = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
14	
15	const iso = (d: Date) => d.toISOString().slice(0, 19);
16	const daysFromNow = (days: number, hour = 10) => {
17	  const d = new Date();
18	  d.setDate(d.getDate() + days);
19	  d.setHours(hour, 0, 0, 0);
20	  return d;
21	};
22	
23	/** Backend enums are serialised as integers. */
24	export const MilestoneStatus = { NotStarted: 0, InProgress: 1, Completed: 2 } as const;
25	export const AppointmentStatus = { Requested: 0, Confirmed: 1, RescheduleProposed: 2, Rejected: 3, Cancelled: 4, Completed: 5, NoShow: 6 } as const;
26	export const ClaimStatus = { Submitted: 0, UnderReview: 1, MoreInfoRequired: 2, Assigned: 3, InProgress: 4, WaitingCustomer: 5, Resolved: 6, Rejected: 7, Cancelled: 8, Closed: 9 } as const;
27	
28	export type Phase = "SUR_PLAN" | "EN_LIVRAISON" | "FINALISE";
29	
30	export interface ProjectFixture {
31	  id: string;
32	  name: string;
33	  immeubleId: string;
34	  floorId: string;
35	  unitIds: string[];
36	  milestoneIds: string[];
37	  warrantyMonths: number;
38	}
39	
40	export interface JourneyFixture {
41	  project: ProjectFixture;
42	  unitId: string;
43	  reservationId: string;
44	  buyer: RoleKey;
45	  saleId?: string;
46	  notaryAppointmentId?: string;
47	  handoverId?: string;
48	  warrantyId?: string;
49	  claimId?: string;
50	  finalVisitAppointmentId?: string;
51	  finalVisitReportId?: string;
52	}
53	
54	const admin = () => Api.as("globalAdmin");
55	
56	/**
57	 * createProject(status, constructionPct).
58	 *
59	 * The project is created SUR_PLAN with two weighted milestones; `constructionPct`
60	 * of the weight is marked completed. Reaching EN_LIVRAISON requires 100 % and
61	 * goes through the real `complete` command; FINALISE through `finalize`.
62	 * Memberships attach the agent, notary, technician, tech lead and project admin
63	 * accounts so their perimeter covers this project (and only this one).
64	 */
65	export async function createProject(
66	  opts: {
67	    phase?: Phase;
68	    constructionPct?: number;
69	    warrantyMonths?: number;
70	    units?: number;
71	    members?: RoleKey[];
72	  } = {},
73	): Promise<ProjectFixture> {
