import { expect, test } from "@playwright/test";
import { Api, expectRefused } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, openReservation } from "./support/ui";

/**
 * Scope 1 — Accès et rôles.
 *
 * Every test runs in the Playwright project of the role in its tag, with that
 * role's session. Preconditions are built through the API (support/state.ts);
 * every mutation is verified by re-reading the API, never the optimistic UI.
 */

// ---------------------------------------------------------------------------
// Agent commercial
// ---------------------------------------------------------------------------
test.describe("Agent commercial", { tag: "@agent" }, () => {
  test("agent_cannot_create_project", async ({ page }) => {
    await page.goto("/admin/projects");
    await expect(page.getByRole("heading", { name: "Projets" })).toBeVisible();
    await expect(page.getByRole("button", { name: "+ Nouveau projet" })).toHaveCount(0);

    const agent = await Api.as("agent");
    const name = `e2e-forbidden-${st.uid()}`;
    await expectRefused(await agent.raw("POST", "/api/Projects", { name, location: "Casablanca", images: [] }), [403], "agent POST /api/Projects");

    const admin = await Api.as("globalAdmin");
    const all = await admin.get<{ data: { name: string }[] }>("/api/Projects?PageSize=1000");
    expect(all.data.map((p) => p.name)).not.toContain(name);
  });

  test("agent_cannot_edit_project", async ({ page }) => {
    const p = await st.createProject();
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("heading", { name: p.name })).toBeVisible();
    await expect(page.getByRole("button", { name: "Modifier" })).toHaveCount(0);
    await expect(page.getByRole("button", { name: "Supprimer" })).toHaveCount(0);

    const agent = await Api.as("agent");
    await expectRefused(
      await agent.raw("PUT", `/api/Projects/${p.id}`, { id: p.id, name: "piraté", location: "X", images: [], warrantyMonths: 99 }),
      [403],
      "agent PUT project",
    );
    const after = await st.getProject(p.id);
    expect(after.name).toBe(p.name);
    expect(after.warrantyMonths).toBe(p.warrantyMonths);
  });

  test("agent_can_create_and_manage_reservation", async ({ page }) => {
    const p = await st.createProject();
    const lastName = `Agent${st.uid()}`;
    await page.goto("/admin/reservations");
    await page.getByRole("button", { name: "Créer une réservation" }).click();
    const dialog = page.getByRole("dialog", { name: "Créer une réservation" });
    await dialog.getByLabel("Projet").selectOption({ label: p.name });
    await dialog.getByLabel("Immeuble").selectOption({ label: `${p.name}-B1` });
    const unitSelect = dialog.getByLabel("Bien disponible");
    await expect(unitSelect.locator("option")).toHaveCount(3); // placeholder + 2 units
    await unitSelect.selectOption({ index: 1 });
    await dialog.getByLabel("Prénom de l'acheteur").fill("Nadia");
    await dialog.getByLabel("Nom de l'acheteur").fill(lastName);
    await dialog.getByLabel("CIN").first().fill(`E2E${st.uid().slice(0, 6)}`);
    await dialog.getByLabel("E-mail").first().fill(`${lastName.toLowerCase()}@example.test`);
    await dialog.getByLabel("Téléphone").first().fill("+212600000001");
    await dialog.getByLabel("Prix total (MAD)").fill("1250000");
    await dialog.getByLabel("Montant de réservation (MAD)").fill("125000");
    await dialog.getByLabel(/Enregistrer en brouillon/).check();
    await dialog.getByRole("button", { name: "Créer la réservation" }).click();
    await expect(dialog).toBeHidden();

    // Persisted as DRAFT.
    const agent = await Api.as("agent");
    const list = await agent.get<{ data: { id: string; lastName: string; status: number | string; phoneNumber: string }[] }>(
      "/api/Reservations/list?PageSize=1000",
    );
    const created = list.data.find((r) => r.lastName === lastName);
    expect(created, "reservation persisted").toBeTruthy();

    // Manage: correct the draft, then submit it.
    const detail = await openReservation(page, p.name, lastName);
    await detail.getByRole("button", { name: "Corriger la réservation" }).click();
    await detail.getByLabel("Téléphone").fill("+212600000999");
    await detail.getByRole("button", { name: "Enregistrer" }).click();
    await expect(detail.getByRole("button", { name: "Soumettre" })).toBeVisible();
    await detail.getByRole("button", { name: "Soumettre" }).click();

    await expect
      .poll(async () => (await agent.get<{ status: string; phoneNumber: string }>(`/api/Reservations/${created!.id}`)).status)
      .toMatch(/^(Pending|SUBMITTED|0)$/i);
    const reloaded = await agent.get<{ phoneNumber: string }>(`/api/Reservations/${created!.id}`);
    expect(reloaded.phoneNumber).toBe("+212600000999");
  });

  test("agent_can_create_and_manage_final_visit", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "APPROVED" });
    await st.setConstructionPct(p, 100);
    await st.completeProject(p);
    await st.createFinalVisit(j, "REQUESTED", { pastStart: true });

    await page.goto(`/admin/units/${j.unitId}`);
    await page.getByRole("button", { name: "Confirmer", exact: true }).click();
    await page.getByRole("button", { name: "Marquer réalisée" }).click();
    await page.getByRole("button", { name: "Saisir un rapport de visite" }).click();
    await page.getByLabel("État général").fill("Conforme");
    await page.getByLabel("Observations").fill("Visite E2E sans réserve");
    await page.getByRole("button", { name: "Envoyer le rapport" }).click();

    const agent = await Api.as("agent");
    await expect
      .poll(async () => {
        const c = await agent.get<{ currentReport?: { observations?: string; status?: string } | null; currentAppointment?: { status: string } | null }>(
          `/api/final-visits/reservations/${j.reservationId}/case`,
        );
        return c.currentReport?.observations ?? null;
      })
      .toBe("Visite E2E sans réserve");
  });

  test("agent_can_create_draft_sale", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    acceptDialogs(page);
    const detail = await openReservation(page, j.project.name, "E2E-buyer");
    await detail.getByRole("button", { name: "Créer une vente" }).click();
    const saleDialog = page.getByRole("dialog", { name: "Créer une vente" });
    await saleDialog.getByLabel(/Notes/).fill("Vente créée par l'agent (E2E)");
    await saleDialog.locator("button[type=submit]").click();
    await expect(saleDialog).toBeHidden();

    const agent = await Api.as("agent");
    const sale = await agent.get<{ status: string; notes: string }>(`/api/sales/by-reservation/${j.reservationId}`);
    expect(sale.status).toBe("Draft");
    expect(sale.notes).toBe("Vente créée par l'agent (E2E)");
  });

  test("agent_can_create_or_confirm_notary_appointment_within_scope", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    const outOfScope = await st.journey("FINAL_VISIT", { members: ["agentOther", "notary", "technician", "techLead", "projectAdmin"] });
    const notary = await Api.as("notary");

    await page.goto("/admin/notary-appointments");
    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
    const dialog = page.getByRole("dialog", { name: "Demander un rendez-vous notarié" });
    const dossier = dialog.getByLabel("Dossier (réservation approuvée)");
    await expect(dossier.locator(`option[value="${j.reservationId}"]`)).toHaveCount(1);
    // Outside the agent's perimeter: not offered.
    await expect(dossier.locator(`option[value="${outOfScope.reservationId}"]`)).toHaveCount(0);
    await dossier.selectOption(j.reservationId);
    await dialog.getByLabel("Notaire affecté").selectOption(notary.userId);
    const when = new Date(Date.now() + (30 + Math.floor(Math.random() * 500)) * 86400000);
    when.setHours(9 + Math.floor(Math.random() * 8), 0, 0, 0);
    const local = new Date(when.getTime() - when.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    await dialog.getByLabel("Date et heure").fill(local);
    await dialog.getByRole("button", { name: /Demander|Envoyer|Valider/ }).first().click();
    await expect(dialog).toBeHidden();

    const agent = await Api.as("agent");
    const mine = async () =>
      (await agent.get<{ data: { id: string; reservationId: string; status: string }[] }>("/api/NotaryAppointments?PageSize=500")).data.filter(
        (a) => a.reservationId === j.reservationId,
      );
    await expect.poll(async () => (await mine()).length).toBe(1);
    const appointment = (await mine())[0];

    // Confirm it from the list.
    const row = page.getByRole("row").filter({ hasText: "E2E-buyer" }).filter({ has: page.getByRole("button", { name: "Confirmer" }) });
    await page.reload();
    await page
      .getByRole("row")
      .filter({ has: page.getByRole("button", { name: "Confirmer" }) })
      .filter({ hasText: new RegExp(when.getFullYear().toString()) })
      .first();
    void row;
    const confirmResponse = page.waitForResponse((r) => r.url().includes(`/api/NotaryAppointments/${appointment.id}`) && r.request().method() === "PUT");
    await page.evaluate(() => void 0);
    // The row for this appointment is identified through its id-bearing request.
    const buttons = page.getByRole("button", { name: "Confirmer" });
    const count = await buttons.count();
    let confirmed = false;
    for (let i = 0; i < count && !confirmed; i++) {
      const [req] = await Promise.all([
        page.waitForRequest((r) => r.method() === "PUT" && r.url().includes("/api/NotaryAppointments/"), { timeout: 5000 }).catch(() => null),
        buttons.nth(i).click(),
      ]);
      if (req?.url().includes(appointment.id)) confirmed = true;
    }
    expect(confirmed, "confirm button for the created appointment").toBe(true);
    expect((await confirmResponse).status()).toBe(200);
    const after = await agent.get<{ status: string }>(`/api/NotaryAppointments/${appointment.id}`);
    expect(after.status).toMatch(/^Confirmed$/i);

    // The same agent is refused on a dossier outside their perimeter.
    await expectRefused(
      await agent.raw("POST", "/api/NotaryAppointments", {
        reservationId: outOfScope.reservationId,
        appointmentDate: when.toISOString(),
        status: "Scheduled",
      }),
      [403],
      "agent books out-of-scope notary appointment",
    );
  });

  test("agent_blocked_on_project_outside_his_scope", async ({ page }) => {
    const other = await st.createProject({ members: ["agentOther", "projectAdmin"] });
    await page.goto("/admin/projects");
    await expect(page.getByRole("heading", { name: "Projets" })).toBeVisible();
    await expect(page.getByRole("link", { name: other.name })).toHaveCount(0);

    await page.goto(`/admin/projects/${other.id}`);
    await expect(page.getByRole("heading", { name: other.name })).toHaveCount(0);

    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("GET", `/api/Projects/${other.id}`), [403, 404], "agent GET out-of-scope project");
    const list = await agent.get<{ data: { id: string }[] }>("/api/Projects?PageSize=1000");
    expect(list.data.map((x) => x.id)).not.toContain(other.id);
  });
});

// ---------------------------------------------------------------------------
// Administrateur de projet
// ---------------------------------------------------------------------------
test.describe("Administrateur de projet", { tag: "@projectAdmin" }, () => {
  test("project_admin_can_crud_project_district_property_type", async ({ page }) => {
    acceptDialogs(page);
    const padmin = await Api.as("projectAdmin");
    const suffix = st.uid();

    // --- Project: create, read, update, delete
    const projectName = `e2e-padmin-${suffix}`;
    await page.goto("/admin/projects");
    await page.getByRole("button", { name: "+ Nouveau projet" }).click();
    const create = page.getByRole("dialog", { name: "Nouveau projet" });
    await create.getByLabel("Nom").fill(projectName);
    await create.getByLabel("Localisation").fill("Rabat");
    await create.getByLabel("Garantie (mois)").fill("18");
    await create.getByRole("button", { name: "Créer" }).click();
    await expect(create).toBeHidden();
    await page.getByRole("link", { name: projectName }).click();
    await expect(page.getByRole("heading", { name: projectName })).toBeVisible();
    const projectId = page.url().split("/").pop()!;
    expect((await padmin.get<{ name: string; warrantyMonths: number }>(`/api/Projects/${projectId}`)).warrantyMonths).toBe(18);

    await page.getByRole("button", { name: "Modifier" }).click();
    const edit = page.getByRole("dialog", { name: "Modifier le projet" });
    await edit.getByLabel("Nom").fill(`${projectName}-v2`);
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    await expect.poll(async () => (await padmin.get<{ name: string }>(`/api/Projects/${projectId}`)).name).toBe(`${projectName}-v2`);

    await page.reload();
    await page.getByRole("button", { name: "Supprimer" }).click();
    await expect(page).toHaveURL(/\/admin\/projects$/);
    const admin = await Api.as("globalAdmin");
    await expectRefused(await admin.raw("GET", `/api/Projects/${projectId}`), [404], "deleted project");

    // --- District (quartier): create, update, delete
