      .poll(async () => (await agent.get<{ currentAppointment?: { status: string } | null }>(`/api/final-visits/reservations/${j.reservationId}/case`)).currentAppointment?.status ?? null)
      .toMatch(/^(REQUESTED|Requested)$/);
  });

  test("buyer_can_create_notary_appointment_request", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    await page.goto(`/my/properties/${j.reservationId}`);
    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
    const when = new Date(Date.now() + (20 + Math.floor(Math.random() * 400)) * 86400000);
    when.setHours(11, 0, 0, 0);
    const local = new Date(when.getTime() - when.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    await page.getByLabel("Date et heure souhaitées").fill(local);
    await page.getByRole("button", { name: "Envoyer la demande" }).click();
    await expect(page.getByRole("heading", { name: "Rendez-vous notaire" })).toBeVisible();

    const buyer = await Api.as("buyer", true);
    const appts = await buyer.get<{ data: { reservationId: string; status: string }[] }>("/api/NotaryAppointments?PageSize=500");
    const created = appts.data.filter((a) => a.reservationId === j.reservationId);
    expect(created).toHaveLength(1);
    expect(created[0].status).toMatch(/^Requested$/i);
  });

  test("buyer_can_create_claim_only_within_warranty_period", async ({ page }) => {
    test.setTimeout(180_000);
    const delivered = await st.journey("DELIVERED");
    const expired = await st.journey("DELIVERED");
    st.expireWarranty(expired.unitId);
    const notDelivered = await st.journey("SOLD");
    const buyer = await Api.as("buyer", true);

    // Within warranty: accepted through the UI and persisted.
    const title = `Fissure ${st.uid()}`;
    await page.goto("/my/sav");
    await page.getByRole("button", { name: "Nouvelle réclamation" }).click();
    await page.getByLabel("Bien concerné").selectOption(delivered.unitId);
    await page.getByLabel("Titre").fill(title);
    await page.getByLabel("Description").fill("Fissure dans le salon (E2E)");
    await page.getByRole("button", { name: "Envoyer" }).click();
    await expect(page.getByRole("row").filter({ hasText: title })).toHaveCount(1);
    const claims = await buyer.get<{ data: { title: string }[] }>("/api/after-sales/claims/mine");
    expect(claims.data.map((c) => c.title)).toContain(title);

    // Warranty expired: refused, nothing persisted.
    const expiredTitle = `Expirée ${st.uid()}`;
    await page.getByRole("button", { name: "Nouvelle réclamation" }).click();
    await page.getByLabel("Bien concerné").selectOption(expired.unitId);
    await page.getByLabel("Titre").fill(expiredTitle);
    await page.getByLabel("Description").fill("Hors garantie (E2E)");
    await page.getByRole("button", { name: "Envoyer" }).click();
    await expect(page.locator(".form-error")).toContainText(/garantie/i);

    // Not yet delivered: refused at the API.
    await expectRefused(
      await buyer.raw("POST", "/api/after-sales/claims", { unitId: notDelivered.unitId, title: "Non livré", description: "x", category: 0, priority: 1 }),
      [409, 422],
      "claim on undelivered unit",
    );
    const after = await buyer.get<{ data: { title: string }[] }>("/api/after-sales/claims/mine");
    expect(after.data.map((c) => c.title)).not.toContain(expiredTitle);
    expect(after.data.map((c) => c.title)).not.toContain("Non livré");
  });
});

