    expect(list.data.map((c) => c.id)).toContain(assignedToMe.claimId);
    expect(list.data.map((c) => c.id)).not.toContain(assignedToOther.claimId);
    expect(list.data.every((c) => c.assignedAgentId === tech.userId)).toBe(true);
