  test("buyer_can_create_notary_appointment_request", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    await page.goto(`/my/properties/${j.reservationId}`);
    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
    const when = new Date(Date.now() + (20 + Math.floor(Math.random() * 400)) * 86400000);
    when.setHours(11, 0, 0, 0);
    const local = new Date(when.getTime() - when.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    await page.getByLabel("Date et heure souhaitées").fill(local);
