    const res = await fetch(`${config.projectApiUrl}/api/Reservations/documents/${documentId}/content`, {
      headers: getToken() ? { Authorization: `Bearer ${getToken()}` } : {},
    });
    if (!res.ok) {
      throw new ApiError(res.status, null, await res.text().catch(() => ""));
    }
    return res.blob();
  },
  async deleteDocument(documentId) {
    // N25 — the controller returns Ok(response.Message): a bare text/plain
    // string, not JSON. projectFetch always tries JSON.parse on a non-empty
    // body, so that parse threw here even on a real 200, and the thrown
    // error was caught upstream and shown as a delete failure — the delete
    // had actually already succeeded server-side. deleteRaw skips the parse.
    await projectFetchText(`/api/Reservations/documents/${documentId}`, { method: "DELETE" });
  },
};

