const unitsForType = (typeId: string) => {
  if (!typeId) return availableUnits ?? [];
  const type = typeBiens?.find((t) => String(t.id) === typeId);
  if (!type || type.nbrChambre == null) return availableUnits ?? [];
  return (availableUnits ?? []).filter((unit) => unit.numberOfBedrooms === type.nbrChambre);
};

const offeredTypes = (typeBiens ?? []).filter(
  (type) => type.nbrChambre != null && unitsForType(String(type.id)).length > 0
);

