function unitLabel(unit: Unit) {
  const parts = [unit.unitNumber];
  if (unit.floor && !unit.unitNumber?.startsWith(unit.floor)) parts.push(unit.floor);
  if (unit.totalSurface != null) parts.push(`${unit.totalSurface} m²`);
  if (unit.numberOfBedrooms != null) parts.push(`${unit.numberOfBedrooms} ch.`);
