async function act(
  action: "approve" | "reject" | "cancel" | "requestChanges" | "submit",
  res: Reservation
) {
  // §12.2/§12.3 — the motif is mandatory on every negative decision, so it is
  // asked for rather than fabricated: a hardcoded "Refusé par l'administrateur"
  // satisfies the field and tells the agent nothing.
  const REASON_PROMPTS: Partial<Record<typeof action, string>> = {
    requestChanges: "Que doit corriger l'agent ?",
    reject: "Motif du refus ?",
    cancel: "Motif de l'annulation ?",
  };
  let reason = "";
  const promptLabel = REASON_PROMPTS[action];
  if (promptLabel) {
    reason = window.prompt(promptLabel)?.trim() ?? "";
    if (!reason) return;
  }

  setActionError(null);
  setActing(true);
  try {
    if (action === "approve") await reservationsApi.approve(res.id);
    if (action === "reject") await reservationsApi.reject(res.id, reason);
    if (action === "cancel") await reservationsApi.cancel(res.id, reason);
    if (action === "requestChanges") await reservationsApi.requestChanges(res.id, reason);
    if (action === "submit") await reservationsApi.submit(res.id);
    setSelected(null);
    reload();
  } catch (err) {
    // Branch on the stable business code, never on the message (spec §31.7).
    if (err instanceof ApiError) {
      if (err.is("INVALID_STATUS_TRANSITION")) {
        setActionError("Cette action n'est plus possible : le statut a changé. Rechargez la page.");
      } else if (err.is("UNIT_NOT_AVAILABLE")) {
        setActionError("Le bien n'est plus disponible.");
      } else if (err.is("RESOURCE_VERSION_CONFLICT")) {
        setActionError("La réservation a été modifiée entre-temps. Rechargez puis réessayez.");
      } else {
        setActionError(err.message);
      }
    } else {
      setActionError("Une erreur inattendue est survenue.");
    }
  } finally {
    setActing(false);
  }
}

