test.describe("Validation (admin projet)", { tag: "@projectAdmin" }, () => {
  test("approval_blocked_without_required_documents", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "SUBMITTED" });
    // The project starts requiring a piece after submission.
    const padmin = await Api.as("projectAdmin");
    await padmin.put(`/api/Projects/${p.id}/document-requirements`, { projectId: p.id, documentType: "CIN", labelFr: "CIN ou passeport", isRequired: true, sequenceNo: 1 });

    const detail = await openReservation(page, p.name, j.buyerLastName);
    await detail.getByRole("button", { name: "Approuver" }).click();
    await expect(detail.locator(".form-error")).toContainText(/CIN|pièce|document/i);
    expect((await reservation(j.reservationId)).status).toBe(STATUS.SUBMITTED);

    await expectRefused(
      await padmin.raw("POST", `/api/Reservations/${j.reservationId}/approve`, { reservationId: j.reservationId, adminUserId: padmin.userId, documents: [] }),
      [422],
      "approve without documents",
    );
    expect((await reservation(j.reservationId)).status).toBe(STATUS.SUBMITTED);
  });

  test("required_documents_are_configurable_per_project", async ({ page }) => {
    acceptDialogs(page);
    // Default set on a new project.
    const withDefaults = await st.createProject({ documentRequirements: "default" });
    const padmin = await Api.as("projectAdmin");
    const defaults = await padmin.get<{ documentType: string; isRequired: boolean }[]>(`/api/Projects/${withDefaults.id}/document-requirements`);
    expect(defaults.map((d) => d.documentType).sort()).toEqual([...st.DEFAULT_DOCUMENT_TYPES].sort());
    expect(defaults.every((d) => d.isRequired)).toBe(true);

    // Another project reconfigured through the UI: keep CIN, drop the other two, add a salary certificate.
    const custom = await st.createProject({ documentRequirements: "default" });
    await page.goto(`/admin/projects/${custom.id}`);
    const panel = page.locator(".card").filter({ has: page.getByRole("heading", { name: "Pièces exigées à la réservation" }) });
    for (const label of ["Contrat ou bulletin de réservation signé", "Justificatif de paiement de la réservation"]) {
      await panel.getByRole("row").filter({ hasText: label }).getByRole("button", { name: "Retirer" }).click();
      await expect(panel.getByRole("row").filter({ hasText: label })).toHaveCount(0);
    }
    await panel.getByLabel("Code").fill("ATTESTATION_SALAIRE");
    await panel.getByLabel("Libellé").fill("Attestation de salaire");
    await panel.getByRole("button", { name: "Ajouter" }).click();
    await expect(panel.getByRole("row").filter({ hasText: "Attestation de salaire" })).toHaveCount(1);

    const configured = await padmin.get<{ documentType: string }[]>(`/api/Projects/${custom.id}/document-requirements`);
    expect(configured.map((d) => d.documentType).sort()).toEqual(["ATTESTATION_SALAIRE", "CIN"]);

    // The checklist of a file on that project follows the new configuration.
    const j = await st.createReservation(custom, { state: "DRAFT" });
    const agent = await Api.as("agent");
    const checklist = await agent.get<{ items: { documentType: string }[] }>(`/api/Reservations/${j.reservationId}/document-checklist`);
    expect(checklist.items.map((i) => i.documentType).sort()).toEqual(["ATTESTATION_SALAIRE", "CIN"]);
    await st.uploadReservationDocument(j.reservationId, "CIN");
    await st.uploadReservationDocument(j.reservationId, "ATTESTATION_SALAIRE");
    await agent.post(`/api/Reservations/${j.reservationId}/submit`, { reservationId: j.reservationId });
    expect((await reservation(j.reservationId)).status).toBe(STATUS.SUBMITTED);
  });
});

