        buildings: [
          { suffix: "A1", floors: [{ name: "RDC", units: [{ bedrooms: 2 }] }, { name: "ETAGE1", units: [{ bedrooms: 3 }, { bedrooms: 2 }] }] },
          { suffix: "A2", floors: [{ name: "RDC", units: [{ bedrooms: 2 }] }] },
        ],
      },
    });
    const b = await st.createProject({ layout: { buildings: [{ suffix: "B1", floors: [{ name: "RDC", units: [{ bedrooms: 2 }] }] }] } });

    const dialog = await openCreateForm(page);
    const project = dialog.getByLabel("Projet");
    const immeuble = dialog.getByLabel("Immeuble");
    const floor = dialog.getByLabel("Étage");
    const type = dialog.getByLabel("Type de bien");
    const unit = dialog.getByLabel("Bien disponible");
    const unitOptions = () => unit.locator("option").filter({ hasNotText: "Sélectionner un bien" });

    // Project A → its two buildings only.
    await project.selectOption({ label: a.name });
    await expect(immeuble.locator("option").filter({ hasText: "e2e-" })).toHaveText([`${a.name}-A1`, `${a.name}-A2`]);

    // Building A1 → floors RDC / ETAGE1, all 3 units.
    await immeuble.selectOption({ label: `${a.name}-A1` });
    await expect(floor.locator("option").filter({ hasNotText: "Tous les étages" })).toHaveText(["ETAGE1", "RDC"]);
    await expect(unitOptions()).toHaveCount(3);

    // Floor ETAGE1 → only its units; types narrowed to what that floor offers.
    await floor.selectOption("ETAGE1");
    await expect(unitOptions()).toHaveCount(2);
    await expect(type.locator("option", { hasText: t3 })).toHaveCount(1);

    // Type T3 → the single 3-bedroom unit, then select it.
    await type.selectOption({ label: new RegExp(`^${t3}`) as unknown as string });
    await expect(unitOptions()).toHaveCount(1);
    await expect(unitOptions().first()).toContainText("ETAGE1-1");
    await unit.selectOption({ index: 1 });
    await expect(unit).not.toHaveValue("");

    // Changing the floor resets type and unit.
    await floor.selectOption("RDC");
    await expect(type).toHaveValue("");
    await expect(unit).toHaveValue("");
    await expect(unitOptions()).toHaveCount(1);
    await expect(unitOptions().first()).toContainText("RDC-1");

    // Changing the building resets floor, type and unit (A2 has one floor: no floor picker).
    await unit.selectOption({ index: 1 });
    await immeuble.selectOption({ label: `${a.name}-A2` });
    await expect(floor).toHaveCount(0);
    await expect(unit).toHaveValue("");
    await expect(unitOptions()).toHaveCount(1);

    // Changing the project resets everything below it.
    await project.selectOption({ label: b.name });
    await expect(immeuble).toHaveValue("");
    await expect(immeuble.locator("option").filter({ hasText: "e2e-" })).toHaveText([`${b.name}-B1`]);
    await expect(unit).toHaveCount(0);
  });

  test("reservation_unit_list_shows_only_available_units", async ({ page }) => {
    const p = await st.createProject({ units: 4 });
    await st.createReservation(p, { state: "APPROVED", unitIndex: 0 }); // RESERVED
    await st.createReservation(p, { state: "SUBMITTED", unitIndex: 1 }); // HOLD_PENDING_APPROVAL
    await st.createReservation(p, { state: "DRAFT", unitIndex: 2 }); // a draft does not block the unit (§12.1)

    const dialog = await openCreateForm(page);
    await dialog.getByLabel("Projet").selectOption({ label: p.name });
    await dialog.getByLabel("Immeuble").selectOption({ label: `${p.name}-B1` });
    const options = dialog.getByLabel("Bien disponible").locator("option").filter({ hasNotText: "Sélectionner un bien" });
    await expect(options).toHaveCount(2);
    await expect(options.nth(0)).toContainText(p.units[2].unitNumber);
    await expect(options.nth(1)).toContainText(p.units[3].unitNumber);

    // Cross-check with the server's own statuses.
    const admin = await Api.as("globalAdmin");
    const units = await admin.all<{ id: string; status: string }>(`/api/Immeuble/by-immeuble?ImmeubleId=${p.immeubleId}`);
    const statusOf = (id: string) => units.find((u) => u.id === id)?.status;
    expect(statusOf(p.units[0].id)).toMatch(/RESERVED/i);
    expect(statusOf(p.units[1].id)).toMatch(/HOLD/i);
  });
});

test.describe("Documents", { tag: "@agent" }, () => {
  test("documents_can_be_uploaded_during_creation", async ({ page }) => {
    const p = await st.createProject({ documentRequirements: "default" });
    const lastName = `Docs${st.uid()}`;
    const dialog = await openCreateForm(page);
    await dialog.getByLabel("Projet").selectOption({ label: p.name });
    await dialog.getByLabel("Immeuble").selectOption({ label: `${p.name}-B1` });
    await dialog.getByLabel("Bien disponible").selectOption({ index: 1 });
    await fillBuyer(dialog, lastName);
    await dialog.getByLabel("CIN ou passeport (obligatoire)").setInputFiles(pdf("cin.pdf"));
    await dialog.getByLabel("Contrat ou bulletin de réservation signé (obligatoire)").setInputFiles(pdf("contrat.pdf"));
    await dialog.getByLabel("Justificatif de paiement de la réservation (obligatoire)").setInputFiles(pdf("paiement.pdf"));
    await dialog.getByRole("button", { name: "Créer la réservation" }).click();
    await expect(dialog).toBeHidden();

    await expect.poll(orNull(async () => (await findByLastName(lastName))?.id ?? null)).not.toBeNull();
    const created = await reservation((await findByLastName(lastName))!.id);
    expect(created.documents).toHaveLength(3);
    expect(created.status).toBe(STATUS.SUBMITTED);
  });

  test("uploaded_documents_visible_in_detail_view", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "DRAFT" });
    await st.uploadReservationDocument(j.reservationId, "CIN", "agent", "piece-identite-e2e.pdf");

    const detail = await openReservation(page, p.name, j.buyerLastName);
    await expect(detail.getByRole("button", { name: "piece-identite-e2e.pdf" })).toBeVisible();
  });

  test("documents_can_be_added_and_deleted_in_detail_view", async ({ page }) => {
    acceptDialogs(page);
    const p = await st.createProject();
    const draft = await st.createReservation(p, { state: "DRAFT", unitIndex: 0 });

    const detail = await openReservation(page, p.name, draft.buyerLastName);
    await detail.getByLabel("Ajouter un document").setInputFiles(pdf("ajout-e2e.pdf"));
    await expect(detail.getByRole("button", { name: "ajout-e2e.pdf" })).toBeVisible();
    await expect.poll(async () => (await reservation(draft.reservationId)).documents.length).toBe(1);

    const item = detail.locator("li").filter({ has: page.getByRole("button", { name: "ajout-e2e.pdf" }) });
    await item.getByRole("button", { name: "Supprimer" }).click();
    await expect(detail.getByRole("button", { name: "ajout-e2e.pdf" })).toHaveCount(0);
    await expect.poll(async () => (await reservation(draft.reservationId)).documents.length).toBe(0);

    // On an approved file: adding stays possible, deleting is not offered and is refused by the API.
    const approved = await st.createReservation(p, { state: "APPROVED", unitIndex: 1 });
    const doc = await st.uploadReservationDocument(approved.reservationId, "OTHER", "agent", "approuve-e2e.pdf");
    await page.keyboard.press("Escape");
    const approvedDetail = await openReservation(page, p.name, approved.buyerLastName);
    await expect(approvedDetail.getByRole("button", { name: "approuve-e2e.pdf" })).toBeVisible();
    await expect(approvedDetail.locator("li").filter({ hasText: "approuve-e2e.pdf" }).getByRole("button", { name: "Supprimer" })).toHaveCount(0);
    await expect(approvedDetail.getByLabel("Ajouter un document")).toBeVisible();
    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("DELETE", `/api/Reservations/documents/${doc.id}`), [409], "delete document on approved file");
    expect((await reservation(approved.reservationId)).documents).toHaveLength(1);
  });

  test("document_upload_does_not_return_403", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "DRAFT" });
    const detail = await openReservation(page, p.name, j.buyerLastName);
    const [response] = await Promise.all([
      page.waitForResponse((r) => r.request().method() === "POST" && r.url().includes(`/api/Reservations/${j.reservationId}/documents`)),
      detail.getByLabel("Ajouter un document").setInputFiles(pdf("statut-http.pdf")),
    ]);
    expect(response.status(), await response.text()).toBe(200);
    await expect(detail.getByRole("button", { name: "statut-http.pdf" })).toBeVisible();
    await expect(detail.getByRole("alert")).toHaveCount(0);
  });

  test("documents_persist_server_side_after_reload", async ({ page, browser }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "DRAFT" });
    const detail = await openReservation(page, p.name, j.buyerLastName);
    await detail.getByLabel("Ajouter un document").setInputFiles(pdf("persiste-e2e.pdf"));
    await expect(detail.getByRole("button", { name: "persiste-e2e.pdf" })).toBeVisible();

    // A brand-new browser context: nothing local survives, only the server.
    const fresh = await browser.newContext({ storageState: storageStateFor("agent") });
    const freshPage = await fresh.newPage();
    const freshDetail = await openReservation(freshPage, p.name, j.buyerLastName);
    await expect(freshDetail.getByRole("button", { name: "persiste-e2e.pdf" })).toBeVisible();
    await fresh.close();

    const docs = (await reservation(j.reservationId)).documents;
    expect(docs.map((d) => d.fileName ?? d.name)).toContain("persiste-e2e.pdf");
  });
});

test.describe("Validation (agent)", { tag: "@agent" }, () => {
  test("draft_reservation_accepts_missing_documents", async ({ page }) => {
    const p = await st.createProject({ documentRequirements: "default" });
    const lastName = `Brouillon${st.uid()}`;
    const dialog = await openCreateForm(page);
    await dialog.getByLabel("Projet").selectOption({ label: p.name });
    await dialog.getByLabel("Immeuble").selectOption({ label: `${p.name}-B1` });
    await dialog.getByLabel("Bien disponible").selectOption({ index: 1 });
    await fillBuyer(dialog, lastName);
    await dialog.getByLabel(/Enregistrer en brouillon/).check();
    await dialog.getByRole("button", { name: "Créer la réservation" }).click();
    await expect(dialog).toBeHidden();

    await expect.poll(orNull(async () => (await findByLastName(lastName))?.id ?? null)).not.toBeNull();
    const created = await reservation((await findByLastName(lastName))!.id);
    expect(created.status).toBe(STATUS.DRAFT);
    expect(created.documents).toHaveLength(0);
  });

  test("submission_blocked_without_required_documents", async ({ page }) => {
    const p = await st.createProject({ documentRequirements: "default" });
    const j = await st.createReservation(p, { state: "DRAFT" });
    await st.uploadReservationDocument(j.reservationId, "CIN");

    const detail = await openReservation(page, p.name, j.buyerLastName);
    await expect(detail.getByText("Ce projet exige des pièces qui manquent encore")).toBeVisible();
    await detail.getByRole("button", { name: "Soumettre" }).click();
    await expect(detail.locator(".form-error")).toContainText(/pièce|document|Contrat/i);
    expect((await reservation(j.reservationId)).status).toBe(STATUS.DRAFT);

    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("POST", `/api/Reservations/${j.reservationId}/submit`, { reservationId: j.reservationId }), [422], "submit without documents");
    expect((await reservation(j.reservationId)).status).toBe(STATUS.DRAFT);
  });

  test("reservation_editable_before_approved", async ({ page }) => {
    const p = await st.createProject();
    const draft = await st.createReservation(p, { state: "DRAFT", unitIndex: 0 });
    const corrected = await st.createReservation(p, { state: "SUBMITTED", unitIndex: 1 });
    const admin = await Api.as("globalAdmin");
    await admin.post(`/api/Reservations/${corrected.reservationId}/request-changes`, { reservationId: corrected.reservationId, reason: "Pièce illisible (E2E)" });

    for (const [j, phone] of [[draft, "+212611111111"], [corrected, "+212622222222"]] as const) {
      const detail = await openReservation(page, p.name, j.buyerLastName);
      await detail.getByRole("button", { name: "Corriger la réservation" }).click();
      await detail.getByLabel("Téléphone").fill(phone);
      await detail.getByRole("button", { name: "Enregistrer" }).click();
      await expect.poll(async () => (await reservation(j.reservationId)).phoneNumber).toBe(phone);
      await page.keyboard.press("Escape");
    }
  });

  test("reservation_read_only_after_approved", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "APPROVED" });
    const before = await reservation(j.reservationId);

    const detail = await openReservation(page, p.name, j.buyerLastName);
    await expect(detail.getByRole("button", { name: "Corriger la réservation" })).toHaveCount(0);
    await expect(detail.getByRole("button", { name: "Soumettre" })).toHaveCount(0);
    // Documents remain an allowed step on an approved file.
    await detail.getByLabel("Ajouter un document").setInputFiles(pdf("apres-approbation.pdf"));
    await expect(detail.getByRole("button", { name: "apres-approbation.pdf" })).toBeVisible();

    const agent = await Api.as("agent");
    await expectRefused(
      await agent.raw("PUT", `/api/Reservations/${j.reservationId}`, { reservationId: j.reservationId, phoneNumber: "+212699999999" }),
      [409],
      "edit approved reservation",
    );
    const after = await reservation(j.reservationId);
    expect(after.phoneNumber).toBe(before.phoneNumber);
    expect(after.status).toBe(STATUS.APPROVED);
    expect(after.documents).toHaveLength(1);
  });
});

test.describe("Validation (admin projet)", { tag: "@projectAdmin" }, () => {
  test("approval_blocked_without_required_documents", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "SUBMITTED" });
    // The project starts requiring a piece after submission.
    const padmin = await Api.as("projectAdmin");
    await padmin.put(`/api/Projects/${p.id}/document-requirements`, { projectId: p.id, documentType: "CIN", labelFr: "CIN ou passeport", isRequired: true, sequenceNo: 1 });

    const detail = await openReservation(page, p.name, j.buyerLastName);
    await detail.getByRole("button", { name: "Approuver" }).click();
    await expect(detail.locator(".form-error")).toContainText(/CIN|pièce|document/i);
    expect((await reservation(j.reservationId)).status).toBe(STATUS.SUBMITTED);

    await expectRefused(
      await padmin.raw("POST", `/api/Reservations/${j.reservationId}/approve`, { reservationId: j.reservationId, adminUserId: padmin.userId, documents: [] }),
      [422],
      "approve without documents",
    );
    expect((await reservation(j.reservationId)).status).toBe(STATUS.SUBMITTED);
  });

  test("required_documents_are_configurable_per_project", async ({ page }) => {
    acceptDialogs(page);
    // Default set on a new project.
    const withDefaults = await st.createProject({ documentRequirements: "default" });
    const padmin = await Api.as("projectAdmin");
    const defaults = await padmin.get<{ documentType: string; isRequired: boolean }[]>(`/api/Projects/${withDefaults.id}/document-requirements`);
    expect(defaults.map((d) => d.documentType).sort()).toEqual([...st.DEFAULT_DOCUMENT_TYPES].sort());
    expect(defaults.every((d) => d.isRequired)).toBe(true);

    // Another project reconfigured through the UI: keep CIN, drop the other two, add a salary certificate.
    const custom = await st.createProject({ documentRequirements: "default" });
    await page.goto(`/admin/projects/${custom.id}`);
    const panel = page.locator(".card").filter({ has: page.getByRole("heading", { name: "Pièces exigées à la réservation" }) });
    for (const label of ["Contrat ou bulletin de réservation signé", "Justificatif de paiement de la réservation"]) {
      await panel.getByRole("row").filter({ hasText: label }).getByRole("button", { name: "Retirer" }).click();
      await expect(panel.getByRole("row").filter({ hasText: label })).toHaveCount(0);
    }
    await panel.getByLabel("Code").fill("ATTESTATION_SALAIRE");
    await panel.getByLabel("Libellé").fill("Attestation de salaire");
    await panel.getByRole("button", { name: "Ajouter" }).click();
    await expect(panel.getByRole("row").filter({ hasText: "Attestation de salaire" })).toHaveCount(1);

    const configured = await padmin.get<{ documentType: string }[]>(`/api/Projects/${custom.id}/document-requirements`);
    expect(configured.map((d) => d.documentType).sort()).toEqual(["ATTESTATION_SALAIRE", "CIN"]);

    // The checklist of a file on that project follows the new configuration.
    const j = await st.createReservation(custom, { state: "DRAFT" });
    const agent = await Api.as("agent");
    const checklist = await agent.get<{ items: { documentType: string }[] }>(`/api/Reservations/${j.reservationId}/document-checklist`);
    expect(checklist.items.map((i) => i.documentType).sort()).toEqual(["ATTESTATION_SALAIRE", "CIN"]);
    await st.uploadReservationDocument(j.reservationId, "CIN");
    await st.uploadReservationDocument(j.reservationId, "ATTESTATION_SALAIRE");
    await agent.post(`/api/Reservations/${j.reservationId}/submit`, { reservationId: j.reservationId });
    expect((await reservation(j.reservationId)).status).toBe(STATUS.SUBMITTED);
  });
});

