    }
  }

  function addDraftSnag() {
    setDraftSnags((prev) => [...prev, { description: "", severity: "MINOR" }]);
  }

  function updateDraftSnag(index: number, patch: Partial<SnagInput>) {
    setDraftSnags((prev) => prev.map((s, i) => (i === index ? { ...s, ...patch } : s)));
  }

  function removeDraftSnag(index: number) {
    setDraftSnags((prev) => prev.filter((_, i) => i !== index));
  }

  async function submitReport(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const appointmentId = visitCase?.currentAppointment?.appointmentId;

    if (!appointmentId) {
      setError("Aucun rendez-vous de visite finale en cours pour ce dossier.");
      return;
    }

    setError(null);
    setBusy(true);
    try {
      const worstSeverity = draftSnags.reduce<SnagSeverity | null>((worst, s) => {
        const rank: Record<SnagSeverity, number> = { MINOR: 1, MAJOR: 2, BLOCKING: 3 };
        return !worst || rank[s.severity] > rank[worst] ? s.severity : worst;
      }, null);

      const resultCode: VisitResult =
        worstSeverity === "BLOCKING"
          ? "NON_COMPLIANT_BLOCKING_SNAGS"
          : worstSeverity === "MAJOR"
          ? "NON_COMPLIANT_MAJOR_SNAGS"
          : worstSeverity === "MINOR"
          ? "COMPLIANT_MINOR_SNAGS"
          : "COMPLIANT_NO_SNAG";

      await finalVisitsApi.submitReport(appointmentId, {
        resultCode,
        generalCondition: String(form.get("generalCondition") || "") || undefined,
        observations: String(form.get("observations") || "") || undefined,
        snags: draftSnags.filter((s) => s.description.trim()),
      });

      setShowReportForm(false);
      setDraftSnags([]);
      (e.target as HTMLFormElement).reset();
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de l'envoi du rapport.");
    } finally {
      setBusy(false);
    }
  }

  async function acknowledge(accept: boolean) {
    const reportId = buyerReport?.reportId;
    if (!reportId) {
      setError("Aucun compte rendu de visite finale à valider pour ce dossier.");
      return;
    }

    let disputeReason: string | undefined;
    if (!accept) {
      disputeReason = window.prompt("Motif de la contestation ?")?.trim();
      if (!disputeReason) return;
    }

    setError(null);
