      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la validation du compte rendu.");
    } finally {
      setBusy(false);
    }
  }

  async function transitionSnag(snagId: string, targetStatus: SnagStatus) {
    let resolutionComment: string | undefined;
    if (targetStatus === "RESOLVED") {
      resolutionComment = window.prompt("Commentaire de résolution ?")?.trim();
      if (!resolutionComment) return;
    }

    setError(null);
    setBusy(true);
    try {
      await finalVisitsApi.transitionSnag(snagId, targetStatus, { resolutionComment });
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la mise à jour de la réserve.");
    } finally {
      setBusy(false);
    }
  }

  if (!eligibility) return <Loading />;

