      status: number;
    }
    interface CaseReportDto {
      reportId: string;
      versionNo: number;
      status: number;
      resultCode: number;
      generalCondition?: string;
      observations?: string;
      submittedAt?: string;
      acknowledgedAt?: string;
      disputeReason?: string;
      snags: CaseSnagDto[];
    }
    interface CaseDto {
      caseId: string;
      status: number;
      currentAppointment?: CaseAppointmentDto;
      currentReport?: CaseReportDto;
    }
    let dto: CaseDto;
    try {
      dto = await projectFetch<CaseDto>(`/api/final-visits/reservations/${reservationId}/case`);
    } catch (err) {
      if (err instanceof ApiError && err.status === 404) return null;
      throw err;
    }
    return {
      caseId: dto.caseId,
      status: (["OPEN", "REVISIT_REQUIRED", "READY_FOR_NOTARY", "CLOSED"] as const)[dto.status],
      currentAppointment: dto.currentAppointment && {
        appointmentId: dto.currentAppointment.appointmentId,
        attemptNo: dto.currentAppointment.attemptNo,
        startsAt: dto.currentAppointment.startsAt,
        endsAt: dto.currentAppointment.endsAt,
        status: finalVisitAttemptStatusCode.fromInt(dto.currentAppointment.status),
