import { expect, test } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { promptAnswers } from "./support/ui";

/**
 * Scope 5 — Visite finale.
 * Wire values: appointment 0 REQUESTED, 1 CONFIRMED, 2 RESCHEDULE_PROPOSED, 4 CANCELLED, 5 COMPLETED, 6 NO_SHOW;
 * visit result 0 COMPLIANT_NO_SNAG … 2 NON_COMPLIANT_MAJOR_SNAGS; eligibility 0 ELIGIBLE, 4 NOT_ELIGIBLE_FINAL_VISIT_PENDING.
 */
const APPT = st.AppointmentStatus;

interface CaseDto {
  responsibleSalesAgentId?: string;
  responsibleSalesAgentName?: string;
  currentAppointment?: { appointmentId: string; attemptNo: number; startsAt: string; status: number; causeType?: string } | null;
  currentReport?: {
    resultCode: number;
    generalCondition?: string;
    observations?: string;
    clientFeedback?: string;
    nonComplianceReason?: string;
    correctiveAction?: string;
    followUpNotes?: string;
    snags: { description: string; severity: number }[];
  } | null;
}

async function visitCase(reservationId: string) {
  const agent = await Api.as("agent");
  return agent.get<CaseDto>(`/api/final-visits/reservations/${reservationId}/case`);
}

const local = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")} ${String(d.getHours()).padStart(2, "0")}:00`;

test.describe("Acheteur", { tag: "@buyer" }, () => {
  test("final_visit_requestable_only_after_reservation_approved", async ({ page }) => {
    const p = await st.createProject();
    const submitted = await st.createReservation(p, { state: "SUBMITTED", unitIndex: 0 });
    const approved = await st.createReservation(p, { state: "APPROVED", unitIndex: 1 });
    await st.setConstructionPct(p, 100);
    await st.completeProject(p);
    const buyer = await Api.as("buyer", true);

    // Not approved: no request action, and the API refuses.
    await page.goto(`/my/properties/${submitted.reservationId}`);
    await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
    await expect(page.getByRole("button", { name: "Demander une visite" })).toHaveCount(0);
    await expectRefused(
      await buyer.raw("POST", `/api/final-visits/reservations/${submitted.reservationId}/request`, { reservationId: submitted.reservationId, startsAt: "2027-02-01T10:00:00" }),
      [409],
      "final visit on a submitted reservation",
    );

    // Approved: the buyer can request it.
    const answer = promptAnswers(page);
    answer.next = local(new Date(Date.now() + 12 * 86400000));
    await page.goto(`/my/properties/${approved.reservationId}`);
    await page.getByRole("button", { name: "Demander une visite" }).click();
    await expect.poll(orNull(async () => (await visitCase(approved.reservationId)).currentAppointment?.status ?? null)).toBe(APPT.Requested);
    await expect(page.getByRole("alert")).toHaveCount(0);
  });

  test("buyer_can_view_own_visits_but_cannot_edit_feedback", async ({ page }) => {
    const j = await st.approvedInDelivery();
    await st.createFinalVisit(j, "COMPLIANT", { report: { clientFeedback: "Très satisfait de la finition (E2E)", followUpNotes: "Remise des clés à planifier (E2E)" } });

    await page.goto(`/my/properties/${j.reservationId}`);
    const card = page.locator(".card").filter({ has: page.getByRole("heading", { name: "Compte-rendu de visite finale" }) });
    await expect(card.getByText("Très satisfait de la finition (E2E)")).toBeVisible();
    await expect(card.getByText("Remise des clés à planifier (E2E)")).toBeVisible();
    // Read-only: nothing to type into, no report authoring.
    await expect(card.locator("input, textarea, select")).toHaveCount(0);
    await expect(page.getByRole("button", { name: "Saisir un rapport de visite" })).toHaveCount(0);

    const buyer = await Api.as("buyer", true);
    await expectRefused(
      await buyer.raw("POST", `/api/final-visits/appointments/${j.finalVisitAppointmentId}/report`, {
        appointmentId: j.finalVisitAppointmentId, resultCode: 0, clientFeedback: "modifié par l'acheteur", snags: [],
      }),
      [403],
      "buyer authors a report",
    );
    await expectRefused(await buyer.raw("GET", `/api/final-visits/reservations/${j.reservationId}/case`), [403], "buyer reads the internal case");
    expect((await visitCase(j.reservationId)).currentReport?.clientFeedback).toBe("Très satisfait de la finition (E2E)");
  });
});

