export async function withSaleInsertFailure<T>(unitId: string, fn: () => Promise<T>): Promise<T> {
  const name = `e2e_fail_sale_${unitId.replace(/-/g, "")}`;
  sql(`EXEC('CREATE TRIGGER [${name}] ON [Sales] AFTER INSERT AS IF EXISTS (SELECT 1 FROM inserted WHERE UnitId = ''${unitId}'') THROW 50001, ''e2e injected sale failure'', 1;')`);
