import { expect, test, type Page } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, openReservation, promptAnswers } from "./support/ui";

/**
 * Scope 6 — Vente manuelle et automatique.
 * Reservation wire status: 0 SUBMITTED, 1 APPROVED, 4 CONVERTED.
 */

async function saleCard(page: Page, projectName: string, buyerLastName: string) {
  const detail = await openReservation(page, projectName, buyerLastName);
  const card = detail.locator(".card").filter({ has: page.getByRole("heading", { name: "Vente", exact: true }) });
  await expect(card).toBeVisible();
  return { detail, card };
}

async function recordPurchaseAsNotary(page: Page, j: st.JourneyFixture) {
  await page.goto("/admin/notary-appointments");
  const row = page.getByRole("row").filter({ hasText: j.buyerLastName });
  await expect(row).toHaveCount(1);
  await row.getByRole("button", { name: "Enregistrer le résultat" }).click();
  const dialog = page.getByRole("dialog", { name: "Résultat du rendez-vous notarié" });
  await dialog.getByLabel(/Achat finalisé/).check();
  await dialog.getByRole("button", { name: "Finaliser la vente" }).click();
  await expect(dialog).toBeHidden();
}

// ---------------------------------------------------------------------------
// Visibilité du bouton « Créer une vente »
// ---------------------------------------------------------------------------
for (const [tag, label] of [["@agent", "Agent commercial"], ["@projectAdmin", "Admin projet"], ["@globalAdmin", "Admin global"]] as const) {
  test.describe(`Visibilité — ${label}`, { tag }, () => {
    test("sale_button_visible_for_sales_agent_project_admin_global_admin", async ({ page }) => {
      const j = await st.journey("FINAL_VISIT");
      const { card } = await saleCard(page, j.project.name, j.buyerLastName);
      await expect(card.getByRole("button", { name: "Créer une vente" })).toBeVisible();
    });
  });
}

for (const [tag, label] of [["@notary", "Notaire"], ["@technician", "Technicien"], ["@buyer", "Acheteur"]] as const) {
  test.describe(`Visibilité — ${label}`, { tag }, () => {
    test("sale_button_hidden_for_other_roles", async ({ page }) => {
      const j = await st.journey("FINAL_VISIT");
      if (tag === "@buyer") {
        await page.goto(`/my/properties/${j.reservationId}`);
        await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
      } else {
        await page.goto("/admin/reservations");
        // The reservations screen is not theirs: redirected away, nothing rendered.
        await expect(page).not.toHaveURL(/\/admin\/reservations/);
      }
      await expect(page.getByRole("button", { name: "Créer une vente" })).toHaveCount(0);

      const key = tag === "@notary" ? "notary" : tag === "@technician" ? "technician" : "buyer";
      const api = await Api.as(key, true);
      await expectRefused(await api.raw("POST", "/api/sales", { reservationId: j.reservationId }), [403], `${key} creates a sale`);
      expect(await st.getSale(j.reservationId)).toBeNull();
    });
  });
}

test.describe("Visibilité — conditions", { tag: "@agent" }, () => {
  test("sale_button_hidden_unless_project_en_livraison", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "APPROVED" });
    const { card } = await saleCard(page, p.name, j.buyerLastName);
    await expect(card.getByRole("button", { name: "Créer une vente" })).toHaveCount(0);
    await expect(card.getByRole("list", { name: "Conditions de création de la vente" })).toContainText("en livraison");

    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("POST", "/api/sales", { reservationId: j.reservationId }), [409, 422], "sale on SUR_PLAN project");
    expect(await st.getSale(j.reservationId)).toBeNull();
  });

  test("sale_button_hidden_unless_reservation_approved", async ({ page }) => {
    const p = await st.createProject();
    const submitted = await st.createReservation(p, { state: "SUBMITTED", unitIndex: 0 });
    await st.setConstructionPct(p, 100);
    await st.completeProject(p);

    const detail = await openReservation(page, p.name, submitted.buyerLastName);
    await expect(detail.getByRole("button", { name: "Approuver" }).or(detail.getByText("Dépôt"))).toBeTruthy();
    await expect(detail.getByRole("button", { name: "Créer une vente" })).toHaveCount(0);

    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("POST", "/api/sales", { reservationId: submitted.reservationId }), [409, 422], "sale on submitted reservation");
    const eligibility = await agent.get<{ canCreate: boolean; reasons: string[] }>(`/api/sales/eligibility/${submitted.reservationId}`);
    expect(eligibility.canCreate).toBe(false);
    expect(eligibility.reasons.join(" ")).toContain("approuvée");
  });

  test("sale_button_hidden_unless_final_visit_validated", async ({ page }) => {
    const j = await st.approvedInDelivery();
    let { card } = await saleCard(page, j.project.name, j.buyerLastName);
    await expect(card.getByRole("button", { name: "Créer une vente" })).toHaveCount(0);
    await expect(card.getByRole("list", { name: "Conditions de création de la vente" })).toContainText("visite finale");

    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("POST", "/api/sales", { reservationId: j.reservationId }), [409, 422], "sale before final visit");

    // Once the visit is validated the only missing condition is met: the button appears.
    await st.createFinalVisit(j);
    await page.keyboard.press("Escape");
    ({ card } = await saleCard(page, j.project.name, j.buyerLastName));
    await expect(card.getByRole("button", { name: "Créer une vente" })).toBeVisible();
  });

  test("sale_button_hidden_when_active_or_finalized_sale_exists", async ({ page }) => {
    const draft = await st.journey("DRAFT_SALE");
    let { card } = await saleCard(page, draft.project.name, draft.buyerLastName);
    await expect(card.getByText("Brouillon")).toBeVisible();
    await expect(card.getByRole("button", { name: "Créer une vente" })).toHaveCount(0);

    const sold = await st.journey("SOLD");
    await page.keyboard.press("Escape");
    ({ card } = await saleCard(page, sold.project.name, sold.buyerLastName));
    await expect(card.getByText("Confirmée")).toBeVisible();
    await expect(card.getByRole("button", { name: "Créer une vente" })).toHaveCount(0);

    const agent = await Api.as("agent");
    for (const j of [draft, sold]) {
      await expectRefused(await agent.raw("POST", "/api/sales", { reservationId: j.reservationId }), [409, 422], "second sale");
    }
  });
});

// ---------------------------------------------------------------------------
// Contenu de la vente brouillon
// ---------------------------------------------------------------------------
test.describe("Contenu du brouillon", { tag: "@agent" }, () => {
  test("draft_sale_contains_all_required_fields", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT", { warrantyMonths: 30 });
    const agent = await Api.as("agent");
    await agent.post("/api/sales", { reservationId: j.reservationId, notes: "Clause parking incluse (E2E)" });
    const sale = (await st.getSale(j.reservationId))!;

    // API: every field the draft must carry.
    expect(sale.status).toBe("Draft");
    expect(sale.projectName).toBe(j.project.name);
    expect(sale.immeubleName).toBe(`${j.project.name}-B1`);
    expect(sale.floorName).toBe("RDC");
    expect(sale.unitNumber).toBe("RDC-1");
    expect(sale.reservationId).toBe(j.reservationId);
    expect(sale.buyerLastName).toBe(j.buyerLastName);
    expect(sale.finalPrice).toBe(1250000);
    expect(sale.reservationAmount).toBe(125000);
    expect(sale.remainingAmount).toBe(1125000);
    expect(sale.warrantyMonths).toBe(30);
    expect(sale.notes).toBe("Clause parking incluse (E2E)");

    // UI: the same fields are displayed.
    const { card } = await saleCard(page, j.project.name, j.buyerLastName);
    const field = (label: string) => card.locator("dt", { hasText: new RegExp(`^${label}`) }).locator("xpath=following-sibling::dd[1]");
    await expect(field("Projet")).toHaveText(j.project.name);
    await expect(field("Immeuble")).toHaveText(`${j.project.name}-B1`);
    await expect(field("Étage")).toHaveText("RDC");
    await expect(field("Unité")).toHaveText("RDC-1");
    await expect(field("Réservation")).toHaveText(j.reservationId.slice(0, 8));
    await expect(field("Acquéreur")).toContainText(j.buyerLastName);
    await expect(field("Prix final")).toContainText(/1[\s.  ]?250[\s.  ]?000/);
    await expect(field("Montant déjà réservé")).toContainText(/125[\s.  ]?000/);
    await expect(field("Reste à payer")).toContainText(/1[\s.  ]?125[\s.  ]?000/);
    await expect(field("Garantie")).toHaveText("30 mois");
    await expect(field("Notes")).toHaveText("Clause parking incluse (E2E)");
  });

  test("draft_sale_remaining_amount_equals_price_minus_reserved", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    const { detail, card } = await saleCard(page, j.project.name, j.buyerLastName);
    await card.getByRole("button", { name: "Créer une vente" }).click();
    const create = page.getByRole("dialog", { name: "Créer une vente" });
    await create.getByLabel(/Prix convenu/).fill("1180000");
    await create.locator("button[type=submit]").click();
    await expect(create).toBeHidden();
    let sale = (await st.getSale(j.reservationId))!;
    expect(sale.remainingAmount).toBe(sale.finalPrice! - sale.reservationAmount!);
    expect(sale.remainingAmount).toBe(1180000 - 125000);

    await detail.getByRole("button", { name: "Modifier", exact: true }).click();
    const edit = page.getByRole("dialog", { name: "Modifier la vente" });
    await edit.getByLabel("Prix convenu (MAD)").fill("1300000");
    await edit.locator("button[type=submit]").click();
    await expect(edit).toBeHidden();
    sale = (await st.getSale(j.reservationId))!;
    expect(sale.finalPrice).toBe(1300000);
    expect(sale.remainingAmount).toBe(1300000 - 125000);
  });

  test("draft_sale_inherits_warranty_from_project", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT", { warrantyMonths: 42 });
    const { card } = await saleCard(page, j.project.name, j.buyerLastName);
    await card.getByRole("button", { name: "Créer une vente" }).click();
    const create = page.getByRole("dialog", { name: "Créer une vente" });
    await create.locator("button[type=submit]").click();
    await expect(create).toBeHidden();
    expect((await st.getSale(j.reservationId))!.warrantyMonths).toBe(42);
    await expect(card.locator("dt", { hasText: "Garantie" }).locator("xpath=following-sibling::dd[1]")).toHaveText("42 mois");
  });
});

// ---------------------------------------------------------------------------
// Création automatique (résultat notaire PURCHASE_COMPLETED)
// ---------------------------------------------------------------------------
test.describe("Création automatique", { tag: "@notary" }, () => {
  test("existing_draft_sale_becomes_confirmed_on_purchase_completed", async ({ page }) => {
    const j = await st.journey("DRAFT_SALE");
