import { expect, type Locator, type Page } from "@playwright/test";

/**
 * Answers prompts with a value that can change between actions:
 *   const answer = promptAnswers(page); answer.next = "2027-01-10 10:00";
 */
export function promptAnswers(page: Page) {
  const state = { next: "" as string | null };
  page.on("dialog", (dialog) => {
    if (dialog.type() === "prompt" && state.next === null) void dialog.dismiss();
    else void dialog.accept(dialog.type() === "prompt" ? (state.next ?? "") : undefined);
  });
  return state;
}

/** Answers every window.confirm/prompt on the page (prompt gets `promptValue`). */
export function acceptDialogs(page: Page, promptValue = "") {
  page.on("dialog", (dialog) => {
    void dialog.accept(dialog.type() === "prompt" ? promptValue : undefined);
  });
}

/**
 * A list filter select by its caption. The <label> wraps the <select>, so its
 * accessible name also contains every option text — getByLabel cannot match it
 * exactly; the caption <span> can.
 */
export function listFilter(page: Page, caption: string) {
  return page.locator(".list-filters label").filter({ has: page.locator("span", { hasText: new RegExp(`^${caption}$`) }) }).locator("select");
}

/**
 * A form control by its exact caption inside a <Field> (label > span).
 * Needed where option texts or placeholders repeat a caption word, which makes
 * getByLabel ambiguous (the label's accessible name includes the options).
 */
export function field(scope: Page | Locator, caption: string) {
  const escaped = caption.replace(/[.*+?^${}()|[\]\]/g, "\$&");
  return scope
    .locator("label")
    .filter({ has: scope.locator("span", { hasText: new RegExp(`^${escaped}$`) }) })
    .locator("select, input, textarea")
    .first();
}

/** Opens a reservation's detail dialog from /admin/reservations, filtered on its project. */
export async function openReservation(page: Page, projectName: string, buyerLastName: string) {
  await page.goto("/admin/reservations");
  const filter = listFilter(page, "Projet");
  await expect(filter.locator("option", { hasText: projectName })).toHaveCount(1);
  await filter.selectOption({ label: projectName });
  const row = page.getByRole("row").filter({ hasText: buyerLastName });
  await expect(row).toHaveCount(1);
  await row.getByRole("button", { name: "Détails" }).click();
  const dialog = page.getByRole("dialog", { name: new RegExp(`Réservation — .*${buyerLastName}`) });
  await expect(dialog).toBeVisible();
  return dialog;
}

/** Waits until the ProjectAPI call matching `urlPart` (and method) completes, returning its status. */
export async function responseStatus(page: Page, urlPart: string | RegExp, method: string, action: () => Promise<unknown>) {
  const [res] = await Promise.all([
    page.waitForResponse((r) => r.request().method() === method && (typeof urlPart === "string" ? r.url().includes(urlPart) : urlPart.test(r.url()))),
    action(),
  ]);
  return res.status();
}

