  const immeubleId = searchParams.get("immeuble") ?? "";

  const [unit, setUnit] = useState<Unit | null | undefined>(undefined);
  const [immeuble, setImmeuble] = useState<Immeuble | null>(null);
  const { journey, loading, error } = useUnitJourney(unitId);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      // Fast path: the caller told us which immeuble the unit belongs to.
      if (immeubleId) {
        const [im, units] = await Promise.all([
          immeublesApi.getById(immeubleId),
          immeublesApi.listUnits(immeubleId),
        ]);
        if (cancelled) return;
        setImmeuble(im ?? null);
        setUnit(units.find((u) => u.id === unitId) ?? null);
        return;
      }

      // Fallback: there is no GET /units/{id}, so locate the unit by scanning
      // each immeuble's units until we find its owner.
      const immeubles = await allPages((page) => immeublesApi.list({ ...page }));
      for (const im of immeubles.data) {
        if (cancelled) return;
        const units = await immeublesApi.listUnits(im.id);
        const match = units.find((u) => u.id === unitId);
        if (match) {
          if (cancelled) return;
          setImmeuble(im);
          setUnit(match);
          return;
        }  
      }
      if (!cancelled) setUnit(null);
    })().catch(() => {
      if (!cancelled) setUnit(null);
    });

