31	    let cancelled = false;
32	
33	    (async () => {
34	      // Fast path: the caller told us which immeuble the unit belongs to.
35	      if (immeubleId) {
36	        const [im, units] = await Promise.all([
37	          immeublesApi.getById(immeubleId),
38	          immeublesApi.listUnits(immeubleId),
39	        ]);
40	        if (cancelled) return;
41	        setImmeuble(im ?? null);
42	        setUnit(units.find((u) => u.id === unitId) ?? null);
43	        return;
44	      }
45	
46	      // No building in the URL: ask the API where the unit is (one call),
