import { expect, test } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { field, openReservation } from "./support/ui";

/** Scope 8 — Livraison et garantie (flow: Handovers). */

interface WarrantyDto {
  id: string;
  unitId: string;
  startsAt: string;
  endsAt: string;
  isActive: boolean;
}

const monthsBetween = (a: string, b: string) => {
  const s = new Date(a);
  const e = new Date(b);
  return (e.getFullYear() - s.getFullYear()) * 12 + (e.getMonth() - s.getMonth());
};

test.describe("Livraison — agent", { tag: "@agent" }, () => {
  test("handover_available_only_after_sale_confirmed", async ({ page }) => {
    const draft = await st.journey("DRAFT_SALE");
    const agent = await Api.as("agent");

    // Sale not confirmed: no delivery section, API refuses to schedule.
    const draftDetail = await openReservation(page, draft.project.name, draft.buyerLastName);
    await expect(draftDetail.getByRole("heading", { name: "Livraison", exact: true })).toHaveCount(0);
    await expect(draftDetail.getByRole("button", { name: "Planifier la livraison" })).toHaveCount(0);
    await expectRefused(
      await agent.raw("POST", "/api/Handovers", { reservationId: draft.reservationId, scheduledAt: "2027-06-01T10:00:00" }),
      [409, 422],
      "handover before confirmed sale",
    );
    await page.keyboard.press("Escape");

    // Sale confirmed (PURCHASE_COMPLETED): the delivery can be planned from the UI.
    const sold = await st.journey("SOLD");
    expect((await st.getSale(sold.reservationId))!.status).toBe("Confirmed");
    const detail = await openReservation(page, sold.project.name, sold.buyerLastName);
    await detail.getByRole("button", { name: "Planifier la livraison" }).click();
    const dialog = page.getByRole("dialog").filter({ has: page.getByLabel("Lieu") }).last();
    await field(dialog, "Date et heure").fill("2027-06-15T10:00");
    await field(dialog, "Lieu").fill("Sur site (E2E)");
    await dialog.locator("button[type=submit]").click();
    await expect(dialog).toBeHidden();
    await expect
      .poll(orNull(async () => (await agent.get<{ appointmentId?: string }>(`/api/Handovers/reservations/${sold.reservationId}/mine`)).appointmentId ?? null))
      .not.toBeNull();
  });

  test("unit_becomes_delivered_after_handover", async ({ page }) => {
    const j = await st.journey("SOLD");
    const agent = await Api.as("agent");
    expect(await st.getUnitStatus(j.project, j.unitId)).toMatch(/^SOLD$/i);

    // Agent: plan, confirm and write the handover report in the UI.
    const detail = await openReservation(page, j.project.name, j.buyerLastName);
    await detail.getByRole("button", { name: "Planifier la livraison" }).click();
    const schedule = page.getByRole("dialog").filter({ has: page.getByLabel("Lieu") }).last();
    await field(schedule, "Date et heure").fill("2027-07-01T09:00");
    await schedule.locator("button[type=submit]").click();
    await expect(schedule).toBeHidden();
    await detail.getByRole("button", { name: "Confirmer le rendez-vous" }).click();
    await detail.getByRole("button", { name: "Rédiger le procès-verbal" }).click();
    const report = page.getByRole("dialog").filter({ has: page.getByLabel("Participants") }).last();
    await field(report, "Participants").fill("Acquéreur, agent (E2E)");
    await field(report, "Observations").fill("Remise conforme (E2E)");
    await report.locator("button[type=submit]").click();
    await expect(report).toBeHidden();

    // Not delivered until the buyer acknowledges the report.
    expect(await st.getUnitStatus(j.project, j.unitId)).toMatch(/^SOLD$/i);
    const status = await agent.get<{ reportId?: string }>(`/api/Handovers/reservations/${j.reservationId}/mine`);
    const buyer = await Api.as("buyer", true);
    await buyer.post(`/api/Handovers/reports/${status.reportId}/acknowledge`, {});
    await expect.poll(async () => st.getUnitStatus(j.project, j.unitId)).toMatch(/^DELIVERED$/i);
  });

  test("warranty_duration_copied_into_sale_at_creation", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT", { warrantyMonths: 18 });
    const detail = await openReservation(page, j.project.name, j.buyerLastName);
    await detail.getByRole("button", { name: "Créer une vente" }).click();
    const dialog = page.getByRole("dialog", { name: "Créer une vente" });
    await dialog.locator("button[type=submit]").click();
    await expect(dialog).toBeHidden();
    expect((await st.getSale(j.reservationId))!.warrantyMonths).toBe(18);
  });

  test("warranty_duration_not_editable_by_buyer_or_agent_at_handover", async ({ page }) => {
    const j = await st.journey("SOLD", { warrantyMonths: 24 });
    const detail = await openReservation(page, j.project.name, j.buyerLastName);
    await detail.getByRole("button", { name: "Planifier la livraison" }).click();
    const schedule = page.getByRole("dialog").filter({ has: page.getByLabel("Lieu") }).last();
    await expect(schedule.getByText(/garantie/i)).toHaveCount(0);
    await field(schedule, "Date et heure").fill("2027-08-01T09:00");
    await schedule.locator("button[type=submit]").click();
    await expect(schedule).toBeHidden();
    await detail.getByRole("button", { name: "Confirmer le rendez-vous" }).click();
    await detail.getByRole("button", { name: "Rédiger le procès-verbal" }).click();
    const report = page.getByRole("dialog").filter({ has: page.getByLabel("Participants") }).last();
    await expect(report.getByText(/garantie/i)).toHaveCount(0);
    await report.locator("button[type=submit]").click();
    await expect(report).toBeHidden();

    // Buyer and agent try to force a warranty length through the API: ignored.
    const agent = await Api.as("agent");
    const status = await agent.get<{ reportId?: string; appointmentId?: string }>(`/api/Handovers/reservations/${j.reservationId}/mine`);
    await agent.raw("POST", `/api/Handovers/${status.appointmentId}/report`, { appointmentId: status.appointmentId, warrantyMonths: 120, participants: "x" });
    const refreshed = await agent.get<{ reportId?: string }>(`/api/Handovers/reservations/${j.reservationId}/mine`);
    const buyer = await Api.as("buyer", true);
    await buyer.post(`/api/Handovers/reports/${refreshed.reportId}/acknowledge`, { warrantyMonths: 120 });
    const warranties = await buyer.get<WarrantyDto[]>(`/api/Handovers/reservations/${j.reservationId}/warranties/mine`);
    expect(warranties).toHaveLength(1);
    expect(monthsBetween(warranties[0].startsAt, warranties[0].endsAt)).toBe(24);
  });

  test("no_duplicate_delivery_flow", async ({ page }) => {
    // One flow only: Handovers. The legacy Deliveries screen and API are gone.
    await page.goto("/admin/deliveries");
    await expect(page).not.toHaveURL(/\/admin\/deliveries/);
    await expect(page.getByRole("link", { name: /Livraisons/ })).toHaveCount(0);

    const agent = await Api.as("agent");
    const j = await st.journey("SOLD");
    const sale = (await st.getSale(j.reservationId))!;
    const legacy = await agent.raw("POST", "/api/deliveries", { saleId: sale.id, unitId: j.unitId, deliveryDate: "2027-01-01T10:00:00" });
    expect([404, 405]).toContain(legacy.status());
    expect(st.runSql(`SELECT COUNT(*) FROM PropertyDeliveries WHERE SaleId = '${sale.id}'`).trim()).toBe("0");

    // …while the Handovers flow is the one that delivers.
    await st.deliverUnit(j);
    expect(await st.getUnitStatus(j.project, j.unitId)).toMatch(/^DELIVERED$/i);
  });
});

