    provision: { firstName: "Salma", lastName: "Autre", phone: "+212600000102" },
  },
  notary: { key: "notary", userName: "e2e.notary", email: "e2e.notary@qa.local", role: "NOTARY" },
  technician: { key: "technician", userName: "e2e.tech", email: "e2e.tech@qa.local", role: "TECHNICIAN" },
  technicianOther: { key: "technicianOther", userName: "gpia.tech", email: "gpia.tech@test.local", role: "TECHNICIAN" },
  techLead: {
    key: "techLead",
    userName: "e2e.techlead@qa.local",
    email: "e2e.techlead@qa.local",
