private static clients = new Map<RoleKey, Api>();

/**
 * One client per role per worker. Creating a request context on every call
 * (hundreds per journey fixture) leaked contexts and slowed the whole run.
 * `fresh` re-logs in and replaces the cached client.
 */
static async as(key: RoleKey, fresh = false): Promise<Api> {
  const cached = Api.clients.get(key);
  if (cached && !fresh) return cached;
  const s = await session(key, fresh);
  const ctx = await request.newContext({
    extraHTTPHeaders: { Authorization: `Bearer ${s.token}`, Accept: "application/json" },
  });
  const api = new Api(ctx, s);
  Api.clients.set(key, api);
  if (cached) void cached.ctx.dispose().catch(() => undefined);
  return api;
}

