  async listMine(query) {
    const qs = buildQuery({ PageNumber: query?.pageNumber, PageSize: query?.pageSize });
    const res = await projectFetch<PaginatedResponse<AfterSaleClaimDto>>(`/api/after-sales/claims/mine${qs}`);
    return { ...res, data: res.data.map(fromWire) };
  },
  async create(data) {
    const res = await projectFetch<{ id: string }>("/api/after-sales/claims", {
      method: "POST",
      body: JSON.stringify({
        ...data,
        category: data.category ? claimCategory.toInt(data.category) : undefined,
        priority: data.priority ? claimPriority.toInt(data.priority) : undefined,
      }),
    });
    return { ...data, id: res.id } as AfterSaleClaim;
  },
  async updateStatus(id, status, extra) {
    await projectFetch<void>(`/api/after-sales/claims/${id}/status`, {
      method: "PUT",
      body: JSON.stringify({
        newStatus: claimStatus.toInt(status),
        changedByUserId: currentUserId(),
        resolutionSummary: extra?.resolutionSummary,
        assignedAgentId: extra?.assignedAgentId,
        note: extra?.note,
      }),
    });
    const list = await projectFetch<PaginatedResponse<AfterSaleClaimDto>>(
      `/api/after-sales/claims${buildQuery({ PageSize: 1000 })}`
    );
    const found = list.data.find((c) => c.id === id);
    if (!found) throw new Error(`Claim ${id} not found after status update`);
    return fromWire(found);
  },
  async respond(id, accept, reason) {
    await projectFetch<void>(`/api/after-sales/claims/${id}/respond`, {
      method: "POST",
      body: JSON.stringify({ accept, reason }),
    });
  },
};
