import { useCallback, useEffect, useState, type FormEvent } from "react";
import { claimsApi } from "../../api";
import { ApiError } from "../../api/http/client";
import type { ClaimCommentKind, ClaimDetail } from "../../types";
import { Button, CLAIM_STATUS_LABEL, Field, Loading, StatusBadge, Table } from "../../components/ui";
import { UnitContextDetails } from "../../components/ui/UnitContextDetails";
import { formatDate, formatDateTime } from "../../lib/format";

const KIND_LABEL: Record<ClaimCommentKind, string> = {
  WORK_DONE: "Travaux effectués",
  NOTE: "Note",
  REPLY: "Réponse de l'acquéreur",
};

const PHASE_LABEL: Record<string, string> = { BEFORE: "Avant", AFTER: "Après" };

/**
 * One claim, in full: what it is about (project / building / floor / unit),
 * its status history, the messages (work done by the technician, replies of
 * the buyer) and the attachments, including the technician's before/after
 * photos. Shared by the SAV desk and the buyer portal; `mode` decides which
 * forms are offered — the API enforces the same split.
 */
export function ClaimDetailView({
  claimId,
  mode,
  canWork,
  onChanged,
}: {
  claimId: string;
  /** "staff" = technician / technical lead / admin, "buyer" = the claim's owner. */
  mode: "staff" | "buyer";
  /** Staff only: may write work-done messages and before/after photos on this claim. */
  canWork?: boolean;
  onChanged?: () => void;
}) {
  const [detail, setDetail] = useState<ClaimDetail | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [phase, setPhase] = useState<"BEFORE" | "AFTER">("BEFORE");

  const load = useCallback(async () => {
    try {
      setDetail(await claimsApi.getDetail(claimId));
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Impossible de charger la réclamation.");
    }
  }, [claimId]);

  useEffect(() => {
    void load();
  }, [load]);

  const closed = detail ? ["CLOSED", "CANCELLED", "REJECTED"].includes(detail.status) : true;

  async function sendMessage(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    const data = new FormData(form);
    const message = String(data.get("message") || "").trim();
    if (!message) return;
    setError(null);
    setBusy(true);
    try {
      const kind: ClaimCommentKind | undefined = mode === "staff" ? (String(data.get("kind") || "NOTE") as ClaimCommentKind) : undefined;
      await claimsApi.addComment(claimId, message, kind);
      form.reset();
      await load();
      onChanged?.();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de l'envoi du message.");
    } finally {
      setBusy(false);
    }
  }

  async function uploadPhoto(file: File | undefined, input: HTMLInputElement) {
    if (!file) return;
    setError(null);
    setBusy(true);
    try {
      await claimsApi.uploadAttachment(claimId, file, mode === "staff" && canWork ? phase : undefined);
      await load();
      onChanged?.();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de l'envoi du fichier.");
    } finally {
      input.value = "";
      setBusy(false);
    }
  }

  async function openAttachment(id: string) {
    try {
      const blob = await claimsApi.downloadAttachment(id);
      const url = URL.createObjectURL(blob);
      window.open(url, "_blank", "noopener");
      setTimeout(() => URL.revokeObjectURL(url), 60_000);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Impossible d'ouvrir la pièce jointe.");
    }
  }

  if (!detail) return error ? <p className="form-error" role="alert">{error}</p> : <Loading />;

  return (
    <div className="claim-detail">
      {error && <p className="form-error" role="alert">{error}</p>}

      <dl className="detail-list">
        <dt>Titre</dt>
        <dd>{detail.title}</dd>
        <dt>Description</dt>
        <dd style={{ whiteSpace: "pre-line" }}>{detail.description}</dd>
        <dt>Catégorie</dt>
        <dd>{detail.category}</dd>
        <dt>Priorité</dt>
        <dd>{detail.priority}</dd>
        <dt>Statut</dt>
        <dd><StatusBadge status={detail.status} label={CLAIM_STATUS_LABEL[detail.status]} /></dd>
        <dt>Technicien</dt>
        <dd>{detail.assignedAgentName || "Non assigné"}</dd>
        <dt>Créée le</dt>
        <dd>{formatDate(detail.createdAt)}</dd>
        {detail.resolutionSummary && (<><dt>Résolution</dt><dd>{detail.resolutionSummary}</dd></>)}
      </dl>

      <UnitContextDetails context={detail.unitContext} />

      <section aria-label="Suivi de la réclamation" style={{ marginTop: 16 }}>
        <h4 style={{ margin: "0 0 8px" }}>Suivi</h4>
        {detail.history.length === 0 ? (
          <p className="muted small">Réclamation soumise, en attente de prise en charge.</p>
        ) : (
          <ol className="plain-list">
            {detail.history.map((h, i) => (
              <li key={i}>
                {formatDateTime(h.changedAt)} — {CLAIM_STATUS_LABEL[h.fromStatus]} → <strong>{CLAIM_STATUS_LABEL[h.toStatus]}</strong>
                {h.changedByName ? ` (${h.changedByName})` : ""}
                {h.note ? ` : ${h.note}` : ""}
              </li>
            ))}
          </ol>
        )}
      </section>

      <section aria-label="Messages" style={{ marginTop: 16 }}>
        <h4 style={{ margin: "0 0 8px" }}>Messages</h4>
        {detail.comments.length === 0 ? (
          <p className="muted small">Aucun message.</p>
        ) : (
          <ul className="plain-list">
            {detail.comments.map((c) => (
              <li key={c.id} data-kind={c.kind} style={{ marginBottom: 8 }}>
                <span className="muted small">
                  {KIND_LABEL[c.kind]} · {c.authorName || "—"} · {formatDateTime(c.createdAt)}
                </span>
                <div style={{ whiteSpace: "pre-line" }}>{c.message}</div>
              </li>
            ))}
          </ul>
        )}
        {!closed && (mode === "buyer" || canWork) && (
          <form onSubmit={sendMessage} className="inline-form" style={{ flexDirection: "column", alignItems: "stretch" }}>
            {mode === "staff" && (
              <Field label="Type de message">
                <select name="kind" defaultValue="WORK_DONE" disabled={busy}>
                  <option value="WORK_DONE">Travaux effectués</option>
                  <option value="NOTE">Note</option>
                </select>
              </Field>
            )}
            <Field label={mode === "buyer" ? "Votre réponse" : "Message"}>
              <textarea name="message" rows={3} required maxLength={2000} disabled={busy} />
            </Field>
            <Button type="submit" disabled={busy}>{busy ? "Envoi…" : mode === "buyer" ? "Répondre" : "Ajouter le message"}</Button>
          </form>
        )}
      </section>

      <section aria-label="Pièces jointes" style={{ marginTop: 16 }}>
        <h4 style={{ margin: "0 0 8px" }}>Pièces jointes</h4>
        {detail.attachments.length === 0 ? (
          <p className="muted small">Aucune pièce jointe.</p>
        ) : (
          <Table
            keyField={(a) => a.id}
            rows={detail.attachments}
            columns={[
              {
                header: "Fichier",
                render: (a) => (
                  <button type="button" className="btn-link" onClick={() => openAttachment(a.id)}>
                    {a.fileName || "Pièce jointe"}
                  </button>
                ),
              },
              { header: "Phase", render: (a) => (a.phase ? PHASE_LABEL[a.phase] : "-") },
              { header: "Ajoutée le", render: (a) => formatDateTime(a.uploadedAt) },
            ]}
          />
        )}
        {!closed && (mode === "buyer" || canWork) && (
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", marginTop: 8 }}>
            {mode === "staff" && (
              <label className="list-filter-select">
                <span>Photo</span>
                <select value={phase} onChange={(e) => setPhase(e.target.value as "BEFORE" | "AFTER")} disabled={busy}>
                  <option value="BEFORE">Avant intervention</option>
                  <option value="AFTER">Après intervention</option>
                </select>
              </label>
            )}
            <input
              type="file"
              accept="image/*,video/mp4,video/quicktime,application/pdf"
              aria-label={mode === "staff" ? "Ajouter une photo" : "Ajouter une pièce jointe"}
              disabled={busy}
              onChange={(e) => uploadPhoto(e.target.files?.[0], e.currentTarget)}
            />
          </div>
        )}
      </section>
    </div>
  );
}

