512	  const p = await createProject({ phase: "SUR_PLAN", warrantyMonths: opts.warrantyMonths, members: opts.members });
513	  const j = await createReservation(p, { state: "APPROVED", buyer: opts.buyer, agent });
514	  if (upTo === "APPROVED") return j;
515	  await setConstructionPct(p, 100);
516	  await completeProject(p);
517	  await createFinalVisit(j);
518	  if (upTo === "FINAL_VISIT") return j;
