  const agent = await Api.as(j.agent);
  const id = j.finalVisitAppointmentId!;
  await agent.post(`/api/final-visits/appointments/${id}/transition`, { appointmentId: id, targetStatus: AppointmentStatus.Confirmed });
  await agent.post(`/api/final-visits/appointments/${id}/transition`, { appointmentId: id, targetStatus: AppointmentStatus.Completed });
  return id;
}

/** Project in delivery with an approved reservation (the precondition of every final-visit test). */
export async function approvedInDelivery(opts: { buyer?: RoleKey } = {}) {
  const p = await createProject();
  const j = await createReservation(p, { state: "APPROVED", buyer: opts.buyer });
  await setConstructionPct(p, 100);
  await completeProject(p);
  return j;
}

export async function createDraftSale(j: JourneyFixture, as?: RoleKey) {
  const api = await Api.as(as ?? j.agent);
  const sale = await api.post<{ id: string; status: string }>("/api/sales", { reservationId: j.reservationId, notes: "Vente E2E" });
  j.saleId = sale.id;
  return sale;
}

/**
 * createNotaryAppointment(result): booked by the agent for this project's
 * notary; with a result, confirmed then completed by the notary.
 */
export async function createNotaryAppointment(j: JourneyFixture, result?: "PURCHASE_COMPLETED" | "POSTPONED") {
  const agent = await Api.as(j.agent);
  const notary = await Api.as("notary");
  const buyer = await Api.as(j.buyer);
  const na = await agent.post<{ id: string }>("/api/NotaryAppointments", {
    reservationId: j.reservationId,
    notaireId: notary.userId,
    agentId: agent.userId,
    buyerId: buyer.userId,
    appointmentDate: iso(daysFromNow(5 + Math.floor(Math.random() * 600), 8 + Math.floor(Math.random() * 9))),
    status: "Scheduled",
    taxFees: 25000,
    tahfidFees: 8000,
  });
  j.notaryAppointmentId = na.id;
  if (result) {
    await notary.put(`/api/NotaryAppointments/${na.id}`, { id: na.id, status: "Confirmed" });
    await notary.put(`/api/NotaryAppointments/${na.id}`, {
      id: na.id,
      status: "Completed",
      outcome: result,
      outcomeNote: result === "PURCHASE_COMPLETED" ? "Acte signé (E2E)" : "Reporté (E2E)",
    });
  }
  return j;
}

/** deliverUnit(): handover scheduled, confirmed, reported, acknowledged by the buyer. */
export async function deliverUnit(j: JourneyFixture) {
  const agent = await Api.as(j.agent);
  const buyer = await Api.as(j.buyer);
  const ho = await agent.post<{ id: string }>("/api/Handovers", {
    reservationId: j.reservationId,
    scheduledAt: iso(daysFromNow(9)),
    location: "Sur site",
    notes: "Remise des clés (E2E)",
  });
  j.handoverId = ho.id;
  await agent.post(`/api/Handovers/${ho.id}/confirm`);
  const rep = await agent.post<{ id: string }>(`/api/Handovers/${ho.id}/report`, {
    appointmentId: ho.id,
    participants: "Acquéreur, agent",
    observations: "Logement conforme (E2E)",
    items: [{ itemType: "Clés", quantity: 2 }],
  });
  await buyer.post(`/api/Handovers/reports/${rep.id}/acknowledge`, {});
  return j;
}

export async function createClaim(j: JourneyFixture, title = `Fuite ${uid()}`) {
  const buyer = await Api.as(j.buyer);
  const claim = await buyer.post<{ id: string }>("/api/after-sales/claims", {
    unitId: j.unitId,
    title,
    description: "Infiltration constatée (E2E)",
    category: 2,
    priority: 1,
  });
  j.claimId = claim.id;
  return { id: claim.id, title };
}

/** Moves a claim forward through the real state machine (lead qualifies and assigns). */
export async function advanceClaim(
  j: JourneyFixture,
  to: "UNDER_REVIEW" | "ASSIGNED" | "IN_PROGRESS" | "RESOLVED",
  technician: RoleKey = "technician",
) {
  const lead = await Api.as("techLead");
  const tech = await Api.as(technician);
  const path = `/api/after-sales/claims/${j.claimId}/status`;
  const order = ["UNDER_REVIEW", "ASSIGNED", "IN_PROGRESS", "RESOLVED"] as const;
  for (const step of order.slice(0, order.indexOf(to) + 1)) {
    if (step === "UNDER_REVIEW") await lead.put(path, { claimId: j.claimId, newStatus: ClaimStatus.UnderReview, note: "Qualification (E2E)" });
    if (step === "ASSIGNED") await lead.put(path, { claimId: j.claimId, newStatus: ClaimStatus.Assigned, assignedAgentId: tech.userId, note: "Affectation (E2E)" });
    if (step === "IN_PROGRESS") await tech.put(path, { claimId: j.claimId, newStatus: ClaimStatus.InProgress, note: "Intervention (E2E)" });
    if (step === "RESOLVED") await tech.put(path, { claimId: j.claimId, newStatus: ClaimStatus.Resolved, resolutionSummary: "Joint remplacé (E2E)" });
  }
}

export async function getClaim(claimId: string, as: RoleKey = "globalAdmin") {
  const api = await Api.as(as);
  const page = { data: await api.all<{ id: string; status: number; assignedAgentId?: string; title: string }>("/api/after-sales/claims") };
  return page.data.find((c) => c.id === claimId);
}

/** Full journey up to a given stage, in dependency order. */
export async function journey(
  upTo: "APPROVED" | "FINAL_VISIT" | "DRAFT_SALE" | "SOLD" | "DELIVERED" | "CLAIM",
  opts: { buyer?: RoleKey; warrantyMonths?: number; members?: RoleKey[]; agent?: RoleKey } = {},
): Promise<JourneyFixture> {
  const agent = opts.agent ?? (opts.members && !opts.members.includes("agent") && opts.members.includes("agentOther") ? "agentOther" : "agent");
  const p = await createProject({ phase: "SUR_PLAN", warrantyMonths: opts.warrantyMonths, members: opts.members });
  const j = await createReservation(p, { state: "APPROVED", buyer: opts.buyer, agent });
  if (upTo === "APPROVED") return j;
  await setConstructionPct(p, 100);
  await completeProject(p);
  await createFinalVisit(j);
  if (upTo === "FINAL_VISIT") return j;
  await createDraftSale(j);
  if (upTo === "DRAFT_SALE") return j;
  await createNotaryAppointment(j, "PURCHASE_COMPLETED");
  if (upTo === "SOLD") return j;
  await deliverUnit(j);
  if (upTo === "DELIVERED") return j;
  await createClaim(j);
  return j;
}

/** Confirms the dossier's notary appointment as the notary (a draft sale becomes PENDING_NOTARY). */
export async function confirmNotaryAppointment(j: JourneyFixture) {
  const notary = await Api.as("notary");
  await notary.put(`/api/NotaryAppointments/${j.notaryAppointmentId}`, { id: j.notaryAppointmentId, status: "Confirmed" });
}

export async function getSale(reservationId: string) {
  const admin = await Api.as("globalAdmin");
  return admin.get<SaleDto | null>(`/api/sales/by-reservation/${reservationId}`);
}

export interface SaleDto {
  id: string;
  reservationId: string;
  unitId: string;
  status: "Draft" | "PendingNotary" | "Confirmed" | "Cancelled";
  isEditable: boolean;
  projectName?: string;
  immeubleName?: string;
  floorName?: string;
  unitNumber?: string;
  buyerFirstName: string;
  buyerLastName: string;
  finalPrice?: number;
  reservationAmount?: number;
  remainingAmount?: number;
  warrantyMonths: number;
  notes?: string;
  confirmedAt?: string | null;
}

export async function getUnitStatus(p: ProjectFixture, unitId: string) {
  const admin = await Api.as("globalAdmin");
  const unit = p.units.find((u) => u.id === unitId)!;
  const page = await admin.get<{ data: { id: string; status: string }[] }>(`/api/Immeuble/by-immeuble?ImmeubleId=${unit.immeubleId}&PageSize=100`);
  return page.data.find((u) => u.id === unitId)?.status;
}

function sql(query: string) {
  const db = process.env.E2E_PROJECT_DB ?? "GPIA_Project_QA";
  const server = process.env.E2E_SQL_SERVER ?? ".\\SQLEXPRESS";
  return execFileSync("sqlcmd", ["-S", server, "-d", db, "-I", "-b", "-W", "-h", "-1", "-Q", `SET NOCOUNT ON; ${query}`], { stdio: "pipe" }).toString();
}

/** Runs raw SQL against the QA database and returns sqlcmd's output (test-only fault injection / probes). */
export const runSql = sql;

/**
 * Fault injection for atomicity tests: while `fn` runs, any INSERT of a sale on
 * this unit fails inside the database (AFTER INSERT trigger raising an error),
 * so the notary handler's transaction must roll back everything it did before.
 */
export async function withSaleInsertFailure<T>(unitId: string, fn: () => Promise<T>): Promise<T> {
  const name = `e2e_fail_sale_${unitId.replace(/-/g, "")}`;
  sql(`EXEC('CREATE TRIGGER [${name}] ON [Sales] AFTER INSERT AS IF EXISTS (SELECT 1 FROM inserted WHERE UnitId = ''${unitId}'') THROW 50001, ''e2e injected sale failure'', 1;')`);
  try {
    return await fn();
  } finally {
    sql(`DROP TRIGGER IF EXISTS [${name}]`);
  }
}

/**
 * Time travel for the warranty: no API can age a warranty, so this moves its
 * end date into the past directly in the QA database. Used only to reach the
 * "warranty expired" state; the rule itself is still asserted through the API/UI.
 */
export function expireWarranty(unitId: string) {
  const db = process.env.E2E_PROJECT_DB ?? "GPIA_Project_QA";
  const server = process.env.E2E_SQL_SERVER ?? ".\\SQLEXPRESS";
  execFileSync(
    "sqlcmd",
    ["-S", server, "-d", db, "-I", "-b", "-Q", `SET NOCOUNT ON; UPDATE Warranties SET StartsAt = DATEADD(month,-30,GETUTCDATE()), EndsAt = DATEADD(day,-1,GETUTCDATE()) WHERE UnitId = '${unitId}'`],
    { stdio: "pipe" },
  );
}

