    const local = new Date(when.getTime() - when.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    await page.getByLabel("Date et heure souhaitées").fill(local);
    await page.getByRole("button", { name: "Envoyer la demande" }).click();
    // The history table appears once the created appointment has been re-read.
    await expect(page.getByRole("heading", { name: "Rendez-vous notaire", exact: true })).toBeVisible();

    const buyer = await Api.as("buyer", true);
    const appts = { data: await buyer.all<{ reservationId: string; status: string }>("/api/NotaryAppointments") };
