2	
3	/**
4	 * Answers prompts with a value that can change between actions:
5	 *   const answer = promptAnswers(page); answer.next = "2027-01-10 10:00";
6	 */
7	export function promptAnswers(page: Page) {
8	  const state = { next: "" as string | null };
9	  page.on("dialog", (dialog) => {
10	    if (dialog.type() === "prompt" && state.next === null) void dialog.dismiss();
11	    else void dialog.accept(dialog.type() === "prompt" ? (state.next ?? "") : undefined);
12	  });
13	  return state;
14	}
15	
16	/** Answers every window.confirm/prompt on the page (prompt gets `promptValue`). */
17	export function acceptDialogs(page: Page, promptValue = "") {
18	  page.on("dialog", (dialog) => {
19	    void dialog.accept(dialog.type() === "prompt" ? promptValue : undefined);
20	  });
21	}
