23	/**
24	 * A list filter select by its caption. The <label> wraps the <select>, so its
25	 * accessible name also contains every option text — getByLabel cannot match it
26	 * exactly; the caption <span> can.
27	 */
28	export function listFilter(page: Page, caption: string) {
29	  return page.locator(".list-filters label").filter({ has: page.locator("span", { hasText: new RegExp(`^${caption}$`) }) }).locator("select");
30	}
31	
32	/**
33	 * A form control by its exact caption inside a <Field> (label > span).
34	 * Needed where option texts or placeholders repeat a caption word, which makes
35	 * getByLabel ambiguous (the label's accessible name includes the options).
36	 */
37	export function field(scope: Page | Locator, caption: string) {
38	  const escaped = caption.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
39	  // `has` is resolved relative to each label, so the inner locator must be page-rooted.
40	  const page = "page" in scope && typeof scope.page === "function" ? (scope as Locator).page() : (scope as Page);
41	  return scope
42	    .locator("label")
43	    .filter({ has: page.locator("span", { hasText: new RegExp(`^${escaped}$`) }) })
44	    .locator("select, input, textarea")
45	    .first();
46	}
