32	    /// <summary>
33	    /// Create a new after-sale claim. If BuyerId is not provided, we'll try to use the authenticated user id.
34	    /// </summary>
35	    [HttpPost]
36	    public async Task<ActionResult<object>> Create([FromBody] CreateAfterSaleClaimCommand cmd, CancellationToken ct)
37	    {
38	        // BuyerId is taken from the token, NOT merely defaulted from it.
39	        //
40	        // It used to be filled in only when the body left it blank, so a buyer
41	        // could send someone else's id and have the claim attributed to them:
42	        // the ownership check downstream verifies that THAT id owns the unit,
43	        // which it does, so the impersonation passed every check. §6.4 —
44	        // "un acheteur ne peut accéder qu'à ses propres données".
45	        //
46	        // An internal caller (admin/technician) may still file on a buyer's
47	        // behalf, which is a real workflow — a claim phoned in to the SAV desk.
48	        // Only a buyer/prospect caller is pinned to themselves.
49	        //
50	        // MUST go through ICurrentUser, not a raw ClaimTypes.NameIdentifier
51	        // lookup — this system's JWTs carry the id under a custom "userId"
52	        // claim, which ClaimTypes.NameIdentifier never matches (see CurrentUser.cs).
53	        var isInternal = _currentUser.Roles.Any(r => RoleCodes.Internal.Contains(r, StringComparer.Ordinal));
54	
55	        if (!isInternal && !string.IsNullOrEmpty(_currentUser.UserId))
56	        {
57	            cmd.BuyerId = _currentUser.UserId;
58	        }
59	        else if (string.IsNullOrWhiteSpace(cmd.BuyerId) && !string.IsNullOrEmpty(_currentUser.UserId))
60	        {
61	            cmd.BuyerId = _currentUser.UserId;
62	        }
63	
64	        try
65	        {
66	            var id = await _mediator.Send(cmd, ct);
67	            // No GetById handler exists, so return 200 with the id payload.
68	            return Ok(new { id });
69	        }
70	        catch (ValidationException ex)
71	        {
72	            // Handler throws FluentValidation.ValidationException for business rules
73	            return ValidationProblem(detail: ex.Message);
74	        }
75	    }
76	
77	    /// <summary>
78	    /// §20/§24.2 — attaches evidence (photo, short video, PDF) to a claim.
79	    ///
80	    /// Files, not URLs: the create-claim command used to accept a list of
81	    /// client-supplied addresses and store them verbatim. Uploads land in a
82	    /// private container and are read back only through the action below.
83	    /// Not role-gated here — a buyer attaches evidence to their OWN claim; the
84	    /// handler enforces which claims that is.
85	    /// </summary>
86	    [HttpPost("{claimId:guid}/attachments")]
87	    [ProducesResponseType(typeof(Application.Sales.AfterSales.Attachments.ClaimAttachmentResponse), StatusCodes.Status200OK)]
88	    [ProducesResponseType(StatusCodes.Status403Forbidden)]
