98	            throw new Application.Common.Exceptions.ValidationException(new[]
99	            {
100	                new FluentValidation.Results.ValidationFailure("File", "Aucun fichier n'a \u00e9t\u00e9 envoy\u00e9.")
101	            });
102	        }
103	
104	        command.ClaimId = claimId;
105	        return Ok(await _mediator.Send(command, ct));
106	    }
