test.describe("Workflow technicien", { tag: "@technician" }, () => {
  test("claim_workflow_follows_state_machine", async ({ page }) => {
    const j = await st.journey("CLAIM");
    const claim = (await st.getClaim(j.claimId!))!;
    await st.advanceClaim(j, "ASSIGNED", "technician");

    await page.goto("/admin/claims");
    const row = page.getByRole("row").filter({ hasText: claim.title });
    const status = () => st.getClaim(j.claimId!).then((c) => c?.status);

    // A technician never assigns, refuses or validates.
    await expect(row.getByRole("button", { name: "Affecter un technicien" })).toHaveCount(0);
    await expect(row.getByRole("button", { name: "Refuser" })).toHaveCount(0);

    await row.getByRole("button", { name: "Commencer l'examen" }).click();
    await expect.poll(status).toBe(st.ClaimStatus.UnderReview);
    await expect(row.getByRole("button", { name: "Résoudre" })).toHaveCount(0);

    await row.getByRole("button", { name: "Démarrer la résolution" }).click();
    await expect.poll(status).toBe(st.ClaimStatus.InProgress);

    await row.getByRole("button", { name: "Résoudre" }).click();
    const dialog = page.getByRole("dialog", { name: "Résoudre la réclamation" });
    await field(dialog, "Résumé de la résolution").fill("Siphon remplacé (E2E)");
    await dialog.getByRole("button", { name: "Résoudre" }).click();
    await expect(dialog).toBeHidden();
    await expect.poll(status).toBe(st.ClaimStatus.Resolved);
    await expect(row.getByRole("button", { name: "Valider la clôture" })).toHaveCount(0);

    // The technical lead validates.
    const lead = await Api.as("techLead");
    await lead.put(`/api/after-sales/claims/${j.claimId}/status`, { claimId: j.claimId, newStatus: st.ClaimStatus.Closed, note: "Validé (E2E)" });
    const final = (await st.getClaim(j.claimId!))!;
    expect(final.status).toBe(st.ClaimStatus.Closed);
    expect(final.history.map((h) => [h.fromStatus, h.toStatus])).toEqual([
      [st.ClaimStatus.Submitted, st.ClaimStatus.Assigned],
      [st.ClaimStatus.Assigned, st.ClaimStatus.UnderReview],
      [st.ClaimStatus.UnderReview, st.ClaimStatus.InProgress],
      [st.ClaimStatus.InProgress, st.ClaimStatus.Resolved],
      [st.ClaimStatus.Resolved, st.ClaimStatus.Closed],
    ]);
  });

  test("technician_can_add_work_done_comments_and_before_after_photos", async ({ page }) => {
    const j = await st.journey("CLAIM");
    await st.advanceClaim(j, "IN_PROGRESS", "technician");
    const claim = (await st.getClaim(j.claimId!))!;

    await page.goto("/admin/claims");
    await page.getByRole("row").filter({ hasText: claim.title }).getByRole("button", { name: "Détails" }).click();
    const dialog = page.getByRole("dialog", { name: `Réclamation — ${claim.title}` });
    await expect(dialog).toBeVisible();

    const work = `Remplacement du joint ${st.uid()}`;
    await field(dialog, "Type de message").selectOption("WORK_DONE");
    await field(dialog, "Message").fill(work);
    await dialog.getByRole("button", { name: "Ajouter le message" }).click();
    await expect(dialog.getByRole("region", { name: "Messages" })).toContainText(work);

    const attachments = dialog.getByRole("region", { name: "Pièces jointes" });
    await field(dialog, "Photo").selectOption("BEFORE");
    await dialog.getByLabel("Ajouter une photo").setInputFiles(png("avant.png"));
    await expect(attachments.getByRole("row").filter({ hasText: "avant.png" })).toContainText("Avant");
    await field(dialog, "Photo").selectOption("AFTER");
    await dialog.getByLabel("Ajouter une photo").setInputFiles(png("apres.png"));
    await expect(attachments.getByRole("row").filter({ hasText: "apres.png" })).toContainText("Après");

    const tech = await Api.as("technician");
    const saved = (await st.getClaim(j.claimId!))!;
    expect(saved.comments).toEqual(expect.arrayContaining([expect.objectContaining({ kind: "WORK_DONE", message: work, authorUserId: tech.userId })]));
    expect(saved.attachments.map((a) => [a.fileName, a.phase]).sort()).toEqual([
      ["apres.png", "AFTER"],
      ["avant.png", "BEFORE"],
    ]);

    // Another technician, not assigned, can neither read nor write on it.
    const other = await Api.as("technicianOther");
    await expectRefused(await other.raw("GET", `/api/after-sales/claims/${j.claimId}`), [403, 404], "unassigned technician reads claim");
    await expectRefused(
      await other.raw("POST", `/api/after-sales/claims/${j.claimId}/comments`, { message: "intrusion", kind: "WORK_DONE" }),
      [403, 404],
      "unassigned technician comments",
    );
  });
});

test.describe("Workflow responsable technique", { tag: "@techLead" }, () => {
  test("claim_invalid_transition_rejected", async ({ page }) => {
    const j = await st.journey("CLAIM");
    const claim = (await st.getClaim(j.claimId!))!;
    const lead = await Api.as("techLead");
    const path = `/api/after-sales/claims/${j.claimId}/status`;

    // Skipping steps is refused and leaves the claim untouched.
    for (const target of [st.ClaimStatus.UnderReview, st.ClaimStatus.InProgress, st.ClaimStatus.Resolved, st.ClaimStatus.Closed]) {
      const res = await lead.raw("PUT", path, { claimId: j.claimId, newStatus: target, resolutionSummary: "x", note: "x" });
      await expectRefused(res, [409, 422], `SUBMITTED -> ${target}`);
    }
    expect((await st.getClaim(j.claimId!))!.status).toBe(st.ClaimStatus.Submitted);
    expect((await st.getClaim(j.claimId!))!.history).toEqual([]);

    // The UI only offers the legal next steps.
    await page.goto("/admin/claims");
    const row = page.getByRole("row").filter({ hasText: claim.title });
    await expect(row.getByRole("button", { name: "Affecter un technicien" })).toBeVisible();
    await expect(row.getByRole("button", { name: "Refuser" })).toBeVisible();
    for (const name of ["Commencer l'examen", "Démarrer la résolution", "Résoudre", "Valider la clôture"]) {
      await expect(row.getByRole("button", { name })).toHaveCount(0);
    }

    // A closed claim cannot be reopened nor commented.
    await st.advanceClaim(j, "RESOLVED");
    await lead.put(path, { claimId: j.claimId, newStatus: st.ClaimStatus.Closed, note: "Validé" });
    await expectRefused(await lead.raw("PUT", path, { claimId: j.claimId, newStatus: st.ClaimStatus.InProgress }), [409, 422], "CLOSED -> IN_PROGRESS");
    await expectRefused(await lead.raw("POST", `/api/after-sales/claims/${j.claimId}/comments`, { message: "après clôture" }), [409], "comment on closed claim");
    expect((await st.getClaim(j.claimId!))!.status).toBe(st.ClaimStatus.Closed);
  });

  test("tech_lead_can_view_assign_and_validate", async ({ page }) => {
    const j = await st.journey("CLAIM");
    const claim = (await st.getClaim(j.claimId!))!;
    const tech = await Api.as("technician");

    await page.goto("/admin/claims");
    const row = page.getByRole("row").filter({ hasText: claim.title });
    await expect(row).toContainText(j.project.name);

    // View.
    await row.getByRole("button", { name: "Détails" }).click();
    const detail = page.getByRole("dialog", { name: `Réclamation — ${claim.title}` });
    await expect(detail).toContainText("Infiltration constatée (E2E)");
    await expect(detail).toContainText("Non assigné");
    await detail.getByRole("button", { name: /Fermer|×/ }).first().click();
    await expect(detail).toBeHidden();

    // Assign.
    await row.getByRole("button", { name: "Affecter un technicien" }).click();
    const dialog = page.getByRole("dialog", { name: "Affecter un technicien" });
    await field(dialog, "Technicien").selectOption(tech.userId);
    await expect(dialog).toBeHidden();
    await expect.poll(async () => (await st.getClaim(j.claimId!))?.status).toBe(st.ClaimStatus.Assigned);
    expect((await st.getClaim(j.claimId!))?.assignedAgentId).toBe(tech.userId);

    // Technician works it; the lead validates the closure.
    for (const step of ["UNDER_REVIEW", "IN_PROGRESS", "RESOLVED"] as const) {
      const path = `/api/after-sales/claims/${j.claimId}/status`;
      const target = { UNDER_REVIEW: st.ClaimStatus.UnderReview, IN_PROGRESS: st.ClaimStatus.InProgress, RESOLVED: st.ClaimStatus.Resolved }[step];
      await tech.put(path, { claimId: j.claimId, newStatus: target, resolutionSummary: "Réparé (E2E)" });
    }
    await page.reload();
    await row.getByRole("button", { name: "Valider la clôture" }).click();
    await expect.poll(async () => (await st.getClaim(j.claimId!))?.status).toBe(st.ClaimStatus.Closed);
    await expect(row).toContainText("Validée / fermée");
  });
});

