    await expect(dialog.getByRole("region", { name: "Messages" })).toContainText(work);
    // The buyer never picks a staff message type.
    await expect(field(dialog, "Type de message")).toHaveCount(0);

    const reply = `Disponible jeudi matin ${st.uid()}`;
    await field(dialog, "Votre réponse").fill(reply);
