    const buyer = await Api.as(j.buyer);
    const saved = (await st.getClaim(j.claimId!))!;
    // Even if the buyer sends a staff kind, it is recorded as a REPLY.
    await buyer.post(`/api/after-sales/claims/${j.claimId}/comments`, { message: "Forcé", kind: "WORK_DONE" });
