    expect(after.comments.find((c) => c.message === "Forcé")?.kind).toBe("REPLY");

    // Another buyer cannot read it.
    const other = await Api.as("buyerOther");
    await expectRefused(await other.raw("GET", `/api/after-sales/claims/${j.claimId}`), [403, 404], "other buyer reads claim");
  });

  test("claim_detail_shows_project_building_floor_unit", async ({ page }) => {
    const j = await st.journey("CLAIM");
    const claim = (await st.getClaim(j.claimId!))!;
    acceptDialogs(page);
    await page.goto("/my/sav");
    await page.getByRole("row").filter({ hasText: claim.title }).getByRole("button", { name: "Détails" }).click();
    const dialog = page.getByRole("dialog", { name: `Réclamation — ${claim.title}` });
    await expectUnitContext(dialog, j.project, unitOf(j));
  });
});

