import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, expectUnitContext, field, pickClaimUnit } from "./support/ui";

/**
 * Scope 9 — SAV / réclamations.
 *
 * A claim is only open on the buyer's own unit with a confirmed sale, delivered,
 * under an active warranty. Workflow (ClaimStateMachine):
 * SOUMISE → ASSIGNÉE → EN COURS D'EXAMEN → EN RÉSOLUTION → RÉSOLUE → VALIDÉE/FERMÉE.
