  "base64",
);
const png = (name: string) => ({ name, mimeType: "image/png", buffer: PNG });

async function eligibleUnitIds(buyer: Api) {
  return (await buyer.get<{ unitId: string }[]>("/api/after-sales/claims/eligible-units")).map((u) => u.unitId);
}

async function myClaimTitles(buyer: Api) {
  return (await buyer.all<{ title: string }>("/api/after-sales/claims/mine")).map((c) => c.title);
}

/** The unit is not offered by the buyer's form and a direct API call is refused with `code`. */
async function expectClaimRefused(page: Page, j: st.JourneyFixture, code: RegExp) {
  const buyer = await Api.as(j.buyer);
  expect(await eligibleUnitIds(buyer)).not.toContain(j.unitId);

  await page.goto("/my/sav");
  await page.getByRole("button", { name: "Nouvelle réclamation" }).click();
  await expect(page.getByRole("heading", { name: "Nouvelle réclamation" })).toBeVisible();
  await expect(page.locator("option", { hasText: j.project.name })).toHaveCount(0);

  const title = `Refusée ${st.uid()}`;
  const res = await buyer.raw("POST", "/api/after-sales/claims", { unitId: j.unitId, title, description: "x", category: 0, priority: 1 });
  await expectRefused(res, [409, 422], "claim creation");
  expect(await res.text()).toMatch(code);
  expect(await myClaimTitles(buyer)).not.toContain(title);
}

function unitOf(j: st.JourneyFixture) {
  return j.project.units.find((u) => u.id === j.unitId)!;
