import { expect, test, type Page } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, expectUnitContext, field, pickClaimUnit } from "./support/ui";

/**
 * Scope 9 — SAV / réclamations.
 *
 * A claim is only open on the buyer's own unit with a confirmed sale, delivered,
 * under an active warranty. Workflow (ClaimStateMachine):
 * SOUMISE → ASSIGNÉE → EN COURS D'EXAMEN → EN RÉSOLUTION → RÉSOLUE → VALIDÉE/FERMÉE.
 */

const PNG = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==",
  "base64",
);
const png = (name: string) => ({ name, mimeType: "image/png", buffer: PNG });

async function eligibleUnitIds(buyer: Api) {
  return (await buyer.get<{ unitId: string }[]>("/api/after-sales/claims/eligible-units")).map((u) => u.unitId);
}

async function myClaimTitles(buyer: Api) {
  return (await buyer.all<{ title: string }>("/api/after-sales/claims/mine")).map((c) => c.title);
}

/** The unit is not offered by the buyer's form and a direct API call is refused with `code`. */
async function expectClaimRefused(page: Page, j: st.JourneyFixture, code: RegExp) {
  const buyer = await Api.as(j.buyer);
  expect(await eligibleUnitIds(buyer)).not.toContain(j.unitId);

  await page.goto("/my/sav");
  await page.getByRole("button", { name: "Nouvelle réclamation" }).click();
  await expect(page.getByRole("heading", { name: "Nouvelle réclamation" })).toBeVisible();
  await expect(page.locator("option", { hasText: j.project.name })).toHaveCount(0);

  const title = `Refusée ${st.uid()}`;
  const res = await buyer.raw("POST", "/api/after-sales/claims", { unitId: j.unitId, title, description: "x", category: 0, priority: 1 });
  await expectRefused(res, [409, 422], "claim creation");
  expect(await res.text()).toMatch(code);
  expect(await myClaimTitles(buyer)).not.toContain(title);
}

function unitOf(j: st.JourneyFixture) {
  return j.project.units.find((u) => u.id === j.unitId)!;
}

// ---------------------------------------------------------------------------
// Conditions de création (acquéreur)
// ---------------------------------------------------------------------------
test.describe("Création d'une réclamation", { tag: "@buyer" }, () => {
  test("claim_requires_confirmed_sale", async ({ page }) => {
    const j = await st.journey("DRAFT_SALE");
    expect((await st.getSale(j.reservationId))?.status).toBe("Draft");
    await expectClaimRefused(page, j, /PROPERTY_NOT_DELIVERED/);
  });

  test("claim_requires_delivered_unit", async ({ page }) => {
    const j = await st.journey("SOLD");
    expect((await st.getSale(j.reservationId))?.status).toBe("Confirmed");
    await expectClaimRefused(page, j, /PROPERTY_NOT_DELIVERED/);
  });

  test("claim_requires_active_warranty", async ({ page }) => {
    const j = await st.journey("DELIVERED");
    st.runSql(`UPDATE Warranties SET IsActive = 0 WHERE UnitId = '${j.unitId}'`);
    await expectClaimRefused(page, j, /WARRANTY_EXPIRED/);
  });

  test("claim_blocked_after_warranty_expiry", async ({ page }) => {
    const j = await st.journey("DELIVERED");
    const buyer = await Api.as(j.buyer);
    expect(await eligibleUnitIds(buyer)).toContain(j.unitId);
    st.expireWarranty(j.unitId);
    await expectClaimRefused(page, j, /WARRANTY_EXPIRED/);
  });

  test("claim_cascade_shows_only_own_project_building_floor_unit_sale", async ({ page }) => {
    test.setTimeout(180_000);
    const mine = await st.journey("DELIVERED");
    const theirs = await st.journey("DELIVERED", { buyer: "buyerOther" });
    const buyer = await Api.as(mine.buyer);
    const ids = await eligibleUnitIds(buyer);
    expect(ids).toContain(mine.unitId);
    expect(ids).not.toContain(theirs.unitId);

    await page.goto("/my/sav");
    await page.getByRole("button", { name: "Nouvelle réclamation" }).click();
    await expect(field(page, "Projet").locator("option", { hasText: theirs.project.name })).toHaveCount(0);
    // Each level stays locked until the one above is chosen.
    await expect(field(page, "Étage")).toBeDisabled();
    await expect(field(page, "Unité")).toBeDisabled();
    await expect(field(page, "Vente")).toBeDisabled();

    const unit = unitOf(mine);
    await pickClaimUnit(page, { ...mine, saleId: (await st.getSale(mine.reservationId))!.id });
    // Only the chosen project's own building / floor / unit are listed.
    await expect(field(page, "Immeuble").locator("option:not([value=''])")).toHaveText([unit.immeubleName]);
    await expect(field(page, "Étage").locator("option:not([value=''])")).toHaveText([unit.floor]);
    await expect(field(page, "Unité").locator("option:not([value=''])")).toHaveText([unit.unitNumber]);
    await expect(field(page, "Vente").locator("option:not([value=''])")).toHaveCount(1);

    // Changing the project resets everything below it.
    await field(page, "Projet").selectOption("");
    await expect(field(page, "Immeuble")).toHaveValue("");
    await expect(field(page, "Unité")).toBeDisabled();
  });

  test("claim_form_persists_description_category_priority_attachments", async ({ page }) => {
    const j = await st.journey("DELIVERED");
    const title = `Fuite cuisine ${st.uid()}`;
    const description = "Fuite sous l'évier de la cuisine,\nconstatée le matin (E2E)";

    await page.goto("/my/sav");
    await page.getByRole("button", { name: "Nouvelle réclamation" }).click();
    await pickClaimUnit(page, j);
    await field(page, "Titre").fill(title);
    await field(page, "Description").fill(description);
    await field(page, "Catégorie").selectOption({ label: "Plomberie" });
    await field(page, "Priorité").selectOption({ label: "Haute" });
    await field(page, "Photos et pièces jointes").setInputFiles([png("fuite-1.png"), png("fuite-2.png")]);
    await page.getByRole("button", { name: "Envoyer" }).click();
    await expect(page.getByRole("row").filter({ hasText: title })).toHaveCount(1);

    const buyer = await Api.as(j.buyer);
    const created = (await buyer.all<{ id: string; title: string }>("/api/after-sales/claims/mine")).find((c) => c.title === title)!;
    expect(created).toBeTruthy();
    await expect
      .poll(orNull(async () => (await st.getClaim(created.id, j.buyer))?.attachments.length ?? 0))
      .toBe(2);
    const claim = (await st.getClaim(created.id, j.buyer))!;
    expect(claim.unitId).toBe(j.unitId);
    expect(claim.description).toBe(description);
    expect(claim.category).toBe(2); // Plumbing
    expect(claim.priority).toBe(2); // High
    expect(claim.status).toBe(st.ClaimStatus.Submitted);
    expect(claim.attachments.map((a) => a.fileName).sort()).toEqual(["fuite-1.png", "fuite-2.png"]);
  });
});

