root = r'C:\Users\LEGION\source\repos\whiredead\realestate\src\ProjectAPI'

os.remove(os.path.join(root, r'src\Api\Controllers\DeliveriesController.cs'))
shutil.rmtree(os.path.join(root, r'src\Api\Application\Sales\ScheduleDelivery'))


def rw(rel, fn):
    p = os.path.join(root, rel)
    raw = open(p, 'rb').read()
    bom = raw.startswith(b'\xef\xbb\xbf')
    text = raw.decode('utf-8-sig')
    crlf = '\r\n' in text
    text = text.replace('\r\n', '\n')
    text = fn(text)
    if crlf:
        text = text.replace('\n', '\r\n')
    open(p, 'wb').write((b'\xef\xbb\xbf' if bom else b'') + text.encode('utf-8'))


def tests(s):
    s = s.replace('using ProjectAPI.Api.Application.Sales.ScheduleDelivery;\n', '')
    a = s.index('    // ------------------------------------------------------------ ScheduleDelivery')
    b = s.index('    // ------------------------------------------------------------ ProjectAgentAssignmentConfig')
    s = s[:a] + s[b:]
    s = s.replace('''/// §6.4 — three unrelated but similarly-shaped gaps from the final Batch 1
/// completeness sweep: delivery scheduling/status had no project scope at
/// all; the agent-assignment-config''', '''/// §6.4 — similarly-shaped gaps from the final Batch 1 completeness sweep
/// (the legacy delivery scheduling flow they also covered has been removed —
/// Handovers is the only delivery flow): the agent-assignment-config''')
    return s


rw(r'tests\Enforcement\DeliveryAssignmentConfigAndBuyerOwnershipScopeTests.cs', tests)


