    old = '''                // wrote to it (N15). ScheduleDeliveryHandler also requires an
                // existing Sale — though the newer HandoversController path
                // (ScheduleHandoverHandler) doesn't, so handovers were never
                // actually blocked by this gap, only sales reporting was.'''
    assert old in s
    return s.replace(old, '''                // wrote to it (N15). Handovers (the only delivery flow) are
                // scheduled from the converted reservation.''')


rw(r'src\Api\Application\NotaryAppointments\UpdateNotaryAppointment\UpdateNotaryAppointmentHandler.cs', notary)
