import { useEffect, useState } from "react";
import { handoversApi } from "../../api";
import { ApiError } from "../../api/http/client";
import type { MyHandoverStatus, MyWarranty } from "../../types";
import { Button, Card, StatusBadge, Table } from "../../components/ui";
import { formatDate, formatDateTime } from "../../lib/format";

const HANDOVER_REPORT_STATUS_LABEL: Record<string, string> = {
  DRAFT: "Brouillon",
  SUBMITTED: "Soumis",
  AWAITING_BUYER_ACKNOWLEDGEMENT: "En attente de votre confirmation",
  ACKNOWLEDGED: "Confirmé",
  SUPERSEDED: "Remplacé",
};

/**
 * §8/§19/§20 buyer portal — handover status and warranty coverage for one
 * reservation. Both reads resolve only through Reservation.BuyerId
 * server-side (GetMyHandoverStatusHandler/GetMyWarrantiesHandler) — there is
 * no way to pass another buyer's reservation id and see their data. The
 * acknowledgement action is the one write this card offers: it is what
 * actually flips the unit to DELIVERED and starts the warranty (§5.8).
 */
export function BuyerHandoverCard({ reservationId }: { reservationId: string }) {
  const [handover, setHandover] = useState<MyHandoverStatus | null | undefined>(undefined);
  const [warranties, setWarranties] = useState<MyWarranty[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  function load() {
    handoversApi.getMyStatus(reservationId).then((h) => setHandover(h));
    handoversApi.getMyWarranties(reservationId).then((w) => setWarranties(w));
  }

  useEffect(load, [reservationId]);

  async function acknowledge() {
    if (!handover?.reportId) return;
    setError(null);
    setBusy(true);
    try {
      await handoversApi.acknowledge(handover.reportId);
      load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la confirmation de réception.");
    } finally {
      setBusy(false);
    }
  }

  // Nothing scheduled yet and no warranty started — the section has nothing
  // to show a buyer whose file hasn't reached delivery.
  if (handover === undefined) return null;
  if (handover === null && warranties.length === 0) return null;

  return (
    <Card>
      <h3>Livraison et garantie</h3>
      {error && <p className="form-error">{error}</p>}

      {handover && (
        <>
          <div className="stat-grid" style={{ marginBottom: 4 }}>
            <Card className="stat-card">
              <span className="stat-label">Rendez-vous de livraison</span>
              <span className="stat-value">{formatDateTime(handover.scheduledAt)}</span>
              {handover.location && <span className="stat-hint neutral">{handover.location}</span>}
              <span className="stat-hint neutral">
                <StatusBadge status={handover.appointmentStatus} />
              </span>
            </Card>
            {handover.reportStatus && (
              <Card className="stat-card">
                <span className="stat-label">Procès-verbal</span>
                <span className="stat-value">
                  <StatusBadge status={handover.reportStatus} label={HANDOVER_REPORT_STATUS_LABEL[handover.reportStatus]} />
                </span>
                {handover.acknowledgedAt && (
                  <span className="stat-hint neutral">Confirmé le {formatDate(handover.acknowledgedAt)}</span>
                )}
              </Card>
            )}
          </div>

          {handover.items.length > 0 && (
            <Table
              keyField={(i) => i.itemType}
              rows={handover.items}
              columns={[
                { header: "Élément", render: (i) => i.itemType },
                { header: "Quantité", render: (i) => i.quantity, align: "right" },
                { header: "Commentaire", render: (i) => i.comment ?? "-" },
              ]}
            />
          )}

          {handover.reportStatus === "AWAITING_BUYER_ACKNOWLEDGEMENT" && (
            <div className="modal-actions" style={{ marginTop: 12 }}>
              <Button onClick={acknowledge} disabled={busy}>
                {busy ? "…" : "Confirmer la réception"}
              </Button>
            </div>
          )}
        </>
      )}

      {warranties.length > 0 && (
        <>
          <h4 style={{ marginTop: handover ? 16 : 0 }}>Garanties</h4>
          <Table
            keyField={(w) => w.id}
            rows={warranties}
            columns={[
              { header: "Type", render: (w) => w.warrantyTypeCode },
              { header: "Début", render: (w) => formatDate(w.startsAt) },
              { header: "Fin", render: (w) => formatDate(w.endsAt) },
              {
                header: "Statut",
                render: (w) => <StatusBadge status={w.isActive ? "ACTIVE" : "EXPIRED"} label={w.isActive ? "Active" : "Expirée"} />,
              },
            ]}
          />
        </>
      )}
    </Card>
  );
}

