import { useState, type FormEvent } from "react";
import { Link } from "react-router-dom";
import { projectsApi } from "../../api";
import type { ProjectStatus } from "../../types";
import { Async, Button, Card, Field, Modal, PageHeader, StatusBadge, Table } from "../../components/ui";
import { useAsync } from "../../lib/useAsync";
import { placeLabel } from "../../lib/format";
import { useAuth } from "../../context/AuthContext";
import { ADMINS } from "../../lib/roles";
import { ApiError } from "../../api/http/client";
import { ImageUploadField } from "../../components/ui/ImageUploadField";
import { allPages } from "../../lib/pagination";

/**
 * Advancement as a filled track plus the figure. Scanning a column of bare
 * percentages gives no sense of which projects are nearly done; the bar does
 * that at a glance while the number stays exact.
 */
function ProgressCell({ value }: { value: number }) {
  const pct = Math.max(0, Math.min(100, value ?? 0));
  const done = pct >= 100;
  return (
    <span className="progress-cell">
      <span className="progress-cell-track" aria-hidden="true">
        <span className={`progress-cell-fill${done ? " is-done" : ""}`} style={{ width: `${pct}%` }} />
      </span>
      <span className="num progress-cell-value">{pct}%</span>
    </span>
  );
}

export default function ProjectsListPage() {
  const { user } = useAuth();
  // §6.3 — creating a project is "A périmètre" (admins). A SALES_AGENT reaches
  // this page to browse stock before creating a reservation, but must not be
  // offered create/edit. The API refuses either way (POST/PUT /api/Projects are
  // RoleGroups.Admins); this only stops us showing an action it would reject.
  const canManageProjects = !!user?.roles.some((role) => ADMINS.includes(role));

  const [showCreate, setShowCreate] = useState(false);
  const [images, setImages] = useState<string[]>([]);
  const [module3DLink, setModule3DLink] = useState("");
  const [creating, setCreating] = useState(false);
  const [createError, setCreateError] = useState<string | null>(null);
  const state = useAsync(() => allPages((page) => projectsApi.list({ ...page })).then((r) => r.data), []);
  const reload = state.reload;

  async function onCreate(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);

    setCreateError(null);
    setCreating(true);
    try {
      await projectsApi.create({
        name: String(form.get("name")),
        location: String(form.get("location")),
        address: String(form.get("address")),
        description: String(form.get("description")),
        type: String(form.get("type")),
        statusGlobal: String(form.get("statusGlobal")) as ProjectStatus,
        warrantyMonths: Number(form.get("warrantyMonths")) || undefined,
        module3DLink: module3DLink.trim() || undefined,
        // Real uploads, not a placeholder. Creation used to insert a
        // picsum.photos URL so the card had *something* to show — a stock
        // photograph of an unrelated building, published on the project's
        // public page as if it were the project.
        images,
      });
      setShowCreate(false);
      resetCreateForm();
      reload();
    } catch (err) {
      setCreateError(err instanceof ApiError ? err.message : "Échec de la création du projet.");
    } finally {
      setCreating(false);
    }
  }

  function resetCreateForm() {
    setImages([]);
    setModule3DLink("");
    setCreateError(null);
  }

  return (
    <div>
      <PageHeader
        title="Projets"
        subtitle="Résidences et programmes immobiliers"
        actions={
          canManageProjects ? <Button onClick={() => setShowCreate(true)}>+ Nouveau projet</Button> : undefined
        }
      />
      <Card>
        <Async state={state} isEmpty={(p) => p.length === 0} empty="Aucun projet pour le moment">
          {(projects) => (
            <Table
              keyField={(p) => p.id}
              rows={projects}
              columns={[
                {
                  header: "Projet",
                  render: (p) => (
                    <span className="cell-lede">
                      <Link to={`/admin/projects/${p.id}`}>{p.name}</Link>
                      <span className="cell-sub">
                        {placeLabel(p.location) ?? "—"}
                        {p.type ? ` · ${p.type}` : ""}
                      </span>
                    </span>
                  ),
                },
                {
                  header: "",
                  render: (p) => (
                    <Link to={`/admin/projects/${p.id}/explore`} className="link-arrow">
                      Explorer →
                    </Link>
                  ),
                },
                { header: "Statut", render: (p) => (p.statusGlobal ? <StatusBadge status={p.statusGlobal} /> : "-") },
                {
                  // A bare "100%" in a numeric column reads the same as "4%"
                  // when scanning; the filled track is what carries the state.
                  header: "Avancement",
                  render: (p) => <ProgressCell value={p.overAllProgress} />,
                },
                {
                  header: "Intérêt",
                  align: "right",
                  render: (p) => (
                    <span className="num">{p.numberLikes}<span className="cell-unit"> ♥</span></span>
                  ),
                },
              ]}
            />
          )}
        </Async>
      </Card>

      {showCreate && canManageProjects && (
        <Modal
          title="Nouveau projet"
          onClose={() => {
            if (creating) return;
            setShowCreate(false);
            resetCreateForm();
          }}
        >
          <form onSubmit={onCreate}>
            {createError && <p className="form-error" role="alert">{createError}</p>}
            <Field label="Nom"><input name="name" required disabled={creating} /></Field>
            <Field label="Localisation"><input name="location" required disabled={creating} /></Field>
            <Field label="Adresse"><input name="address" required disabled={creating} /></Field>
            <Field label="Type">
              <select name="type">
                <option>Appartements</option>
                <option>Bureaux</option>
                <option>Studios</option>
              </select>
            </Field>
            <Field label="Statut">
              {/* Seuls les codes §3 que le backend legacy sait écrire honnêtement
                  (voir enums.ts). DRAFT est pourtant requis à la création
                  (FR-CMS-001) — lacune backend, pas un choix UI. */}
              <select name="statusGlobal">
                <option value="PLANNED">PLANNED</option>
                <option value="IN_PROGRESS">IN_PROGRESS</option>
              </select>
            </Field>
            <Field label="Garantie (mois)">
              {/* §8 — copiée et gelée sur chaque vente à sa création. Vide = 12 mois. */}
              <input name="warrantyMonths" type="number" min="1" max="360" placeholder="12" disabled={creating} />
            </Field>
            <Field label="Description"><textarea name="description" rows={3} disabled={creating} /></Field>

            <ImageUploadField label="Photos" value={images} onChange={setImages} />

            <Field label="Lien visite 3D">
              <input
                type="url"
                value={module3DLink}
                onChange={(e) => setModule3DLink(e.target.value)}
                placeholder="https://…"
                disabled={creating}
              />
            </Field>

            <Button type="submit" disabled={creating}>{creating ? "Création…" : "Créer"}</Button>
          </form>
        </Modal>
      )}
    </div>
  );
}

