import { test, expect } from "@playwright/test";
import * as st from "../support/state";
import { openReservation, field } from "../support/ui";
import { storageStateFor } from "../support/accounts";
test.use({ storageState: storageStateFor("agent"), baseURL: "http://localhost:5173" });
test("profile", async ({ page }) => {
  test.setTimeout(300_000);
  const j = await st.journey("SOLD");
  const slow: string[] = [];
  page.on("requestfinished", async (r) => { const t = r.timing(); const d = t.responseEnd; if (d > 1000) slow.push(`${Math.round(d)}ms ${r.method()} ${r.url().replace(/[0-9a-f-]{36}/g, "{id}")}`); });
  const cdp = await page.context().newCDPSession(page);
  await cdp.send("Performance.enable");
  let t = Date.now();
  const detail = await openReservation(page, j.project.name, j.buyerLastName);
  console.log("open detail", Date.now() - t);
  let m = await cdp.send("Performance.getMetrics"); console.log("after open", JSON.stringify(m.metrics.filter(x => ["TaskDuration","ScriptDuration","LayoutDuration","RecalcStyleDuration","Nodes","JSHeapUsedSize"].includes(x.name))));
  t = Date.now();
  await detail.getByRole("button", { name: "Planifier la livraison" }).click();
  const dlg = page.getByRole("dialog").filter({ has: page.getByLabel("Lieu") }).last();
  await field(dlg, "Date et heure").fill("2027-09-01T09:00");
  console.log("fill", Date.now() - t); t = Date.now();
  await dlg.locator("button[type=submit]").click();
  await expect(dlg).toBeHidden({ timeout: 120000 });
  console.log("schedule closed", Date.now() - t);
  m = await cdp.send("Performance.getMetrics"); console.log("after", JSON.stringify(m.metrics.filter(x => ["TaskDuration","ScriptDuration","LayoutDuration","RecalcStyleDuration","Nodes"].includes(x.name))));
  console.log(slow.join("\n"));
});
EOF
npx playwright test -c tests/.scratch/pw.config.ts tests/.scratch/profile-res.spec.ts 2>&1 | grep -vE "^\s*$" | tail -30

