import os
ROOT = r'C:\Users\LEGION\source\repos\whiredead\realestate\src\ProjectAPI\src'


def write_new(rel, text):
    p = os.path.join(ROOT, rel)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'wb') as f:
        f.write(text.replace('\r\n', '\n').replace('\n', '\r\n').encode('utf-8'))
    print('new', rel)


def edit(rel, pairs):
    p = os.path.join(ROOT, rel)
    raw = open(p, 'rb').read()
    bom = raw.startswith(b'\xef\xbb\xbf')
    s = raw.decode('utf-8-sig')
    crlf = '\r\n' in s
    s = s.replace('\r\n', '\n')
    for a, b in pairs:
        assert s.count(a) == 1, (rel, a[:80], s.count(a))
        s = s.replace(a, b)
    if crlf:
        s = s.replace('\n', '\r\n')
    open(p, 'wb').write((b'\xef\xbb\xbf' if bom else b'') + s.encode('utf-8'))
    print('edited', rel)


