import { useEffect, useState, type FormEvent } from "react";
import { typeBiensApi } from "../../api";
import { ApiError } from "../../api/http/client";
import type { TypeBien } from "../../types";
import { Button, Card, Field, Loading, Modal, PageHeader, Table } from "../../components/ui";

/** Reads a number input, treating an empty field as "not recorded" rather than 0. */
function optionalNumber(value: FormDataEntryValue | null): number | undefined {
  const text = String(value ?? "").trim();
  return text === "" ? undefined : Number(text);
}

function optionalText(value: FormDataEntryValue | null): string | undefined {
  const text = String(value ?? "").trim();
  return text === "" ? undefined : text;
}

export default function TypeBiensPage() {
  const [items, setItems] = useState<TypeBien[] | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [editing, setEditing] = useState<TypeBien | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function reload() {
    typeBiensApi.list().then(setItems);
  }
  useEffect(reload, []);

  async function onCreate(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);

    setError(null);
    setBusy(true);
    try {
      await typeBiensApi.create({
        name: String(form.get("name")),
        description: optionalText(form.get("description")),
        nbrChambre: optionalNumber(form.get("nbrChambre")),
        nbrSalleDeBain: optionalNumber(form.get("nbrSalleDeBain")),
        nbrDouche: optionalNumber(form.get("nbrDouche")),
        nbrParking: optionalNumber(form.get("nbrParking")),
        minSurface: optionalNumber(form.get("minSurface")),
        maxSurface: optionalNumber(form.get("maxSurface")),
        module3DLink: optionalText(form.get("module3DLink")),
      });
      setShowCreate(false);
      reload();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la création du type de bien.");
    } finally {
      setBusy(false);
    }
  }

  async function onEdit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!editing) return;
    const form = new FormData(e.currentTarget);

    setError(null);
    setBusy(true);
    try {
      await typeBiensApi.update(editing.id, {
        name: String(form.get("name")),
        description: optionalText(form.get("description")),
        nbrChambre: optionalNumber(form.get("nbrChambre")),
        nbrSalleDeBain: optionalNumber(form.get("nbrSalleDeBain")),
        nbrDouche: optionalNumber(form.get("nbrDouche")),
        nbrParking: optionalNumber(form.get("nbrParking")),
        minSurface: optionalNumber(form.get("minSurface")),
        maxSurface: optionalNumber(form.get("maxSurface")),
        module3DLink: optionalText(form.get("module3DLink")),
      });
      setEditing(null);
      reload();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la modification du type de bien.");
    } finally {
      setBusy(false);
    }
  }

  /** Refused by the API while a project, building or appointment references the type. */
  async function remove(t: TypeBien) {
    if (!confirm(`Supprimer le type de bien « ${t.name} » ?`)) return;
    setError(null);
    try {
      await typeBiensApi.remove(t.id);
      reload();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la suppression du type de bien.");
    }
  }

  /**
   * The layout fields, shared by create and edit so the two forms cannot drift.
   * Every one is optional: an empty input means "not recorded", which is what
   * the API stores as null — 0 chambres and "nobody filled this in" are
   * different statements about a property.
   */
  // A render function, not a nested component: a component declared inside
  // the page gets a new identity on every render, so React remounted the
  // inputs (wiping what the user typed) whenever the list reloaded.
  function renderLayoutFields(value?: TypeBien) {
    return (
      <>
        <Field label="Nom"><input name="name" defaultValue={value?.name ?? ""} required disabled={busy} /></Field>
        <Field label="Description"><input name="description" defaultValue={value?.description ?? ""} disabled={busy} /></Field>
        <Field label="Chambres">
          <input name="nbrChambre" type="number" min="0" defaultValue={value?.nbrChambre ?? ""} disabled={busy} />
        </Field>
        <Field label="Salles de bain">
          <input name="nbrSalleDeBain" type="number" min="0" defaultValue={value?.nbrSalleDeBain ?? ""} disabled={busy} />
        </Field>
        <Field label="Salles de douche">
          {/* Comptées à part des salles de bain : annoncer « 2 salles de bain »
              quand l'une est une salle de douche décrit un autre bien. */}
          <input name="nbrDouche" type="number" min="0" defaultValue={value?.nbrDouche ?? ""} disabled={busy} />
        </Field>
        <Field label="Parking (places)">
          <input name="nbrParking" type="number" min="0" defaultValue={value?.nbrParking ?? ""} disabled={busy} />
        </Field>
        <Field label="Surface min (m²)">
          <input name="minSurface" type="number" min="0" defaultValue={value?.minSurface ?? ""} disabled={busy} />
        </Field>
        <Field label="Surface max (m²)">
          <input name="maxSurface" type="number" min="0" defaultValue={value?.maxSurface ?? ""} disabled={busy} />
        </Field>
        <Field label="Lien visite 3D">
          {/* Propre au plan, distinct de la visite 3D du projet. Le serveur
              refuse les domaines non autorisés. */}
          <input name="module3DLink" type="url" placeholder="https://…" defaultValue={value?.module3DLink ?? ""} disabled={busy} />
        </Field>
      </>
    );
  }

  return (
    <div>
      <PageHeader
        title="Types de biens"
        subtitle="Studios, appartements, bureaux…"
        actions={<Button onClick={() => setShowCreate(true)}>+ Nouveau type</Button>}
      />
      <Card>
        {error && !showCreate && !editing && <p className="form-error" role="alert">{error}</p>}
        {!items ? (
          <Loading />
        ) : (
          <Table
            keyField={(t) => String(t.id)}
            rows={items}
            columns={[
              { header: "Nom", render: (t) => t.name },
              { header: "Description", render: (t) => t.description ?? "-" },
              { header: "Ch.", align: "right", render: (t) => t.nbrChambre ?? "-" },
              { header: "SdB", align: "right", render: (t) => t.nbrSalleDeBain ?? "-" },
              { header: "Douches", align: "right", render: (t) => t.nbrDouche ?? "-" },
              { header: "Parking", align: "right", render: (t) => t.nbrParking ?? "-" },
              {
                header: "3D",
                render: (t) =>
                  t.module3DLink ? (
                    <a href={t.module3DLink} target="_blank" rel="noopener noreferrer">
                      Visiter →
                    </a>
                  ) : (
                    "-"
                  ),
              },
              {
                header: "",
                render: (t) => (
                  <span style={{ display: "flex", gap: 8 }}>
                    <button className="btn btn-ghost" onClick={() => setEditing(t)}>
                      Modifier
                    </button>
                    <button className="btn btn-ghost" onClick={() => remove(t)}>
                      Supprimer
                    </button>
                  </span>
                ),
              },
            ]}
          />
        )}
      </Card>

      {showCreate && (
        <Modal
          title="Nouveau type de bien"
          onClose={() => {
            if (!busy) setShowCreate(false);
          }}
        >
          <form onSubmit={onCreate}>
            {error && <p className="form-error" role="alert">{error}</p>}
            {renderLayoutFields()}
            <Button type="submit" disabled={busy}>{busy ? "Création…" : "Créer"}</Button>
          </form>
        </Modal>
      )}

      {editing && (
        <Modal
          title={`Modifier — ${editing.name}`}
          onClose={() => {
            if (!busy) setEditing(null);
          }}
        >
          <form onSubmit={onEdit}>
            {error && <p className="form-error" role="alert">{error}</p>}
            {renderLayoutFields(editing)}
            <Button type="submit" disabled={busy}>{busy ? "Enregistrement…" : "Enregistrer"}</Button>
          </form>
        </Modal>
      )}
    </div>
  );
}

