      setShowManual(true);
    }

    setBusy(false);
    if (inputRef.current) inputRef.current.value = "";
  }

  function addManual() {
    const url = manualUrl.trim();
    if (!url) return;
    onChange(multiple ? [...value, url] : [url]);
    setManualUrl("");
  }

  return (
    <div className="field">
      <span>{label}</span>

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        <input
          ref={inputRef}
          type="file"
          accept="image/*"
          multiple={multiple}
          onChange={(e) => handleFiles(e.target.files)}
          disabled={busy}
          style={{ flex: 1, minWidth: 180 }}
        />
        {busy && <span className="muted small">Envoi en cours…</span>}
        {!showManual && !busy && (
          <button type="button" className="btn btn-ghost" onClick={() => setShowManual(true)}>
            Saisir une URL
          </button>
        )}
      </div>

      {error && (
        <p className="form-error" style={{ marginTop: 8, marginBottom: 0 }}>
          {error} Vous pouvez saisir une URL d'image manuellement.
        </p>
      )}

      {showManual && (
        <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
          <input
            type="url"
            placeholder="https://…"
            value={manualUrl}
            onChange={(e) => setManualUrl(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                addManual();
              }
            }}
            style={{ flex: 1 }}
          />
          <button type="button" className="btn btn-secondary" onClick={addManual}>
            Ajouter
          </button>
        </div>
      )}

      {value.length > 0 && (
        <div className="upload-preview">
          {value.map((url) => (
            <span key={url} className="upload-thumb">
              <img src={url} alt="" loading="lazy" />
              <button
                type="button"
                aria-label="Retirer l'image"
                onClick={() => onChange(value.filter((u) => u !== url))}
              >
                ×
              </button>
            </span>
          ))}
        </div>
      )}
    </div>
  );

