import { useEffect, useState, type FormEvent } from "react";
import { projectsApi } from "../../api";
import { ApiError } from "../../api/http/client";
import type { Quartier, QuartierFeature } from "../../types";
import { Button, Card, Field, Loading, Modal, PageHeader, Table } from "../../components/ui";
import { ImageUploadField } from "../../components/ui/ImageUploadField";

/** Quartier.images is one comma-separated column on the server. */
function splitImages(packed?: string | null): string[] {
  return (packed ?? "").split(",").map((s) => s.trim()).filter(Boolean);
}

/**
 * §7.2 — the quartier referential (neighbourhoods projects are grouped into):
 * name, description, optional image(s), and a list of features (title,
 * description, optional image).
 *
 * Deletion is refused by the API (409) while a project is attached.
 *
 * Per-project amenity chips ("écoles", "transports") are NOT here: they belong
 * to a project, not to the quartier, and are managed on the project page.
 */
export default function QuartiersPage() {
  const [items, setItems] = useState<Quartier[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [editing, setEditing] = useState<Quartier | null>(null);
  const [featuresOf, setFeaturesOf] = useState<Quartier | null>(null);
  const [images, setImages] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  function reload() {
    projectsApi
      .listQuartiers()
      .then((list) => {
        setItems(list);
        setLoadError(null);
      })
      .catch((err) => {
        setItems([]);
        setLoadError(err instanceof ApiError ? err.message : "Échec du chargement des quartiers.");
      });
  }
  useEffect(reload, []);

  function openCreate() {
    setImages([]);
    setFormError(null);
    setShowCreate(true);
  }

  function openEdit(q: Quartier) {
    setImages(splitImages(q.images));
    setFormError(null);
    setEditing(q);
  }

  async function onCreate(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);

    setFormError(null);
    setBusy(true);
    try {
      await projectsApi.createQuartier({
        name: String(form.get("name")),
        description: String(form.get("description") || ""),
        images: images.join(","),
      });
      setShowCreate(false);
      reload();
    } catch (err) {
      setFormError(err instanceof ApiError ? err.message : "Échec de la création du quartier.");
    } finally {
      setBusy(false);
    }
  }

  async function onEdit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!editing) return;
    const form = new FormData(e.currentTarget);

    setFormError(null);
    setBusy(true);
    try {
      await projectsApi.updateQuartier(editing.id, {
        name: String(form.get("name")),
        description: String(form.get("description") || ""),
        images: images.join(","),
      });
      setEditing(null);
      reload();
    } catch (err) {
      setFormError(err instanceof ApiError ? err.message : "Échec de la modification du quartier.");
    } finally {
      setBusy(false);
    }
  }

  async function onRemove(q: Quartier) {
    if (!window.confirm(`Supprimer le quartier « ${q.name} » ?`)) return;
    setBusy(true);
    try {
      await projectsApi.removeQuartier(q.id);
      setLoadError(null);
      reload();
    } catch (err) {
      setLoadError(err instanceof ApiError ? err.message : "Échec de la suppression du quartier.");
    } finally {
      setBusy(false);
    }
  }

  /** Shared by create and edit so the two forms cannot drift apart. */
  // A render function, not a nested component: a component declared inside
  // the page gets a new identity on every render, so React remounted the
  // inputs (wiping what the user typed) whenever the list reloaded.
  function renderQuartierFields(value?: Quartier) {
    return (
      <>
        <Field label="Nom">
          <input name="name" defaultValue={value?.name ?? ""} maxLength={200} required disabled={busy} />
        </Field>
        <Field label="Description">
          <textarea name="description" rows={3} defaultValue={value?.description ?? ""} disabled={busy} />
        </Field>
        {/* Facultative. Stored server-side as one comma-separated column. */}
        <ImageUploadField label="Images (facultatif)" value={images} onChange={setImages} />
      </>
    );
  }

  return (
    <div>
      <PageHeader
        title="Quartiers"
        subtitle="Référentiel des quartiers auxquels les projets sont rattachés"
        actions={<Button onClick={openCreate}>+ Nouveau quartier</Button>}
      />
      <Card>
        {loadError && <p className="form-error" role="alert">{loadError}</p>}
        {!items ? (
          <Loading />
        ) : (
          <Table
            keyField={(q) => q.id}
            rows={items}
            emptyLabel="Aucun quartier enregistré"
            columns={[
              { header: "Nom", render: (q) => q.name },
              { header: "Description", render: (q) => q.description || "-" },
              { header: "Images", align: "right", render: (q) => splitImages(q.images).length },
              {
                header: "",
                render: (q) => (
                  <span style={{ display: "flex", gap: 8 }}>
                    <button className="btn btn-ghost" onClick={() => openEdit(q)}>
                      Modifier
                    </button>
                    <button className="btn btn-ghost" onClick={() => setFeaturesOf(q)}>
                      Fonctionnalités
                    </button>
                    <button className="btn btn-ghost" disabled={busy} onClick={() => onRemove(q)}>
                      Supprimer
                    </button>
                  </span>
                ),
              },
            ]}
          />
        )}
      </Card>

      {showCreate && (
        <Modal
          title="Nouveau quartier"
          onClose={() => {
            if (!busy) setShowCreate(false);
          }}
        >
          <form onSubmit={onCreate}>
            {formError && <p className="form-error" role="alert">{formError}</p>}
            {renderQuartierFields()}
            <Button type="submit" disabled={busy}>{busy ? "Création…" : "Créer"}</Button>
          </form>
        </Modal>
      )}

      {editing && (
        <Modal
          title={`Modifier — ${editing.name}`}
          onClose={() => {
            if (!busy) setEditing(null);
          }}
        >
          <form onSubmit={onEdit}>
            {formError && <p className="form-error" role="alert">{formError}</p>}
            <p className="muted small">
              Le nom est repris sur la fiche publique de chaque projet rattaché à ce quartier.
            </p>
            {renderQuartierFields(editing)}
            <Button type="submit" disabled={busy}>{busy ? "Enregistrement…" : "Enregistrer"}</Button>
          </form>
        </Modal>
      )}

      {featuresOf && (
        <Modal title={`Fonctionnalités — ${featuresOf.name}`} onClose={() => setFeaturesOf(null)}>
          <QuartierFeaturesEditor quartierId={featuresOf.id} />
        </Modal>
      )}
    </div>
  );
}

/** Add / edit / delete the features of one quartier; every change re-reads the list. */
function QuartierFeaturesEditor({ quartierId }: { quartierId: string }) {
  const [features, setFeatures] = useState<QuartierFeature[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  // null = adding a new feature; otherwise the feature being edited.
  const [editing, setEditing] = useState<QuartierFeature | null>(null);
  const [image, setImage] = useState<string[]>([]);
  const [formKey, setFormKey] = useState(0);

  async function load() {
    try {
      setFeatures(await projectsApi.listQuartierFeatures(quartierId));
    } catch (err) {
      setFeatures([]);
      setError(err instanceof ApiError ? err.message : "Échec du chargement des fonctionnalités.");
    }
  }
  useEffect(() => {
    void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [quartierId]);

  function resetForm() {
    setEditing(null);
    setImage([]);
    setFormKey((k) => k + 1);
  }

  function startEdit(f: QuartierFeature) {
    setEditing(f);
    setImage(f.image ? [f.image] : []);
    setFormKey((k) => k + 1);
  }

  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const data = {
      title: String(form.get("title") || "").trim(),
      description: String(form.get("description") || "").trim(),
      image: image[0] ?? "",
    };
    setError(null);
    setBusy(true);
    try {
      if (editing) await projectsApi.updateQuartierFeature(editing.id, data);
      else await projectsApi.addQuartierFeature(quartierId, data);
      resetForm();
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de l'enregistrement de la fonctionnalité.");
    } finally {
      setBusy(false);
    }
  }

  async function remove(f: QuartierFeature) {
    if (!window.confirm(`Supprimer la fonctionnalité « ${f.title} » ?`)) return;
    setError(null);
    setBusy(true);
    try {
      await projectsApi.removeQuartierFeature(f.id);
      if (editing?.id === f.id) resetForm();
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la suppression de la fonctionnalité.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      {error && <p className="form-error" role="alert">{error}</p>}
      {!features ? (
        <Loading />
      ) : (
        <Table
          keyField={(f) => f.id}
          rows={features}
          emptyLabel="Aucune fonctionnalité"
          columns={[
            { header: "Titre", render: (f) => f.title },
            { header: "Description", render: (f) => f.description || "-" },
            {
              header: "Image",
              render: (f) => (f.image ? <img src={f.image} alt={f.title} style={{ height: 32, borderRadius: 4 }} /> : "-"),
            },
            {
              header: "",
              render: (f) => (
                <span style={{ display: "flex", gap: 8 }}>
                  <button className="btn btn-ghost" disabled={busy} onClick={() => startEdit(f)}>
                    Modifier
                  </button>
                  <button className="btn btn-ghost" disabled={busy} onClick={() => remove(f)}>
                    Supprimer
                  </button>
                </span>
              ),
            },
          ]}
        />
      )}

      <form key={formKey} onSubmit={submit} style={{ marginTop: 16 }} aria-label="Fonctionnalité du quartier">
        <h4 style={{ margin: "0 0 8px" }}>{editing ? `Modifier « ${editing.title} »` : "Ajouter une fonctionnalité"}</h4>
        <Field label="Titre">
          <input name="title" required maxLength={200} defaultValue={editing?.title ?? ""} disabled={busy} />
        </Field>
        <Field label="Description de la fonctionnalité">
          <textarea name="description" rows={2} maxLength={2000} defaultValue={editing?.description ?? ""} disabled={busy} />
        </Field>
        <ImageUploadField label="Image de la fonctionnalité (facultatif)" value={image} onChange={setImage} multiple={false} />
        <div style={{ display: "flex", gap: 8 }}>
          <Button type="submit" disabled={busy}>{editing ? "Enregistrer la fonctionnalité" : "Ajouter la fonctionnalité"}</Button>
          {editing && (
            <Button type="button" variant="secondary" onClick={resetForm} disabled={busy}>
              Annuler
            </Button>
          )}
        </div>
      </form>
    </div>
  );
}

