/** A 1×1 PNG, the smallest real image the storage and media policy accept. */
export const PNG_1PX = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==",
  "base64",
);

/** Uploads a file to the API's own storage (POST /api/File/upload) and returns its public URL. */
export async function uploadToStorage(name = `e2e-${uid()}.png`, buffer = PNG_1PX, mimeType = "image/png") {
  const a = await admin();
  const res = await a.ctx.post(`${PROJECT_API_BASE}/api/File/upload`, {
    multipart: { Files: { name, mimeType, buffer } },
  });
  const text = await res.text();
  if (!res.ok()) throw new Error(`upload -> ${res.status()} ${text}`);
  const links = (JSON.parse(text) as { fileLinks: string[] | null }).fileLinks ?? [];
  if (links.length === 0) throw new Error("upload returned no link");
  return links[0];
}
