test.describe("Types de biens", { tag: "@projectAdmin" }, () => {
  test("property_type_persists_all_fields", async ({ page }) => {
    const name = `T3 E2E ${st.uid()}`;
    const tour = await st.uploadToStorage(`visite-${st.uid()}.png`);

    await page.goto("/admin/type-biens");
    await page.getByRole("button", { name: "+ Nouveau type" }).click();
    const dialog = page.getByRole("dialog", { name: "Nouveau type de bien" });
    await field(dialog, "Nom").fill(name);
    await field(dialog, "Description").fill("Trois pièces traversant");
    await field(dialog, "Chambres").fill("2");
    await field(dialog, "Salles de bain").fill("1");
    await field(dialog, "Salles de douche").fill("1");
    await field(dialog, "Parking (places)").fill("1");
    await field(dialog, "Surface min (m²)").fill("78");
    await field(dialog, "Surface max (m²)").fill("96");
    await field(dialog, "Lien visite 3D").fill(tour);
    await uploadImage(page, dialog, "Photo", "t3.png");
    await dialog.getByRole("button", { name: "Créer" }).click();
    await expect(dialog).toBeHidden();

    await expect.poll(orNull(() => findTypeBien(name))).not.toBeNull();
    const t = (await findTypeBien(name))!;
    expect(t).toMatchObject({
      description: "Trois pièces traversant",
      nbrChambre: 2,
      nbrSalleDeBain: 1,
      nbrDouche: 1,
      nbrParking: 1,
      minSurface: 78,
      maxSurface: 96,
      module3DLink: tour,
    });
    expect(t.image ?? "").toMatch(/^https:\/\/.+t3/);

    // Re-read in the UI after a reload.
    await page.reload();
    const row = page.getByRole("row").filter({ hasText: name });
    await expect(row).toContainText("78 – 96");
    await expect(row.getByRole("img", { name })).toBeVisible();
  });

  test("property_type_rejects_min_area_greater_than_max", async ({ page }) => {
    const name = `Incohérent ${st.uid()}`;
    await page.goto("/admin/type-biens");
    await page.getByRole("button", { name: "+ Nouveau type" }).click();
    const dialog = page.getByRole("dialog", { name: "Nouveau type de bien" });
    await field(dialog, "Nom").fill(name);
    await field(dialog, "Surface min (m²)").fill("120");
    await field(dialog, "Surface max (m²)").fill("80");
    await dialog.getByRole("button", { name: "Créer" }).click();
    await expect(dialog.getByRole("alert")).toContainText(/surface minimale/i);
    await expect(dialog).toBeVisible();
    expect(await findTypeBien(name)).toBeNull();

    // The API refuses it on its own, on create and on update.
    const admin = await Api.as("globalAdmin");
    await expectRefused(await admin.raw("POST", "/api/TypeBiens", { name, minSurface: 120, maxSurface: 80 }), [400, 422], "create min > max");
    expect(await findTypeBien(name)).toBeNull();
    const ok = await admin.post<{ id: number }>("/api/TypeBiens", { name: `${name} valide`, minSurface: 60, maxSurface: 80 });
    await expectRefused(
      await admin.raw("PUT", `/api/TypeBiens/${ok.id}`, { id: ok.id, name: `${name} valide`, minSurface: 120, maxSurface: 80 }),
      [400, 422],
      "update min > max",
    );
    expect((await findTypeBien(`${name} valide`))?.minSurface).toBe(60);
  });

  test("project_can_link_one_or_many_property_types", async ({ page }) => {
    const admin = await Api.as("globalAdmin");
    const suffix = st.uid();
    const t1 = await admin.post<{ id: number }>("/api/TypeBiens", { name: `Studio ${suffix}`, minSurface: 30, maxSurface: 40 });
    const t2 = await admin.post<{ id: number }>("/api/TypeBiens", { name: `T4 ${suffix}`, minSurface: 110, maxSurface: 130 });
    const p = await st.createProject({ units: 1 });
    const linked = async () => (await admin.get<{ id: number }[]>(`/api/Projects/${p.id}/type-biens`)).map((t) => t.id).sort();

    // One type.
    await page.goto(`/admin/projects/${p.id}`);
    await page.getByRole("button", { name: "Modifier", exact: true }).click();
    let edit = page.getByRole("dialog", { name: "Modifier le projet" });
    await edit.getByRole("checkbox", { name: `Studio ${suffix}` }).check();
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    await expect.poll(linked).toEqual([t1.id]);

    // Many types.
    await page.getByRole("button", { name: "Modifier", exact: true }).click();
    edit = page.getByRole("dialog", { name: "Modifier le projet" });
    await expect(edit.getByRole("checkbox", { name: `Studio ${suffix}` })).toBeChecked();
    await edit.getByRole("checkbox", { name: `T4 ${suffix}` }).check();
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    await expect.poll(linked).toEqual([t1.id, t2.id].sort());
    await expect(page.locator(".feature-chip", { hasText: `T4 ${suffix}` })).toBeVisible();

    // Unlink one.
    await page.getByRole("button", { name: "Modifier", exact: true }).click();
    edit = page.getByRole("dialog", { name: "Modifier le projet" });
    await edit.getByRole("checkbox", { name: `Studio ${suffix}` }).uncheck();
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    await expect.poll(linked).toEqual([t2.id]);
  });
});
