/**
 * Stable business error codes (backend `BusinessErrorCodes`, spec §31.7).
 * Branch on these — never on `message`, which is localised and may change.
 */
export type BusinessErrorCode =
  | "UNIT_NOT_AVAILABLE"
  | "APPOINTMENT_SLOT_CONFLICT"
  | "RESOURCE_VERSION_CONFLICT"
  // Still referenced by other data (FK violation / in-use check) — HTTP 409.
  | "RESOURCE_IN_USE"
  | "IDEMPOTENCY_KEY_REUSED"
  | "INVALID_STATUS_TRANSITION"
  | "MISSING_REQUIRED_DOCUMENT"
  | "DISCOUNT_LIMIT_EXCEEDED"
  | "PROJECT_PROGRESS_INCOMPLETE"
  | "INVALID_REPORT_RESULT"
  | "NOTARY_NOT_ELIGIBLE"
  | "VALIDATION_FAILED"
  | "NOT_FOUND"
  | "UNAUTHORIZED"
  // §6.4 — authenticated and correctly roled, but outside the caller's project
  // perimeter / not their own dossier. Returned as HTTP 403.
  | "PROJECT_SCOPE_DENIED"
  // §6.4 — the owning agent may not approve their own reservation (HTTP 403).
  | "SELF_APPROVAL_FORBIDDEN"
  | "INTERNAL_ERROR";

/** An RFC 9457 `application/problem+json` response surfaced as an Error. */
export class ApiError extends Error {
  readonly status: number;
  readonly code?: BusinessErrorCode | string;
  /** Field-level errors, when the backend returned a ValidationProblemDetails. */
  readonly errors?: Record<string, string[]>;
  readonly requestId?: string;

