import { expect, test, type Locator, type Page } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, field } from "./support/ui";

/** Scope 3 — Quartiers et types de biens (référentiels gérés par l'admin projet). */

interface QuartierDto {
  id: string;
  name: string;
  description: string;
  images: string | null;
}

interface FeatureDto {
  id: string;
  title: string;
  description: string | null;
  image: string | null;
}

interface TypeBienDto {
  id: number;
  name: string;
  description?: string | null;
  image?: string | null;
  module3DLink?: string | null;
  nbrChambre?: number | null;
  nbrSalleDeBain?: number | null;
  nbrDouche?: number | null;
  nbrParking?: number | null;
  minSurface?: number | null;
  maxSurface?: number | null;
}

const png = (name: string) => ({ name, mimeType: "image/png", buffer: st.PNG_1PX });

async function findQuartier(name: string) {
  const admin = await Api.as("globalAdmin");
  return (await admin.all<QuartierDto>("/api/Projects/quartiers")).find((q) => q.name === name) ?? null;
}

async function findTypeBien(name: string) {
  const admin = await Api.as("globalAdmin");
  return (await admin.get<TypeBienDto[]>("/api/Projects/type-biens")).find((t) => t.name === name) ?? null;
}

async function features(quartierId: string) {
  const admin = await Api.as("globalAdmin");
  return admin.get<FeatureDto[]>(`/api/Projects/quartiers/${quartierId}/features`);
}

/** Uploads through an ImageUploadField (real storage) and waits for its thumbnail. */
async function uploadImage(scope: Locator, label: string, fileName: string) {
  await scope.getByLabel(label, { exact: true }).setInputFiles(png(fileName));
  await expect(scope.locator(".upload-thumb img").first()).toBeVisible({ timeout: 40_000 });
}

function rowOf(scope: Page | Locator, text: string) {
  return scope.getByRole("row").filter({ hasText: text });
}

test.describe("Quartiers", { tag: "@projectAdmin" }, () => {
  test("district_crud_with_name_description_optional_image", async ({ page }) => {
    acceptDialogs(page);
    const name = `Quartier E2E ${st.uid()}`;

    // Create with name, description and an image.
    await page.goto("/admin/quartiers");
    await page.getByRole("button", { name: "+ Nouveau quartier" }).click();
    const create = page.getByRole("dialog", { name: "Nouveau quartier" });
    await field(create, "Nom").fill(name);
    await field(create, "Description").fill("Quartier résidentiel calme (E2E)");
    await uploadImage(create, "Images (facultatif)", "quartier.png");
    await create.getByRole("button", { name: "Créer" }).click();
    await expect(create).toBeHidden();

    await expect.poll(orNull(() => findQuartier(name))).not.toBeNull();
    const created = (await findQuartier(name))!;
    expect(created.description).toBe("Quartier résidentiel calme (E2E)");
    expect(created.images ?? "").toMatch(/^https:\/\/\S+quartier/);
    await expect(rowOf(page, name)).toHaveCount(1);

    // Edit: rename, change the description and remove the image.
    const renamed = `${name} modifié`;
    await rowOf(page, name).getByRole("button", { name: "Modifier" }).click();
    const edit = page.getByRole("dialog", { name: `Modifier — ${name}` });
    await field(edit, "Nom").fill(renamed);
    await field(edit, "Description").fill("Description corrigée (E2E)");
    await edit.getByRole("button", { name: "Retirer l'image" }).click();
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    const admin = await Api.as("globalAdmin");
    await expect.poll(async () => (await admin.get<QuartierDto>(`/api/Projects/quartiers/${created.id}`)).name).toBe(renamed);
    const edited = await admin.get<QuartierDto>(`/api/Projects/quartiers/${created.id}`);
    expect(edited.description).toBe("Description corrigée (E2E)");
    expect(edited.images ?? "").toBe("");

    // Delete.
    await rowOf(page, renamed).getByRole("button", { name: "Supprimer" }).click();
    await expect(rowOf(page, renamed)).toHaveCount(0);
    expect((await admin.raw("GET", `/api/Projects/quartiers/${created.id}`)).status()).toBe(404);
  });

  test("district_supports_feature_list", async ({ page }) => {
    acceptDialogs(page);
    const admin = await Api.as("globalAdmin");
    const name = `Quartier features ${st.uid()}`;
    await admin.post("/api/Projects/quartiers", { name, description: "E2E", images: "" });
    const q = (await findQuartier(name))!;

    await page.goto("/admin/quartiers");
    await rowOf(page, name).getByRole("button", { name: "Fonctionnalités" }).click();
    const dialog = page.getByRole("dialog", { name: `Fonctionnalités — ${name}` });

    // Add: title, description, image.
    await field(dialog, "Titre").fill("Parc urbain");
    await field(dialog, "Description de la fonctionnalité").fill("Grand parc à 5 minutes à pied");
    await uploadImage(dialog, "Image de la fonctionnalité (facultatif)", "parc.png");
    await dialog.getByRole("button", { name: "Ajouter la fonctionnalité" }).click();
    await expect(rowOf(dialog, "Parc urbain")).toHaveCount(1);
    // A second one, without image.
    await field(dialog, "Titre").fill("Tramway");
    await field(dialog, "Description de la fonctionnalité").fill("Station T1");
    await dialog.getByRole("button", { name: "Ajouter la fonctionnalité" }).click();
    await expect(rowOf(dialog, "Tramway")).toHaveCount(1);

    let list = await features(q.id);
    expect(list.map((f) => f.title)).toEqual(["Parc urbain", "Tramway"]);
    expect(list[0].description).toBe("Grand parc à 5 minutes à pied");
    expect(list[0].image ?? "").toMatch(/^https:\/\/\S+parc/);
    expect(list[1].image).toBeNull();

    // Edit the first one: its image is kept.
    await rowOf(dialog, "Parc urbain").getByRole("button", { name: "Modifier" }).click();
    await field(dialog, "Titre").fill("Parc urbain Zenata");
    await dialog.getByRole("button", { name: "Enregistrer la fonctionnalité" }).click();
    await expect(rowOf(dialog, "Parc urbain Zenata")).toHaveCount(1);
    list = await features(q.id);
    expect(list.map((f) => f.title)).toEqual(["Parc urbain Zenata", "Tramway"]);
    expect(list[0].image ?? "").toMatch(/^https:\/\//);

    // Delete the second one.
    await rowOf(dialog, "Tramway").getByRole("button", { name: "Supprimer" }).click();
    await expect(rowOf(dialog, "Tramway")).toHaveCount(0);
    expect((await features(q.id)).map((f) => f.title)).toEqual(["Parc urbain Zenata"]);

    // The API requires a title and only lets admins write.
    await expectRefused(await admin.raw("POST", `/api/Projects/quartiers/${q.id}/features`, { title: " " }), [422], "feature without title");
    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("POST", `/api/Projects/quartiers/${q.id}/features`, { title: "Intrus" }), [403], "agent adds feature");
  });

  test("district_image_and_feature_image_are_optional", async ({ page }) => {
    const name = `Quartier sans image ${st.uid()}`;
    await page.goto("/admin/quartiers");
    await page.getByRole("button", { name: "+ Nouveau quartier" }).click();
    const create = page.getByRole("dialog", { name: "Nouveau quartier" });
    await field(create, "Nom").fill(name);
    await create.getByRole("button", { name: "Créer" }).click();
    await expect(create).toBeHidden();
    await expect.poll(orNull(() => findQuartier(name))).not.toBeNull();
    const q = (await findQuartier(name))!;
    expect(q.images ?? "").toBe("");

    await rowOf(page, name).getByRole("button", { name: "Fonctionnalités" }).click();
    const dialog = page.getByRole("dialog", { name: `Fonctionnalités — ${name}` });
    await field(dialog, "Titre").fill("Écoles");
    await dialog.getByRole("button", { name: "Ajouter la fonctionnalité" }).click();
    await expect(rowOf(dialog, "Écoles")).toHaveCount(1);
    const list = await features(q.id);
    expect(list).toHaveLength(1);
    expect(list[0].image).toBeNull();
    expect(list[0].description).toBeNull();
  });
});

test.describe("Types de biens", { tag: "@projectAdmin" }, () => {
  test("property_type_persists_all_fields", async ({ page }) => {
    const name = `T3 E2E ${st.uid()}`;
    // The 3D link must be an accepted media host: the API's own storage is.
    const tour = await st.uploadToStorage(`visite-${st.uid()}.png`);

    await page.goto("/admin/type-biens");
    await page.getByRole("button", { name: "+ Nouveau type" }).click();
    const dialog = page.getByRole("dialog", { name: "Nouveau type de bien" });
    await field(dialog, "Nom").fill(name);
    await field(dialog, "Description").fill("Trois pièces traversant");
    await field(dialog, "Chambres").fill("2");
    await field(dialog, "Salles de bain").fill("1");
    await field(dialog, "Salles de douche").fill("1");
    await field(dialog, "Parking (places)").fill("1");
    await field(dialog, "Surface min (m²)").fill("78");
    await field(dialog, "Surface max (m²)").fill("96");
    await field(dialog, "Lien visite 3D").fill(tour);
    await uploadImage(dialog, "Photo", "t3.png");
    await dialog.getByRole("button", { name: "Créer" }).click();
    await expect(dialog).toBeHidden();

    await expect.poll(orNull(() => findTypeBien(name))).not.toBeNull();
    const t = (await findTypeBien(name))!;
    expect(t).toMatchObject({
      description: "Trois pièces traversant",
      nbrChambre: 2,
      nbrSalleDeBain: 1,
      nbrDouche: 1,
      nbrParking: 1,
      minSurface: 78,
      maxSurface: 96,
      module3DLink: tour,
    });
    expect(t.image ?? "").toMatch(/^https:\/\/\S+t3/);

    // Re-read in the UI after a reload.
    await page.reload();
    const row = rowOf(page, name);
    await expect(row).toContainText("78 – 96");
    await expect(row.getByRole("img", { name })).toBeVisible();
  });

  test("property_type_rejects_min_area_greater_than_max", async ({ page }) => {
    const name = `Incohérent ${st.uid()}`;
    await page.goto("/admin/type-biens");
    await page.getByRole("button", { name: "+ Nouveau type" }).click();
    const dialog = page.getByRole("dialog", { name: "Nouveau type de bien" });
    await field(dialog, "Nom").fill(name);
    await field(dialog, "Surface min (m²)").fill("120");
    await field(dialog, "Surface max (m²)").fill("80");
    await dialog.getByRole("button", { name: "Créer" }).click();
    await expect(dialog.getByRole("alert")).toContainText(/surface minimale/i);
    await expect(dialog).toBeVisible();
    expect(await findTypeBien(name)).toBeNull();

    // The API refuses it on its own, on create and on update.
    const admin = await Api.as("globalAdmin");
    await expectRefused(await admin.raw("POST", "/api/TypeBiens", { name, minSurface: 120, maxSurface: 80 }), [400, 422], "create min > max");
    expect(await findTypeBien(name)).toBeNull();
    const ok = await admin.post<{ id: number }>("/api/TypeBiens", { name: `${name} valide`, minSurface: 60, maxSurface: 80 });
    await expectRefused(
      await admin.raw("PUT", `/api/TypeBiens/${ok.id}`, { id: ok.id, name: `${name} valide`, minSurface: 120, maxSurface: 80 }),
      [400, 422],
      "update min > max",
    );
    expect((await findTypeBien(`${name} valide`))?.minSurface).toBe(60);
  });

  test("project_can_link_one_or_many_property_types", async ({ page }) => {
    const admin = await Api.as("globalAdmin");
    const suffix = st.uid();
    const t1 = await admin.post<{ id: number }>("/api/TypeBiens", { name: `Studio ${suffix}`, minSurface: 30, maxSurface: 40 });
    const t2 = await admin.post<{ id: number }>("/api/TypeBiens", { name: `T4 ${suffix}`, minSurface: 110, maxSurface: 130 });
    const p = await st.createProject({ units: 1 });
    const linked = async () => (await admin.get<{ id: number }[]>(`/api/Projects/${p.id}/type-biens`)).map((t) => t.id).sort((a, b) => a - b);
    const openEdit = async () => {
      await page.getByRole("button", { name: "Modifier", exact: true }).click();
      return page.getByRole("dialog", { name: "Modifier le projet" });
    };

    // One type.
    await page.goto(`/admin/projects/${p.id}`);
    let edit = await openEdit();
    await edit.getByRole("checkbox", { name: `Studio ${suffix}` }).check();
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    await expect.poll(linked).toEqual([t1.id]);

    // Many types.
    edit = await openEdit();
    await expect(edit.getByRole("checkbox", { name: `Studio ${suffix}` })).toBeChecked();
    await edit.getByRole("checkbox", { name: `T4 ${suffix}` }).check();
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    await expect.poll(linked).toEqual([t1.id, t2.id].sort((a, b) => a - b));
    await expect(page.locator(".feature-chip", { hasText: `T4 ${suffix}` })).toBeVisible();

    // Unlink one.
    edit = await openEdit();
    await edit.getByRole("checkbox", { name: `Studio ${suffix}` }).uncheck();
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expect(edit).toBeHidden();
    await expect.poll(linked).toEqual([t2.id]);
  });
});

