import { expect, test, type Locator, type Page } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, field } from "./support/ui";

/** Scope 3 — Quartiers et types de biens (référentiels gérés par l'admin projet). */

interface QuartierDto {
  id: string;
  name: string;
  description: string;
  images: string | null;
}

interface FeatureDto {
  id: string;
  title: string;
  description: string | null;
  image: string | null;
}

interface TypeBienDto {
  id: number;
  name: string;
  description?: string | null;
  image?: string | null;
  module3DLink?: string | null;
  nbrChambre?: number | null;
  nbrSalleDeBain?: number | null;
  nbrDouche?: number | null;
  nbrParking?: number | null;
  minSurface?: number | null;
  maxSurface?: number | null;
}

const png = (name: string) => ({ name, mimeType: "image/png", buffer: st.PNG_1PX });

async function findQuartier(name: string) {
  const admin = await Api.as("globalAdmin");
  return (await admin.all<QuartierDto>("/api/Projects/quartiers")).find((q) => q.name === name) ?? null;
}

async function findTypeBien(name: string) {
  const admin = await Api.as("globalAdmin");
  return (await admin.get<TypeBienDto[]>("/api/Projects/type-biens")).find((t) => t.name === name) ?? null;
}

async function features(quartierId: string) {
  const admin = await Api.as("globalAdmin");
  return admin.get<FeatureDto[]>(`/api/Projects/quartiers/${quartierId}/features`);
}

/** Uploads through an ImageUploadField (real storage) and waits for its thumbnail. */
async function uploadImage(scope: Locator, label: string, fileName: string) {
  await scope.getByLabel(label, { exact: true }).setInputFiles(png(fileName));
  await expect(scope.locator(".upload-thumb img").first()).toBeVisible({ timeout: 40_000 });
}

function rowOf(scope: Page | Locator, text: string) {
  return scope.getByRole("row").filter({ hasText: text });
}

test.describe("Quartiers", { tag: "@projectAdmin" }, () => {
  test("district_crud_with_name_description_optional_image", async ({ page }) => {
    acceptDialogs(page);
    const name = `Quartier E2E ${st.uid()}`;

    // Create with name, description and an image.
