    expect(list[0].description).toBe("Grand parc à 5 minutes à pied");
    expect(list[0].image ?? "").toMatch(/^https:\/\/\S+parc/);
    expect(list[1].image).toBeNull();

    // Edit the first one: its image is kept.
    await rowOf(dialog, "Parc urbain").getByRole("button", { name: "Modifier" }).click();
