    expect(list[0].image ?? "").toMatch(/^https:\/\//);

    // Delete the second one.
    await rowOf(dialog, "Tramway").getByRole("button", { name: "Supprimer" }).click();
    await expect(rowOf(dialog, "Tramway")).toHaveCount(0);
    expect((await features(q.id)).map((f) => f.title)).toEqual(["Parc urbain Zenata"]);

    // The API requires a title and only lets admins write.
    await expectRefused(await admin.raw("POST", `/api/Projects/quartiers/${q.id}/features`, { title: " " }), [422], "feature without title");
    const agent = await Api.as("agent");
