    const q = (await findQuartier(name))!;
    expect(q.images ?? "").toBe("");

    await rowOf(page, name).getByRole("button", { name: "Fonctionnalités" }).click();
    const dialog = page.getByRole("dialog", { name: `Fonctionnalités — ${name}` });
    await field(dialog, "Titre").fill("Écoles");
    await dialog.getByRole("button", { name: "Ajouter la fonctionnalité" }).click();
    await expect(rowOf(dialog, "Écoles")).toHaveCount(1);
    const list = await features(q.id);
    expect(list).toHaveLength(1);
    expect(list[0].image).toBeNull();
    expect(list[0].description).toBeNull();
  });
});

