2	import { Link, useNavigate, useParams } from "react-router-dom";
3	import { immeublesApi, projectsApi } from "../../api";
4	import { ApiError } from "../../api/http/client";
5	import type { Immeuble, Project, ProjectFeature, ProjectStatus } from "../../types";
