16	// Zenata Ecocité) — only the latter should render as a clickable link.
17	function isUrl(value?: string | null): value is string {
18	  if (!value) return false;
19	  try {
20	    const url = new URL(value);
21	    return url.protocol === "http:" || url.protocol === "https:";
22	  } catch {
23	    return false;
