30	  // §6.3 — editing a project and adding a building are both "A périmètre"
31	  // (admins): PUT /api/Projects/{id} and POST /api/Immeuble are RoleGroups.Admins.
32	  // A SALES_AGENT may read this page but must not be offered either action.
33	  const canManageProjects = !!user?.roles.some((role) => ADMINS.includes(role));
34	
35	  const [project, setProject] = useState<Project | null | undefined>(undefined);
36	  const [immeubles, setImmeubles] = useState<Immeuble[]>([]);
