import { useEffect, useState, type FormEvent } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { immeublesApi, projectsApi } from "../../api";
import { ApiError } from "../../api/http/client";
import type { Immeuble, Project, ProjectFeature, ProjectStatus } from "../../types";
import { Button, Card, Field, Loading, Modal, PageHeader, StatusBadge, Table } from "../../components/ui";
import { formatMAD } from "../../lib/format";
import { ConstructionPanel } from "../construction/ConstructionPanel";
import { ProjectMediaPanel } from "./ProjectMediaPanel";
import { ProjectDocumentRequirementsPanel } from "./ProjectDocumentRequirementsPanel";
import { useAuth } from "../../context/AuthContext";
import { ADMINS } from "../../lib/roles";

// Project.address sometimes holds a plain street address and sometimes a
// full Google Maps link pasted in from the source spreadsheet (e.g. Beaulieu
// Zenata Ecocité) — only the latter should render as a clickable link.
function isUrl(value?: string | null): value is string {
  if (!value) return false;
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

export default function ProjectDetailPage() {
  const { id = "" } = useParams();
  const { user } = useAuth();
  // §6.3 — editing a project and adding a building are both "A périmètre"
  // (admins): PUT /api/Projects/{id} and POST /api/Immeuble are RoleGroups.Admins.
  // A SALES_AGENT may read this page but must not be offered either action.
  const canManageProjects = !!user?.roles.some((role) => ADMINS.includes(role));

  const [project, setProject] = useState<Project | null | undefined>(undefined);
  const [immeubles, setImmeubles] = useState<Immeuble[]>([]);
  const [features, setFeatures] = useState<ProjectFeature[]>([]);
  const [showEdit, setShowEdit] = useState(false);
  const [showCreateImmeuble, setShowCreateImmeuble] = useState(false);
  const [createImmeubleError, setCreateImmeubleError] = useState<string | null>(null);
  const [creatingImmeuble, setCreatingImmeuble] = useState(false);
  const [editError, setEditError] = useState<string | null>(null);
  const [removing, setRemoving] = useState(false);
  const [removeError, setRemoveError] = useState<string | null>(null);
  const navigate = useNavigate();
  const [savingEdit, setSavingEdit] = useState(false);

  function loadProject() {
    projectsApi.getById(id).then((p) => setProject(p ?? null));
  }

  function loadImmeubles() {
    immeublesApi.list({ projectId: id, pageSize: 20 }).then((r) => setImmeubles(r.data));
  }

  useEffect(() => {
    loadProject();
    loadImmeubles();
    projectsApi.listFeatures(id).then(setFeatures);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  async function onCreateImmeuble(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    setCreateImmeubleError(null);
    setCreatingImmeuble(true);
    try {
      await immeublesApi.create({
        projectId: id,
        name: String(form.get("name")),
        location: String(form.get("location")),
        type: String(form.get("type")),
        minPrice: Number(form.get("minPrice")),
        maxPrice: Number(form.get("maxPrice")),
        description: String(form.get("description")),
        latitude: Number(form.get("latitude")) || 0,
        longitude: Number(form.get("longitude")) || 0,
        numberOfUnits: 0,
        numberOfSoldUnites: 0,
        numberOfAvailableUnites: 0,
        images: [],
      });
      setShowCreateImmeuble(false);
      loadImmeubles();
    } catch (err) {
      setCreateImmeubleError(err instanceof ApiError ? err.message : "Échec de la création du bâtiment.");
    } finally {
      setCreatingImmeuble(false);
    }
  }

