import { useEffect, useState } from "react";
import { projectsApi, typeBiensApi } from "../../api";
import { ApiError } from "../../api/http/client";
import type { Quartier, TypeBien } from "../../types";
import { Field } from "../../components/ui";

/**
 * The project's catalogue links, shared by the create and edit forms: the
 * quartier it belongs to and the property types it offers (one or many).
 * Both lists are read from their referentials; the API validates the ids.
 */
export function ProjectCatalogueFields({
  quartierId,
  onQuartierChange,
  typeBienIds,
  onTypeBiensChange,
  disabled,
}: {
  quartierId: string;
  onQuartierChange: (id: string) => void;
  typeBienIds: number[];
  onTypeBiensChange: (ids: number[]) => void;
  disabled?: boolean;
}) {
  const [quartiers, setQuartiers] = useState<Quartier[] | null>(null);
  const [types, setTypes] = useState<TypeBien[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fail = (err: unknown) => setError(err instanceof ApiError ? err.message : "Échec du chargement des référentiels.");
    projectsApi.listQuartiers().then(setQuartiers, (err) => { setQuartiers([]); fail(err); });
    typeBiensApi.list().then(setTypes, (err) => { setTypes([]); fail(err); });
  }, []);

  function toggle(id: number, checked: boolean) {
    onTypeBiensChange(checked ? [...typeBienIds.filter((t) => t !== id), id] : typeBienIds.filter((t) => t !== id));
  }

  return (
    <>
      {error && <p className="form-error" role="alert">{error}</p>}
      <Field label="Quartier">
        <select value={quartierId} onChange={(e) => onQuartierChange(e.target.value)} disabled={disabled || !quartiers}>
          <option value="">Aucun quartier</option>
          {(quartiers ?? []).map((q) => (
            <option key={q.id} value={q.id}>{q.name}</option>
          ))}
        </select>
      </Field>
      <fieldset className="field" style={{ border: 0, padding: 0, margin: "0 0 12px" }} disabled={disabled}>
        <legend style={{ fontWeight: 600, marginBottom: 6 }}>Types de biens</legend>
        {!types ? (
          <span className="muted small">Chargement…</span>
        ) : types.length === 0 ? (
          <span className="muted small">Aucun type de bien dans le référentiel.</span>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "6px 16px", maxHeight: 160, overflowY: "auto" }}>
            {types.map((t) => (
              <label key={t.id} style={{ display: "inline-flex", gap: 6, alignItems: "center", fontWeight: 400 }}>
                <input type="checkbox" checked={typeBienIds.includes(t.id)} onChange={(e) => toggle(t.id, e.target.checked)} />
                {t.name}
              </label>
            ))}
          </div>
        )}
      </fieldset>
    </>
  );
}

