1	import { expect, test, type Locator, type Page } from "@playwright/test";
2	import { Api, expectRefused, orNull } from "./support/api";
3	import * as st from "./support/state";
4	import { acceptDialogs, field } from "./support/ui";
5	
6	/** Scope 3 — Quartiers et types de biens (référentiels gérés par l'admin projet). */
7	
8	interface QuartierDto {
9	  id: string;
10	  name: string;
11	  description: string;
12	  images: string | null;
13	}
14	
15	interface FeatureDto {
16	  id: string;
17	  title: string;
18	  description: string | null;
19	  image: string | null;
20	}
21	
22	interface TypeBienDto {
23	  id: number;
24	  name: string;
25	  description?: string | null;
26	  image?: string | null;
27	  module3DLink?: string | null;
28	  nbrChambre?: number | null;
29	  nbrSalleDeBain?: number | null;
30	  nbrDouche?: number | null;
31	  nbrParking?: number | null;
32	  minSurface?: number | null;
33	  maxSurface?: number | null;
34	}
35	
36	const png = (name: string) => ({ name, mimeType: "image/png", buffer: st.PNG_1PX });
37	
38	/** Finds a quartier by name in the list, then re-reads it by id (the full record). */
39	async function findQuartier(name: string) {
40	  const admin = await Api.as("globalAdmin");
41	  const row = (await admin.all<{ id: string; name: string }>("/api/Projects/quartiers")).find((q) => q.name === name);
42	  return row ? admin.get<QuartierDto>(`/api/Projects/quartiers/${row.id}`) : null;
43	}
44	
45	async function findTypeBien(name: string) {
46	  const admin = await Api.as("globalAdmin");
47	  return (await admin.get<TypeBienDto[]>("/api/Projects/type-biens")).find((t) => t.name === name) ?? null;
48	}
49	
50	async function features(quartierId: string) {
51	  const admin = await Api.as("globalAdmin");
52	  return admin.get<FeatureDto[]>(`/api/Projects/quartiers/${quartierId}/features`);
53	}
54	
55	/** Uploads through an ImageUploadField (real storage) and waits for its thumbnail. */
56	async function uploadImage(scope: Locator, label: string, fileName: string) {
57	  await scope.getByLabel(label, { exact: true }).setInputFiles(png(fileName));
58	  await expect(scope.locator(".upload-thumb img").first()).toBeVisible({ timeout: 40_000 });
59	}
60	
61	function rowOf(scope: Page | Locator, text: string) {
62	  return scope.getByRole("row").filter({ hasText: text });
63	}
64	
65	test.describe("Quartiers", { tag: "@projectAdmin" }, () => {
66	  test("district_crud_with_name_description_optional_image", async ({ page }) => {
67	    acceptDialogs(page);
68	    const name = `Quartier E2E ${st.uid()}`;
69	
70	    // Create with name, description and an image.
71	    await page.goto("/admin/quartiers");
72	    await page.getByRole("button", { name: "+ Nouveau quartier" }).click();
73	    const create = page.getByRole("dialog", { name: "Nouveau quartier" });
74	    await field(create, "Nom").fill(name);
75	    await field(create, "Description").fill("Quartier résidentiel calme (E2E)");
76	    await uploadImage(create, "Images (facultatif)", "quartier.png");
77	    await create.getByRole("button", { name: "Créer" }).click();
78	    await expect(create).toBeHidden();
79	
80	    await expect.poll(orNull(() => findQuartier(name))).not.toBeNull();
81	    const created = (await findQuartier(name))!;
82	    expect(created.description).toBe("Quartier résidentiel calme (E2E)");
83	    expect(created.images ?? "").toMatch(/^https:\/\/\S+quartier/);
84	    await expect(rowOf(page, name)).toHaveCount(1);
85	
86	    // Edit: rename, change the description and remove the image.
87	    const renamed = `${name} modifié`;
88	    await rowOf(page, name).getByRole("button", { name: "Modifier" }).click();
89	    const edit = page.getByRole("dialog", { name: `Modifier — ${name}` });
90	    await field(edit, "Nom").fill(renamed);
91	    await field(edit, "Description").fill("Description corrigée (E2E)");
92	    await edit.getByRole("button", { name: "Retirer l'image" }).click();
93	    await edit.getByRole("button", { name: "Enregistrer" }).click();
94	    await expect(edit).toBeHidden();
95	    const admin = await Api.as("globalAdmin");
96	    await expect.poll(async () => (await admin.get<QuartierDto>(`/api/Projects/quartiers/${created.id}`)).name).toBe(renamed);
97	    const edited = await admin.get<QuartierDto>(`/api/Projects/quartiers/${created.id}`);
98	    expect(edited.description).toBe("Description corrigée (E2E)");
99	    expect(edited.images ?? "").toBe("");
100	
101	    // Delete.
102	    await rowOf(page, renamed).getByRole("button", { name: "Supprimer" }).click();
103	    await expect(rowOf(page, renamed)).toHaveCount(0);
104	    expect((await admin.raw("GET", `/api/Projects/quartiers/${created.id}`)).status()).toBe(404);
105	  });
106	
107	  test("district_supports_feature_list", async ({ page }) => {
108	    acceptDialogs(page);
109	    const admin = await Api.as("globalAdmin");
110	    const name = `Quartier features ${st.uid()}`;
111	    await admin.post("/api/Projects/quartiers", { name, description: "E2E", images: "" });
112	    const q = (await findQuartier(name))!;
113	
