import { useMemo, useState } from "react";
import { dashboardApi } from "../../api";
import type { AdminDashboardOverview, DashboardPeriodPreset } from "../../types";
import { Async, Card, DateRangeFilter, PageHeader, Plaque, StatCard, Table } from "../../components/ui";
import { useAsync } from "../../lib/useAsync";
import { formatMAD } from "../../lib/format";
import { resolvePreset, toDateInputValue, formatRangeLabel } from "../../lib/dateRange";
import { AgentPerformance } from "./AgentPerformance";
import { CompareChip } from "./CompareChip";
import { SalesVelocity } from "./SalesVelocity";
import { InventorySnapshot } from "./InventorySnapshot";
import { ProjectRankings } from "./ProjectRankings";
import { NearSelloutList } from "./NearSelloutList";

export default function DashboardPage() {
  const [preset, setPreset] = useState<DashboardPeriodPreset>("thisMonth");
  const [custom, setCustom] = useState<{ start: string; end: string }>(() => {
    const now = new Date();
    const start = new Date(now.getFullYear(), now.getMonth(), 1);
    return { start: toDateInputValue(start), end: toDateInputValue(now) };
  });

  const range = useMemo(() => resolvePreset(preset, custom), [preset, custom]);

  const state = useAsync(() => dashboardApi.overview({ start: range.start, end: range.end }), [range.start.getTime(), range.end.getTime()]);

  function onFilterChange(next: DashboardPeriodPreset, nextCustom?: { start: string; end: string }) {
    setPreset(next);
    if (nextCustom) setCustom(nextCustom);
  }

  return (
    <div>
      <PageHeader title="Tableau de bord" subtitle="Vue d'ensemble de l'activité commerciale" />

      <DateRangeFilter preset={preset} customStart={custom.start} customEnd={custom.end} onChange={onFilterChange} />

      <Async state={state}>
        {(overview) => <DashboardBody overview={overview} />}
      </Async>
    </div>
  );
}

function DashboardBody({ overview }: { overview: AdminDashboardOverview }) {
  const agents = overview.agentsPerformance;
  // Average sale size is the one derived figure the lede can carry honestly:
  // it comes from two numbers the API already returns, not from invented
  // history.
  const avgSale =
    overview.salesThisMonth > 0
      ? Math.round(overview.salesVolumeThisMonth / overview.salesThisMonth)
      : null;
  const totalAppointments = agents.reduce((s, a) => s + a.appointmentsCount, 0);

  const periodStart = new Date(overview.periodStart);
  const periodEnd = new Date(overview.periodEnd);

  return (
    <>
      {/* Active-period indicator — always visible so a filtered view never
          reads as ambiguous about which window it's showing. */}
      <div className="period-indicator">
        <span className="period-indicator-dot" aria-hidden="true" />
        Période affichée : {formatRangeLabel(periodStart, periodEnd)}
      </div>

      {/* Focal point: the period's sales volume leads at plaque scale; the
          three supporting counts are demoted into a single bordered strip
          beside it, and the comparison chip sits right under the lede where
          the eye already is. */}
      <div className="metric-lede">
        <Plaque
          label="Volume de ventes · période sélectionnée"
          value={formatMAD(overview.salesVolumeThisMonth)}
          meta={
            <>
              <strong>{overview.salesThisMonth}</strong> ventes conclues
              {avgSale !== null && <> · panier moyen {formatMAD(avgSale)}</>}
              {overview.previousPeriod && (
                <>
                  {" "}
                  <CompareChip pct={overview.previousPeriod.salesVolumeChangePct} />
                </>
              )}
            </>
          }
        />
        <div className="metric-support">
          <StatCard label="Ventes" value={overview.salesThisMonth} />
          <StatCard label="Réservations" value={overview.reservationsInPeriod} />
          <StatCard label="Taux de réservation" value={`${overview.reservationRatePct}%`} />
          <StatCard label="Agents actifs" value={overview.totalAgents} />
          <StatCard label="Projets" value={overview.totalProjects} />
          <StatCard label="Rendez-vous" value={totalAppointments} />
        </div>
      </div>

      <div className="detail-grid dashboard-reservation-kpis">
        <StatCard label="Montant des réservations · période" value={formatMAD(overview.reservationAmountInPeriod)} />
        <StatCard label="Montant moyen · période" value={formatMAD(overview.averageReservationAmountInPeriod)} />
      </div>

      <Card>
    agentId: dto.agentId,
    agentName: dto.agentFullName,
    salesCount: dto.salesCount,
    salesVolume: dto.salesVolume,
    appointmentsCount: dto.appointmentsScheduled,
    conversionRate: dto.conversionRate,
  };
}

function toPeriodComparison(dto: PeriodComparisonDto): PeriodComparison {
  return { ...dto };
}

function toVelocity(dto: ProjectVelocityDto): ProjectVelocity {
  return { ...dto, points: dto.points as MonthlyVelocityPoint[] };
}

function toSellThrough(dto: ProjectSellThroughDto): ProjectSellThrough {
  return { ...dto };
}

function toNearSellout(dto: ImmeubleNearSelloutDto): ImmeubleNearSellout {
  return { ...dto };
}

function toInventory(dto: ProjectInventoryDto): ProjectInventory {
  return { ...dto };
}

export const dashboardApi: DashboardApi = {
  /**
   * `range` selects the date window every figure is computed against; when
   * omitted this defaults to the current calendar month (matches the
   * server's own default for an unfiltered call). Passing a range always
   * sends explicit StartDate/EndDate — the legacy Year/Month params are kept
   * server-side for compatibility only, never sent from here.
   */

    const overview: AdminDashboardOverview = {
      totalAgents: dto.totalAgents,
      totalProjects: dto.totalProjects,
      salesThisMonth: dto.salesThisMonth,
      salesVolumeThisMonth: dto.salesVolumeThisMonth,
      reservationsInPeriod: dto.reservationsInPeriod,
      reservationAmountInPeriod: dto.reservationAmountInPeriod,
      reservationRatePct: dto.reservationRatePct,
      averageReservationAmountInPeriod: dto.averageReservationAmountInPeriod,
      agentsPerformance: dto.agentsPerformance.map(toAgentPerformance),
      topPerformers: dto.topPerformers.map(toAgentPerformance),
      periodStart: dto.periodStart,
      periodEnd: dto.periodEnd,
      previousPeriod: dto.previousPeriod ? toPeriodComparison(dto.previousPeriod) : null,
      salesVelocityByProject: dto.salesVelocityByProject.map(toVelocity),
      topPerformingProjects: dto.topPerformingProjects.map(toSellThrough),
      bottomPerformingProjects: dto.bottomPerformingProjects.map(toSellThrough),
      nearSelloutBuildings: dto.nearSelloutBuildings.map(toNearSellout),
      inventoryByProject: dto.inventoryByProject.map(toInventory),
    };
    return overview;
  },
};

