test("reservation_creation_allowed_only_for_sur_plan_project", async ({ page }) => {
  const surPlan = await st.createProject();
  const enLivraison = await st.createProject({ phase: "EN_LIVRAISON" });
  const finalise = await st.createProject({ phase: "FINALISE" });

  const dialog = await openCreateForm(page);
  const projectSelect = dialog.getByLabel("Projet");
  await expect(projectSelect.locator("option", { hasText: surPlan.name })).toHaveCount(1);
  await expect(projectSelect.locator("option", { hasText: enLivraison.name })).toHaveCount(0);
  await expect(projectSelect.locator("option", { hasText: finalise.name })).toHaveCount(0);

  const agent = await Api.as("agent");
  const buyer = await Api.as("buyer");
  for (const p of [enLivraison, finalise]) {
    await expectRefused(
      await agent.raw("POST", "/api/Reservations/create", {
        buyerId: buyer.userId, name: "X", lastName: "Refus", email: "x@example.test", phoneNumber: "+212600000000",
        unitId: p.unitIds[0], agentId: agent.userId, totalPropertyPrice: 1000000, reservationAmount: 10000, createAsDraft: true,
      }),
      [409, 422],
      `reservation on ${p.name}`,
    );
  }
  const onClosed = (await agent.all<{ unitId: string }>("/api/Reservations/list")).filter((r) =>
    [...enLivraison.unitIds, ...finalise.unitIds].includes(r.unitId),
  );
  expect(onClosed).toHaveLength(0);
});
test("project_admin_can_finalize_project_at_100_pct", async ({ page }) => {
  acceptDialogs(page);
  const p = await st.createProject({ constructionPct: 100 });
  await page.goto(`/admin/projects/${p.id}`);
  await page.getByRole("button", { name: "Passer en livraison" }).click();
  await expect(page.getByRole("button", { name: "Finaliser le projet" })).toBeVisible();
  expect((await st.getProject(p.id, "projectAdmin")).statusGlobal).toBe("COMPLETED");

  await page.getByRole("button", { name: "Finaliser le projet" }).click();
  await expect(page.getByRole("button", { name: "Projet finalisé" })).toBeVisible();
  expect((await st.getProject(p.id, "projectAdmin")).statusGlobal).toBe("ARCHIVED");
  await page.reload();
  await expect(page.getByText("Finalisé").first()).toBeVisible();
});
test("project_admin_finalize_rejected_below_100_pct", async ({ page }) => {
  acceptDialogs(page);
  const p = await st.createProject({ constructionPct: 50 });
  const before = (await st.getProject(p.id, "projectAdmin")).statusGlobal;
  await page.goto(`/admin/projects/${p.id}`);
  await page.getByRole("button", { name: "Passer en livraison" }).click();
  await expect(page.getByRole("alert")).toContainText("100%");
  await page.reload();
  await expect(page.getByRole("button", { name: "Passer en livraison" })).toBeVisible();
  expect((await st.getProject(p.id, "projectAdmin")).statusGlobal).toBe(before);

  const padmin = await Api.as("projectAdmin");
  await expectRefused(
    await padmin.raw("POST", `/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true }),
    [409, 422],
    "finalize below 100%",
  );
  await expectRefused(
    await padmin.raw("POST", `/api/construction/projects/${p.id}/complete`, {
      projectId: p.id,
      confirm: true,
      overrideIncompleteProgress: true,
      overrideReason: "tentative",
    }),
    [403],
    "project admin derogation",
  );
  expect((await st.getProject(p.id, "projectAdmin")).statusGlobal).toBe(before);
});

