test.describe("Statuts projet — agent", { tag: "@agent" }, () => {
  test("sur_plan_allows_reservation_creation", async ({ page }) => {
    const p = await st.createProject();
    const dialog = await openReservationCreate(page);
    await expect(dialog.getByLabel("Projet").locator("option", { hasText: p.name })).toHaveCount(1);
    // The rule itself, through the API.
    const j = await st.createReservation(p, { state: "SUBMITTED" });
    const agent = await Api.as("agent");
    const mine = await agent.all<{ id: string }>(`/api/Reservations/list?ProjectId=${p.id}`);
    expect(mine.map((r) => r.id)).toContain(j.reservationId);
  });

  test("en_livraison_blocks_new_reservation", async ({ page }) => {
    // A file approved while SUR_PLAN, then the project moves to EN_LIVRAISON.
    const j = await st.approvedInDelivery();
    expect((await st.getProject(j.project.id)).statusGlobal).toBe("COMPLETED");

    // No new reservation: not offered, refused by the API.
    const dialog = await openReservationCreate(page);
    await expect(dialog.getByLabel("Projet").locator("option", { hasText: j.project.name })).toHaveCount(0);
    const agent = await Api.as("agent");
    const buyer = await Api.as("buyer");
    await expectRefused(
      await agent.raw("POST", "/api/Reservations/create", {
        buyerId: buyer.userId, name: "X", lastName: "Refus", email: "x@example.test", phoneNumber: "+212600000000",
        unitId: j.project.unitIds[1], agentId: agent.userId, totalPropertyPrice: 1000000, reservationAmount: 10000, createAsDraft: true,
      }),
      [409, 422],
      "reservation on EN_LIVRAISON",
    );

    // …but the validated file keeps moving: final visit, sale, notary.
    await st.createFinalVisit(j);
    await st.createDraftSale(j);
    expect((await st.getSale(j.reservationId))?.status).toBe("Draft");
    await st.createNotaryAppointment(j, "PURCHASE_COMPLETED");
    await expect.poll(async () => (await st.getSale(j.reservationId))?.status).toBe("Confirmed");
  });

  test("finalise_transition_only_by_project_admin", async ({ page }) => {
    const p = await st.createProject({ constructionPct: 100 });
    await st.completeProject(p);
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("heading", { name: "Avancement de la construction" })).toBeVisible();
    await expect(page.getByRole("button", { name: "Finaliser le projet" })).toHaveCount(0);

    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("POST", `/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true }), [403], "agent finalizes");
    for (const key of ["technician", "notary", "buyer"] as const) {
      const api = await Api.as(key);
      await expectRefused(await api.raw("POST", `/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true }), [403], `${key} finalizes`);
    }
    expect((await st.getProject(p.id)).statusGlobal).toBe("COMPLETED");

    // The project admin can.
    const padmin = await Api.as("projectAdmin");
    await padmin.post(`/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true });
    expect((await st.getProject(p.id)).statusGlobal).toBe("ARCHIVED");
  });
});

test.describe("Statuts projet — admin", { tag: "@projectAdmin" }, () => {
  test("finalise_makes_project_read_only", async ({ page }) => {
    const j = await st.approvedInDelivery();
    await st.finalizeProject(j.project);
    const p = j.project;

    // UI: every business action is withdrawn.
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("status", { name: "Projet en lecture seule" })).toBeVisible();
    for (const name of ["Modifier", "Supprimer", "+ Nouveau bâtiment", "Ajouter le jalon", "Passer en livraison", "Finaliser le projet"]) {
      await expect(page.getByRole("button", { name, exact: true })).toHaveCount(0);
    }
    await expect(page.getByRole("button", { name: "Projet finalisé" })).toBeDisabled();
    await expect(page.getByRole("button", { name: "Démarrer" })).toHaveCount(0);

    // API: refused with PROJECT_READ_ONLY, nothing changed.
    const admin = await Api.as("globalAdmin");
    const padmin = await Api.as("projectAdmin");
    const agent = await Api.as("agent");
    const checks: [Api, string, string, unknown][] = [
      [padmin, "PUT", `/api/Projects/${p.id}`, { id: p.id, name: `${p.name}-x`, location: "Casablanca", address: "12 avenue E2E", images: [], warrantyMonths: 99 }],
      [admin, "POST", `/api/construction/projects/${p.id}/milestones`, { projectId: p.id, code: "X", nameFr: "Après clôture", sequenceNo: 9, weightPercent: 0 }],
      [admin, "POST", `/api/Immeuble/${p.immeubleId}/floors`, { immeubleId: p.immeubleId, name: "R+9", sequenceNo: 9 }],
      [agent, "POST", "/api/sales", { reservationId: j.reservationId, notes: "après clôture" }],
    ];
    for (const [api, method, path, body] of checks) {
      const res = await api.raw(method, path, body);
      await expectRefused(res, [409], `${method} ${path} on finalised project`);
      expect(await res.text()).toMatch(/PROJECT_READ_ONLY/);
    }
    const after = await st.getProject(p.id);
    expect(after.name).toBe(p.name);
    expect(after.warrantyMonths).toBe(p.warrantyMonths);
    expect(after.statusGlobal).toBe("ARCHIVED");
    expect(await st.getSale(j.reservationId)).toBeFalsy();
  });

  test("finalise_transition_rejected_below_100_pct", async ({ page }) => {
    acceptDialogs(page);
    const p = await st.createProject({ constructionPct: 50 });
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("button", { name: "Finaliser le projet" })).toHaveCount(0);
    await page.getByRole("button", { name: "Passer en livraison" }).click();
    await expect(page.getByRole("alert")).toContainText("100%");
    const padmin = await Api.as("projectAdmin");
    await expectRefused(await padmin.raw("POST", `/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true }), [409, 422], "finalize at 50 %");
    await page.reload();
    expect((await st.getProject(p.id)).statusGlobal).not.toMatch(/COMPLETED|ARCHIVED/);
  });
});

