test.describe("Dashboard", { tag: "@projectAdmin" }, () => {
  test("dashboard_shows_all_required_metrics", async ({ page }) => {
    test.setTimeout(180_000);
    // 4 units: 1 reserved (approved), 1 sold, 1 delivered, 1 available; 50 % built.
    const p = await st.createProject({ units: 4, constructionPct: 50 });
    const reserved = await st.createReservation(p, { state: "APPROVED", unitIndex: 0 });
    void reserved;
    const soldP = await st.createProject({ units: 1 });
    void soldP;

    await openDashboardFor(page, p.name);
    await expect(stat(page, "Réservations")).toHaveText("1");
    await expect(stat(page, "Montant des réservations · période")).toContainText("125");
    await expect(stat(page, "Taux de réservation")).toHaveText("25%");
    await expect(stat(page, "Montant moyen · période")).toContainText("125");
    await expect(stat(page, "Avancement construction")).toHaveText("50%");
    await expect(stat(page, "Unités disponibles")).toHaveText("3");
    await expect(stat(page, "Unités réservées")).toHaveText("1");
    await expect(stat(page, "Unités vendues")).toHaveText("0");
    await expect(stat(page, "Unités livrées")).toHaveText("0");

    // Sold and delivered, on a project of their own.
    const sold = await st.journey("SOLD");
    const delivered = await st.journey("DELIVERED");
    await openDashboardFor(page, sold.project.name);
    await expect(stat(page, "Unités vendues")).toHaveText("1");
    await expect(stat(page, "Unités livrées")).toHaveText("0");
    await expect(stat(page, "Avancement construction")).toHaveText("100%");
    await openDashboardFor(page, delivered.project.name);
    await expect(stat(page, "Unités livrées")).toHaveText("1");
    await expect(stat(page, "Unités vendues")).toHaveText("0");

    // Same figures as the API.
    const padmin = await Api.as("projectAdmin");
    const overview = await padmin.get<{ deliveredUnits: number; availableUnits: number }>(
      `/api/AdminDashboard/overview?ProjectId=${delivered.project.id}`,
    );
    expect(overview.deliveredUnits).toBe(1);
  });

  test("dashboard_metrics_update_after_new_reservation", async ({ page }) => {
    const p = await st.createProject({ units: 2 });
    await openDashboardFor(page, p.name);
    await expect(stat(page, "Réservations")).toHaveText("0");
    await expect(stat(page, "Unités disponibles")).toHaveText("2");
    await expect(stat(page, "Taux de réservation")).toHaveText("0%");

    await st.createReservation(p, { state: "APPROVED" });

    // Reloaded from the API, not an optimistic local value.
    await page.reload();
    await listFilter(page, "Projet").selectOption({ label: p.name });
    await expect(stat(page, "Réservations")).toHaveText("1");
    await expect(stat(page, "Unités disponibles")).toHaveText("1");
    await expect(stat(page, "Unités réservées")).toHaveText("1");
    await expect(stat(page, "Taux de réservation")).toHaveText("50%");
    await expect(stat(page, "Montant des réservations · période")).toContainText("125");
  });
});

