        buyerId: buyer.userId, name: "X", lastName: "Refus", email: "x@example.test", phoneNumber: "+212600000000",
        unitId: j.project.unitIds[1], agentId: agent.userId, totalPropertyPrice: 1000000, reservationAmount: 10000, createAsDraft: true,
      }),
      [409, 422],
      "reservation on EN_LIVRAISON",
    );

    // …but the validated file keeps moving: final visit, sale, notary.
    await st.createFinalVisit(j);
    await st.createDraftSale(j);
    expect((await st.getSale(j.reservationId))?.status).toBe("Draft");
    await st.createNotaryAppointment(j, "PURCHASE_COMPLETED");
    await expect.poll(async () => (await st.getSale(j.reservationId))?.status).toBe("Confirmed");
  });

  test("finalise_transition_only_by_project_admin", async ({ page }) => {
    const p = await st.createProject({ constructionPct: 100 });
