test.describe("Statuts projet — admin", { tag: "@projectAdmin" }, () => {
  test("finalise_makes_project_read_only", async ({ page }) => {
    const j = await st.approvedInDelivery();
    await st.finalizeProject(j.project);
    const p = j.project;

    // UI: every business action is withdrawn.
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("status", { name: "Projet en lecture seule" })).toBeVisible();
    for (const name of ["Modifier", "Supprimer", "+ Nouveau bâtiment", "Ajouter le jalon", "Passer en livraison", "Finaliser le projet"]) {
      await expect(page.getByRole("button", { name, exact: true })).toHaveCount(0);
    }
    await expect(page.getByRole("button", { name: "Projet finalisé" })).toBeDisabled();
    await expect(page.getByRole("button", { name: "Démarrer" })).toHaveCount(0);

    // API: refused with PROJECT_READ_ONLY, nothing changed.
    const admin = await Api.as("globalAdmin");
    const padmin = await Api.as("projectAdmin");
    const agent = await Api.as("agent");
    const checks: [Api, string, string, unknown][] = [
      [padmin, "PUT", `/api/Projects/${p.id}`, { id: p.id, name: `${p.name}-x`, location: "Casablanca", address: "12 avenue E2E", images: [], warrantyMonths: 99 }],
      [admin, "POST", `/api/construction/projects/${p.id}/milestones`, { projectId: p.id, code: "X", nameFr: "Après clôture", sequenceNo: 9, weightPercent: 0 }],
      [admin, "POST", `/api/Immeuble/${p.immeubleId}/floors`, { immeubleId: p.immeubleId, name: "R+9", sequenceNo: 9 }],
      [agent, "POST", "/api/sales", { reservationId: j.reservationId, notes: "après clôture" }],
    ];
    for (const [api, method, path, body] of checks) {
      const res = await api.raw(method, path, body);
      await expectRefused(res, [409], `${method} ${path} on finalised project`);
      expect(await res.text()).toMatch(/PROJECT_READ_ONLY/);
    }
    const after = await st.getProject(p.id);
    expect(after.name).toBe(p.name);
    expect(after.warrantyMonths).toBe(p.warrantyMonths);
    expect(after.statusGlobal).toBe("ARCHIVED");
    expect(await st.getSale(j.reservationId)).toBeFalsy();
  });

  test("finalise_transition_rejected_below_100_pct", async ({ page }) => {
    acceptDialogs(page);
    const p = await st.createProject({ constructionPct: 50 });
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("button", { name: "Finaliser le projet" })).toHaveCount(0);
    await page.getByRole("button", { name: "Passer en livraison" }).click();
    await expect(page.getByRole("alert")).toContainText("100%");
    const padmin = await Api.as("projectAdmin");
    await expectRefused(await padmin.raw("POST", `/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true }), [409, 422], "finalize at 50 %");
    await page.reload();
    expect((await st.getProject(p.id)).statusGlobal).not.toMatch(/COMPLETED|ARCHIVED/);
  });
});

