import { expect, test, type Locator, type Page } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, field, listFilter } from "./support/ui";

/** Scope 2 — Projet, construction et dashboard. */

const png = (name: string) => ({ name, mimeType: "image/png", buffer: st.PNG_1PX });

async function findProjectByName(name: string) {
  const admin = await Api.as("globalAdmin");
  const page = await admin.get<{ data: st.ProjectRow[] }>(`/api/Projects?Name=${encodeURIComponent(name)}&PageSize=5`);
  return page.data.find((p) => p.name === name) ?? null;
}

async function uploadImages(scope: Locator, label: string, names: string[]) {
  await scope.getByLabel(label, { exact: true }).setInputFiles(names.map(png));
  await expect(scope.locator(".upload-thumb img")).toHaveCount(names.length, { timeout: 60_000 });
}

async function openCreateProject(page: Page) {
  await page.goto("/admin/projects");
  await page.getByRole("button", { name: "+ Nouveau projet" }).click();
  const dialog = page.getByRole("dialog", { name: "Nouveau projet" });
  await expect(field(dialog, "Nom")).toBeVisible();
  return dialog;
}

async function fillIdentity(dialog: Locator, name: string) {
  await field(dialog, "Nom").fill(name);
  await field(dialog, "Localisation").fill("Casablanca");
  await field(dialog, "Adresse").fill("12 avenue E2E");
}

async function typeBiens(n: number) {
  const admin = await Api.as("globalAdmin");
  const suffix = st.uid();
  const ids: { id: number; name: string }[] = [];
  for (let i = 0; i < n; i++) {
    const name = `Type ${i + 1} ${suffix}`;
    const t = await admin.post<{ id: number }>("/api/TypeBiens", { name, minSurface: 50 + i * 10, maxSurface: 60 + i * 10 });
    ids.push({ id: t.id, name });
  }
  return ids;
}

// ---------------------------------------------------------------------------
// Formulaire projet
// ---------------------------------------------------------------------------
test.describe("Formulaire projet", { tag: "@projectAdmin" }, () => {
  test("project_form_persists_all_fields", async ({ page }) => {
    test.setTimeout(180_000);
    acceptDialogs(page);
    const admin = await Api.as("globalAdmin");
    const name = `e2e-form-${st.uid()}`;
    const quartierName = `Quartier form ${st.uid()}`;
    await admin.post("/api/Projects/quartiers", { name: quartierName, description: "E2E", images: "" });
    const [t1, t2] = await typeBiens(2);
    const tour = await st.uploadToStorage(`tour-${st.uid()}.png`);
    const video = `https://www.youtube.com/watch?v=e2e${st.uid().slice(-6)}`;

    const dialog = await openCreateProject(page);
    await fillIdentity(dialog, name);
    await field(dialog, "Statut").selectOption("IN_PROGRESS");
    await field(dialog, "Garantie (mois)").fill("30");
    await field(dialog, "Description").fill("Résidence E2E complète");
    await uploadImages(dialog, "Photos", ["facade.png", "jardin.png"]);
    await field(dialog, "Lien visite 3D").fill(tour);
    await field(dialog, "Liens vidéo (un par ligne)").fill(video);
    await field(dialog, "Quartier").selectOption({ label: quartierName });
    await dialog.getByRole("checkbox", { name: t1.name }).check();
    await dialog.getByRole("checkbox", { name: t2.name }).check();
    await dialog.getByRole("button", { name: "Créer" }).click();
    await expect(dialog).toBeHidden({ timeout: 30_000 });

    // Persisted server-side.
    await expect.poll(orNull(() => findProjectByName(name))).not.toBeNull();
    const created = (await findProjectByName(name))!;
    const project = await st.getProject(created.id);
    expect(project.statusGlobal).toBe("IN_PROGRESS");
    expect(project.warrantyMonths).toBe(30);
    expect(project.images).toHaveLength(2);
    expect(project.module3DLink).toBe(tour);
    expect(project.typeBiens.map((t) => t.id).sort((a, b) => a - b)).toEqual([t1.id, t2.id].sort((a, b) => a - b));
    const quartier = (await admin.all<{ id: string; name: string }>("/api/Projects/quartiers")).find((q) => q.name === quartierName)!;
    expect(project.quartierId).toBe(quartier.id);
    const videos = await admin.get<{ videoLink: string }[]>(`/api/Projects/${created.id}/videos`);
    expect(videos.map((v) => v.videoLink)).toEqual([video]);

    // Construction percentage: the admin completes one of two 50 % milestones.
    await admin.post(`/api/construction/projects/${created.id}/milestones`, { projectId: created.id, code: "GO", nameFr: "Gros œuvre", sequenceNo: 1, weightPercent: 50 });
    await admin.post(`/api/construction/projects/${created.id}/milestones`, { projectId: created.id, code: "FIN", nameFr: "Finitions", sequenceNo: 2, weightPercent: 50 });
    await page.goto(`/admin/projects/${created.id}`);
    const milestone = page.getByRole("row").filter({ hasText: "Gros œuvre" });
    await milestone.getByRole("button", { name: "Démarrer" }).click();
    await milestone.getByRole("button", { name: "Terminer" }).click();
    await expect(milestone).toContainText("Terminé");
    const construction = await admin.get<{ progressPercent?: number; weightedProgressPercent?: number; overallProgress?: number }>(
      `/api/construction/projects/${created.id}`,
    );
    expect(JSON.stringify(construction)).toMatch(/50/);

    // Re-read in a fresh page load.
    await page.reload();
    const info = page.locator(".card").filter({ has: page.getByRole("heading", { name: "Informations" }) });
    await expect(info).toContainText(quartierName);
    await expect(info).toContainText("30 mois");
    await expect(page.locator(".feature-chip", { hasText: t1.name })).toBeVisible();
    await expect(page.locator(".feature-chip", { hasText: t2.name })).toBeVisible();
    await expect(page.getByText(video)).toBeVisible();
    await expect(page.getByText("50%").first()).toBeVisible();
  });

  test("project_form_accepts_multiple_property_types", async ({ page }) => {
    const types = await typeBiens(3);
    const name = `e2e-types-${st.uid()}`;
    const dialog = await openCreateProject(page);
    await fillIdentity(dialog, name);
    for (const t of types) await dialog.getByRole("checkbox", { name: t.name }).check();
    await dialog.getByRole("button", { name: "Créer" }).click();
    await expect(dialog).toBeHidden();
    await expect.poll(orNull(() => findProjectByName(name))).not.toBeNull();
    const project = await st.getProject((await findProjectByName(name))!.id);
    expect(project.typeBiens.map((t) => t.id).sort((a, b) => a - b)).toEqual(types.map((t) => t.id).sort((a, b) => a - b));
  });

  test("project_form_accepts_multiple_images", async ({ page }) => {
    test.setTimeout(150_000);
    const name = `e2e-images-${st.uid()}`;
    const dialog = await openCreateProject(page);
    await fillIdentity(dialog, name);
    await uploadImages(dialog, "Photos", ["a.png", "b.png", "c.png"]);
    await dialog.getByRole("button", { name: "Créer" }).click();
    await expect(dialog).toBeHidden();
    await expect.poll(orNull(() => findProjectByName(name))).not.toBeNull();
    const project = await st.getProject((await findProjectByName(name))!.id);
    expect(project.images).toHaveLength(3);
    for (const url of project.images) expect(url).toMatch(/^https:\/\//);
  });
});

