  test("auto_sale_creation_is_transactional", async () => {
    // No draft: PURCHASE_COMPLETED must convert the reservation, sell the unit
    // AND insert the sale. The insert is made to fail inside the database.
    const j = await st.journey("FINAL_VISIT");
    await st.createNotaryAppointment(j);
    await st.confirmNotaryAppointment(j);
    const notary = await Api.as("notary");
    const res = await st.withSaleInsertFailure(j.unitId, () =>
      notary.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, {
        id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé (E2E)",
      }),
    );
    expect(res.status(), await res.text()).toBeGreaterThanOrEqual(400);

    // No partial effect.
    expect(await st.getSale(j.reservationId)).toBeNull();
    const admin = await Api.as("globalAdmin");
    expect((await admin.get<{ status: number }>(`/api/Reservations/${j.reservationId}`)).status).toBe(1);
    expect(await st.getUnitStatus(j.project, j.unitId)).toMatch(/RESERVED/i);
    const appt = await admin.get<{ status: string; outcome?: string | null }>(`/api/NotaryAppointments/${j.notaryAppointmentId}`);
    expect(appt.outcome ?? null).toBeNull();
    expect(appt.status).toMatch(/Confirmed/i);

    // And without the fault, the same call succeeds end to end.
    await notary.put(`/api/NotaryAppointments/${j.notaryAppointmentId}`, {
      id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé (E2E)",
    });
    expect((await st.getSale(j.reservationId))?.status).toBe("Confirmed");
  });
