import { expect, request, test } from "@playwright/test";
import { PROJECT_API } from "./support/accounts";
import { Api, expectRefused } from "./support/api";
import * as st from "./support/state";

/**
 * Scope 11 — Sécurité serveur (API seule).
 *
 * The frontend is never the guarantee: every call below goes straight to the
 * API with an unsuitable token (or none) and expects a refusal, then re-reads
 * the state to prove nothing changed.
 */

const pdf = (label: string) => ({ name: `${label}.pdf`, mimeType: "application/pdf", buffer: Buffer.from(`%PDF-1.4 ${label}`) });

test.describe("Sécurité serveur", { tag: "@globalAdmin" }, () => {
  test("api_rejects_role_violation", async () => {
    test.setTimeout(180_000);
    const p = await st.createProject({ constructionPct: 100 });
    const submitted = await st.createReservation(p, { state: "SUBMITTED" });
    const agent = await Api.as("agent");
    const buyer = await Api.as("buyer");
    const technician = await Api.as("technician");
    const notary = await Api.as("notary");

    // Project creation / modification.
    for (const api of [agent, buyer, technician, notary]) {
      await expectRefused(await api.raw("POST", "/api/Projects", { name: `intrus-${st.uid()}`, location: "X", address: "X", images: [] }), [403], `${api.s.key} creates project`);
      await expectRefused(
        await api.raw("PUT", `/api/Projects/${p.id}`, { id: p.id, name: "Piraté", location: "X", address: "X", images: [] }),
        [403],
        `${api.s.key} edits project`,
      );
    }
    expect((await st.getProject(p.id)).name).toBe(p.name);

    // Reservation approval.
    for (const api of [agent, buyer, technician, notary]) {
      await expectRefused(
        await api.raw("POST", `/api/Reservations/${submitted.reservationId}/approve`, { reservationId: submitted.reservationId, adminUserId: api.userId, documents: [] }),
        [403],
        `${api.s.key} approves reservation`,
      );
    }
    const admin = await Api.as("globalAdmin");
    expect((await admin.get<{ status: number }>(`/api/Reservations/${submitted.reservationId}`)).status).toBe(0);

    // Project finalisation (and the delivery step before it).
    for (const api of [agent, buyer, technician, notary]) {
      await expectRefused(await api.raw("POST", `/api/construction/projects/${p.id}/complete`, { projectId: p.id, confirm: true }), [403], `${api.s.key} completes project`);
      await expectRefused(await api.raw("POST", `/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true }), [403], `${api.s.key} finalizes project`);
    }
    expect((await st.getProject(p.id)).statusGlobal).not.toMatch(/COMPLETED|ARCHIVED/);

    // Sale confirmation = the notary's PURCHASE_COMPLETED: never the agent, buyer or technician.
    const j = await st.journey("FINAL_VISIT");
    await st.createDraftSale(j);
    await st.createNotaryAppointment(j);
    await st.confirmNotaryAppointment(j);
    const completion = { id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé" };
    for (const api of [agent, buyer, technician]) {
      await expectRefused(await api.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, completion), [403, 422], `${api.s.key} confirms sale`);
    }
    expect((await st.getSale(j.reservationId))?.status).not.toBe("Confirmed");

    // Claim closure validation.
    const c = await st.journey("CLAIM");
    await st.advanceClaim(c, "RESOLVED");
    for (const api of [technician, agent, buyer, notary]) {
      await expectRefused(
        await api.raw("PUT", `/api/after-sales/claims/${c.claimId}/status`, { claimId: c.claimId, newStatus: st.ClaimStatus.Closed }),
        [403],
        `${api.s.key} validates claim closure`,
      );
    }
    expect((await st.getClaim(c.claimId!))!.status).toBe(st.ClaimStatus.Resolved);
  });

  test("api_rejects_out_of_scope_project_access", async () => {
    // Staffed with the "other" agent/technician only: the default accounts are out of scope.
    const p = await st.createProject({ members: ["agentOther", "notary", "technicianOther", "techLead", "projectAdmin"] });
    const mine = await st.createReservation(p, { state: "SUBMITTED", agent: "agentOther" });
    const agent = await Api.as("agent");
    const buyer = await Api.as("buyer");

    await expectRefused(await agent.raw("GET", `/api/Projects/${p.id}`), [403, 404], "agent reads out-of-scope project");
    await expectRefused(await agent.raw("GET", `/api/Reservations/${mine.reservationId}`), [403, 404], "agent reads out-of-scope reservation");
    const listed = await agent.all<{ id: string }>("/api/Reservations/list");
    expect(listed.map((r) => r.id)).not.toContain(mine.reservationId);
    await expectRefused(
      await agent.raw("POST", "/api/Reservations/create", {
        buyerId: buyer.userId, name: "X", lastName: "HorsPérimètre", email: "x@example.test", phoneNumber: "+212600000000",
        unitId: p.unitIds[1], agentId: agent.userId, totalPropertyPrice: 1000000, reservationAmount: 10000, createAsDraft: true,
      }),
      [403],
      "agent reserves out of scope",
    );
    await expectRefused(
      await agent.raw("POST", `/api/Immeuble/${p.immeubleId}/floors`, { immeubleId: p.immeubleId, name: "R+5", sequenceNo: 5 }),
      [403],
      "agent adds a floor out of scope",
    );

    // A project admin is bound by memberships too.
    const q = await st.createProject({ members: ["agent"] });
    const padmin = await Api.as("projectAdmin");
    await expectRefused(
      await padmin.raw("PUT", `/api/Projects/${q.id}`, { id: q.id, name: "Hors périmètre", location: "X", address: "X", images: [] }),
      [403],
      "project admin edits out-of-scope project",
    );
    expect((await st.getProject(q.id)).name).toBe(q.name);

    const technician = await Api.as("technician");
    const claims = await technician.all<{ unitId: string }>("/api/after-sales/claims");
    expect(claims.filter((c) => p.unitIds.includes(c.unitId))).toHaveLength(0);
  });

  test("api_rejects_status_violation", async () => {
    const finalised = await st.createProject({ phase: "FINALISE" });
    const agent = await Api.as("agent");
    const buyer = await Api.as("buyer");

    // Reservation on a FINALISE project.
    const res = await agent.raw("POST", "/api/Reservations/create", {
      buyerId: buyer.userId, name: "X", lastName: "Finalisé", email: "x@example.test", phoneNumber: "+212600000000",
      unitId: finalised.unitIds[0], agentId: agent.userId, totalPropertyPrice: 1000000, reservationAmount: 10000, createAsDraft: true,
    });
    await expectRefused(res, [409, 422], "reservation on FINALISE project");
    expect((await agent.all<{ unitId: string }>("/api/Reservations/list")).filter((r) => r.unitId === finalised.unitIds[0])).toHaveLength(0);

    // Sale on a reservation that is not approved.
    const p = await st.createProject();
    const submitted = await st.createReservation(p, { state: "SUBMITTED" });
    await expectRefused(await agent.raw("POST", "/api/sales", { reservationId: submitted.reservationId, notes: "trop tôt" }), [409, 422], "sale on unapproved reservation");
    expect(await st.getSale(submitted.reservationId)).toBeFalsy();

    // Handover before the sale is confirmed; claim before delivery.
    const draft = await st.journey("DRAFT_SALE");
    await expectRefused(await agent.raw("POST", "/api/Handovers", { reservationId: draft.reservationId, scheduledAt: "2027-06-01T10:00:00" }), [409, 422], "handover on draft sale");
    await expectRefused(
      await buyer.raw("POST", "/api/after-sales/claims", { unitId: draft.unitId, title: "Trop tôt", description: "x", category: 0, priority: 1 }),
      [409, 422],
      "claim before delivery",
    );
  });

  test("api_enforces_state_machine_transitions", async () => {
    test.setTimeout(180_000);
    const admin = await Api.as("globalAdmin");
    const agent = await Api.as("agent");
    const notary = await Api.as("notary");

    // Reservation: a draft cannot be approved; an approved one cannot be approved again.
    const p = await st.createProject({ units: 3 });
    const draft = await st.createReservation(p, { state: "DRAFT", unitIndex: 0 });
    await expectRefused(
      await admin.raw("POST", `/api/Reservations/${draft.reservationId}/approve`, { reservationId: draft.reservationId, adminUserId: admin.userId, documents: [] }),
      [409, 422],
      "approve a draft",
    );
    expect((await admin.get<{ status: number }>(`/api/Reservations/${draft.reservationId}`)).status).toBe(5);

    // Final visit: Requested → Completed skips confirmation.
    const fv = await st.approvedInDelivery();
    await st.createFinalVisit(fv, "REQUESTED");
    const apptId = fv.finalVisitAppointmentId!;
    await expectRefused(
      await agent.raw("POST", `/api/final-visits/appointments/${apptId}/transition`, { appointmentId: apptId, targetStatus: st.AppointmentStatus.Completed }),
      [409, 422],
      "final visit Requested -> Completed",
    );

    // Notary appointment: Scheduled → Completed skips confirmation.
    const j = await st.journey("FINAL_VISIT");
    await st.createDraftSale(j);
    await st.createNotaryAppointment(j);
    await expectRefused(
      await notary.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, { id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "saut" }),
      [409, 422],
      "notary appointment -> Completed without confirmation",
    );

    // Sale: stays a draft; a confirmed sale cannot go back to draft.
    expect((await st.getSale(j.reservationId))?.status).not.toBe("Confirmed");
    await st.confirmNotaryAppointment(j);
    await notary.put(`/api/NotaryAppointments/${j.notaryAppointmentId}`, { id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé" });
    const sale = (await st.getSale(j.reservationId))!;
    expect(sale.status).toBe("Confirmed");
    await expectRefused(await agent.raw("PUT", `/api/sales/${sale.id}`, { id: sale.id, notes: "modif après confirmation" }), [403, 409, 422], "edit a confirmed sale");

    // Claim: Submitted → Resolved skips every step.
    const c = await st.journey("CLAIM");
    const lead = await Api.as("techLead");
    await expectRefused(
      await lead.raw("PUT", `/api/after-sales/claims/${c.claimId}/status`, { claimId: c.claimId, newStatus: st.ClaimStatus.Resolved, resolutionSummary: "saut" }),
      [409, 422],
      "claim Submitted -> Resolved",
    );
    expect((await st.getClaim(c.claimId!))!.status).toBe(st.ClaimStatus.Submitted);
  });

  test("api_upload_requires_token_role_ownership_and_project_scope", async () => {
    const p = await st.createProject({ members: ["agent", "notary", "technician", "techLead", "projectAdmin"] });
    const j = await st.createReservation(p, { state: "SUBMITTED" });
    const url = `${PROJECT_API}/api/Reservations/${j.reservationId}/documents`;

    // 1. No token.
    const anon = await request.newContext();
    const noToken = await anon.post(url, { multipart: { File: pdf("anonyme"), DocumentType: "CIN" } });
    expect(noToken.status()).toBe(401);
    await anon.dispose();

    // 2. Wrong role.
    for (const key of ["buyer", "technician", "notary"] as const) {
      const api = await Api.as(key);
      const res = await api.ctx.post(url, { multipart: { File: pdf(key), DocumentType: "CIN" } });
      expect(res.status(), `${key} uploads a reservation document`).toBe(403);
    }

    // 3. Ownership: another buyer cannot attach evidence to someone else's claim.
    const c = await st.journey("CLAIM");
    const other = await Api.as("buyerOther");
    const notMine = await other.ctx.post(`${PROJECT_API}/api/after-sales/claims/${c.claimId}/attachments`, {
      multipart: { File: { name: "intrus.png", mimeType: "image/png", buffer: st.PNG_1PX } },
    });
    expect([403, 404], `other buyer uploads on claim: ${notMine.status()}`).toContain(notMine.status());

    // 4. Project scope: an agent not staffed on the project.
    const agentOther = await Api.as("agentOther");
    const outOfScope = await agentOther.ctx.post(url, { multipart: { File: pdf("hors-perimetre"), DocumentType: "CIN" } });
    expect(outOfScope.status(), "out-of-scope agent uploads").toBe(403);

    // Nothing was stored by any refused call; the legitimate upload works.
    const admin = await Api.as("globalAdmin");
    const checklist = await admin.get<{ documents?: unknown[]; items?: { uploaded?: boolean }[] }>(`/api/Reservations/${j.reservationId}/document-checklist`);
