      multipart: { File: { name: "intrus.png", mimeType: "image/png", buffer: st.PNG_1PX } },
    });
    expect([403, 404], `other buyer uploads on claim: ${notMine.status()}`).toContain(notMine.status());

    // 4. Project scope: an agent not staffed on the project.
    const agentOther = await Api.as("agentOther");
    const outOfScope = await agentOther.ctx.post(url, { multipart: { File: pdf("hors-perimetre"), DocumentType: "CIN" } });
    expect(outOfScope.status(), "out-of-scope agent uploads").toBe(403);

    // Nothing was stored by any refused call; the legitimate upload works.
    const admin = await Api.as("globalAdmin");
    const checklist = await admin.get<{ documents?: unknown[]; items?: { uploaded?: boolean }[] }>(`/api/Reservations/${j.reservationId}/document-checklist`);
    expect(JSON.stringify(checklist)).not.toMatch(/anonyme|intrus|hors-perimetre|technician\.pdf|notary\.pdf|buyer\.pdf/);
    const ok = await st.uploadReservationDocument(j.reservationId, "CIN");
    expect(ok.id).toBeTruthy();
    expect((await admin.get<{ attachments: unknown[] }>(`/api/after-sales/claims/${c.claimId}`)).attachments).toHaveLength(0);
  });

  test("api_rejects_file_access_from_non_owner", async () => {
    // A reservation document.
