    const admin = await Api.as("globalAdmin");
    const completion = { id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé (E2E)" };

    const res = await st.withSaleInsertFailure(j.unitId, () => notary.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, completion));
    expect(res.status(), await res.text()).toBeGreaterThanOrEqual(400);

