    const notary = await Api.as("notary");

    // Project creation / modification.
    for (const api of [agent, buyer, technician, notary]) {
      await expectRefused(await api.raw("POST", "/api/Projects", { name: `intrus-${st.uid()}`, location: "X", address: "X", images: [] }), [403], `${api.s.key} creates project`);
      await expectRefused(
        await api.raw("PUT", `/api/Projects/${p.id}`, { id: p.id, name: "Piraté", location: "X", address: "X", images: [] }),
        [403],
        `${api.s.key} edits project`,
      );
    }
    expect((await st.getProject(p.id)).name).toBe(p.name);

    // Reservation approval.
    for (const api of [agent, buyer, technician, notary]) {
      await expectRefused(
        await api.raw("POST", `/api/Reservations/${submitted.reservationId}/approve`, { reservationId: submitted.reservationId, adminUserId: api.userId, documents: [] }),
        [403],
        `${api.s.key} approves reservation`,
      );
    }
    const admin = await Api.as("globalAdmin");
    expect((await admin.get<{ status: number }>(`/api/Reservations/${submitted.reservationId}`)).status).toBe(0);

    // Project finalisation (and the delivery step before it).
    for (const api of [agent, buyer, technician, notary]) {
      await expectRefused(await api.raw("POST", `/api/construction/projects/${p.id}/complete`, { projectId: p.id, confirm: true }), [403], `${api.s.key} completes project`);
      await expectRefused(await api.raw("POST", `/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true }), [403], `${api.s.key} finalizes project`);
    }
    expect((await st.getProject(p.id)).statusGlobal).not.toMatch(/COMPLETED|ARCHIVED/);

    // Sale confirmation = the notary's PURCHASE_COMPLETED: never the agent, buyer or technician.
    const j = await st.journey("FINAL_VISIT");
    await st.createDraftSale(j);
    await st.createNotaryAppointment(j);
    await st.confirmNotaryAppointment(j);
    const completion = { id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé" };
    for (const api of [agent, buyer, technician]) {
      await expectRefused(await api.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, completion), [403, 422], `${api.s.key} confirms sale`);
    }
    expect((await st.getSale(j.reservationId))?.status).not.toBe("Confirmed");

    // Claim closure validation.
    const c = await st.journey("CLAIM");
    await st.advanceClaim(c, "RESOLVED");
    for (const api of [technician, agent, buyer, notary]) {
      await expectRefused(
        await api.raw("PUT", `/api/after-sales/claims/${c.claimId}/status`, { claimId: c.claimId, newStatus: st.ClaimStatus.Closed }),
        [403],
        `${api.s.key} validates claim closure`,
      );
    }
    expect((await st.getClaim(c.claimId!))!.status).toBe(st.ClaimStatus.Resolved);
  });

  test("api_rejects_out_of_scope_project_access", async () => {
    // Staffed with the "other" agent/technician only: the default accounts are out of scope.
    const p = await st.createProject({ members: ["agentOther", "notary", "technicianOther", "techLead", "projectAdmin"] });
    const mine = await st.createReservation(p, { state: "SUBMITTED", agent: "agentOther" });
    const agent = await Api.as("agent");
    const buyer = await Api.as("buyer");

    await expectRefused(await agent.raw("GET", `/api/Projects/${p.id}`), [403, 404], "agent reads out-of-scope project");
    await expectRefused(await agent.raw("GET", `/api/Reservations/${mine.reservationId}`), [403, 404], "agent reads out-of-scope reservation");
    const listed = await agent.all<{ id: string }>("/api/Reservations/list");
    expect(listed.map((r) => r.id)).not.toContain(mine.reservationId);
    await expectRefused(
      await agent.raw("POST", "/api/Reservations/create", {
        buyerId: buyer.userId, name: "X", lastName: "HorsPérimètre", email: "x@example.test", phoneNumber: "+212600000000",
        unitId: p.unitIds[1], agentId: agent.userId, totalPropertyPrice: 1000000, reservationAmount: 10000, createAsDraft: true,
      }),
      [403],
      "agent reserves out of scope",
    );
    await expectRefused(
      await agent.raw("POST", `/api/Immeuble/${p.immeubleId}/floors`, { immeubleId: p.immeubleId, name: "R+5", sequenceNo: 5 }),
      [403],
      "agent adds a floor out of scope",
    );

    // A project admin is bound by memberships too.
    const q = await st.createProject({ members: ["agent"] });
    const padmin = await Api.as("projectAdmin");
    await expectRefused(
      await padmin.raw("PUT", `/api/Projects/${q.id}`, { id: q.id, name: "Hors périmètre", location: "X", address: "X", images: [] }),
      [403],
      "project admin edits out-of-scope project",
    );
    expect((await st.getProject(q.id)).name).toBe(q.name);

    const technician = await Api.as("technician");
    const claims = await technician.all<{ unitId: string }>("/api/after-sales/claims");
    expect(claims.filter((c) => p.unitIds.includes(c.unitId))).toHaveLength(0);
  });

  test("api_rejects_status_violation", async () => {
    const finalised = await st.createProject({ phase: "FINALISE" });
    const agent = await Api.as("agent");
    const buyer = await Api.as("buyer");

    // Reservation on a FINALISE project.
