import { expect, test, type Page } from "@playwright/test";
import { Api, expectRefused } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, field, openReservation } from "./support/ui";

/** Scope 10 — Contraintes frontend (transverses). */

/** Records the ProjectAPI calls a page makes, in order. */
function recordApi(page: Page) {
  const log: { method: string; path: string; status: number; at: number }[] = [];
  page.on("response", (r) => {
    const url = new URL(r.url());
    if (url.port !== "48989" || r.request().method() === "OPTIONS") return;
    log.push({ method: r.request().method(), path: `${url.pathname}${url.search}`, status: r.status(), at: Date.now() });
  });
  return log;
}

/** Waits until a GET matching `list` completed after the mutation matching `mutation`. */
async function expectReloadAfter(log: ReturnType<typeof recordApi>, mutation: { method: string; path: RegExp }, list: RegExp) {
  await expect
    .poll(() => {
      const m = log.findIndex((e) => e.method === mutation.method && mutation.path.test(e.path) && e.status < 400);
      return m >= 0 && log.slice(m + 1).some((e) => e.method === "GET" && list.test(e.path) && e.status === 200);
    }, { message: `GET ${list} after ${mutation.method} ${mutation.path}` })
    .toBe(true);
}

// ---------------------------------------------------------------------------
// forbidden_actions_hidden_or_disabled_by_role_and_status
// ---------------------------------------------------------------------------
test.describe("Actions interdites — agent", { tag: "@agent" }, () => {
  test("forbidden_actions_hidden_or_disabled_by_role_and_status", async ({ page }) => {
    const p = await st.createProject();
    const own = await st.createReservation(p, { state: "SUBMITTED" });

    // Project (SUR_PLAN): no management action for an agent.
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("heading", { name: p.name })).toBeVisible();
    for (const name of ["Modifier", "Supprimer", "+ Nouveau bâtiment", "Ajouter le jalon", "Passer en livraison"]) {
      await expect(page.getByRole("button", { name, exact: true })).toHaveCount(0);
    }

    // Own SUBMITTED reservation: no self-approval.
    const detail = await openReservation(page, p.name, own.buyerLastName);
    await expect(detail.getByRole("button", { name: "Approuver" })).toHaveCount(0);

    // Admin-only screens are not reachable.
    for (const path of ["/admin/users", "/admin/quartiers", "/admin/type-biens", "/admin/assignments"]) {
      await page.goto(path);
      await expect(page).not.toHaveURL(new RegExp(`${path}$`));
    }
  });
});

test.describe("Actions interdites — admin projet", { tag: "@projectAdmin" }, () => {
  test("forbidden_actions_hidden_or_disabled_by_role_and_status", async ({ page }) => {
    acceptDialogs(page);
    // SUBMITTED by the agent: the project admin reviews it.
    const p = await st.createProject({ units: 2 });
    const submitted = await st.createReservation(p, { state: "SUBMITTED", unitIndex: 0 });
    const detail = await openReservation(page, p.name, submitted.buyerLastName);
    await expect(detail.getByRole("button", { name: "Approuver" })).toBeVisible();
    await page.keyboard.press("Escape");

    // APPROVED: no approval nor submission any more.
    const approved = await st.createReservation(p, { state: "APPROVED", unitIndex: 1 });
    const approvedDetail = await openReservation(page, p.name, approved.buyerLastName);
    for (const name of ["Approuver", "Soumettre", "Demander une correction"]) {
      await expect(approvedDetail.getByRole("button", { name })).toHaveCount(0);
    }
    await page.keyboard.press("Escape");

    // EN_LIVRAISON: construction steps done, only "Finaliser" is offered.
    await st.setConstructionPct(p, 100);
    await st.completeProject(p);
    await page.goto(`/admin/projects/${p.id}`);
    await expect(page.getByRole("button", { name: "Finaliser le projet" })).toBeVisible();
    await expect(page.getByRole("button", { name: "Passer en livraison" })).toHaveCount(0);
    await page.getByRole("button", { name: "Modifier", exact: true }).click();
    await expect(field(page.getByRole("dialog", { name: "Modifier le projet" }), "Statut")).toHaveCount(0);
    await page.keyboard.press("Escape");

    // FINALISE: read-only.
    await st.finalizeProject(p);
    await page.reload();
    await expect(page.getByRole("status", { name: "Projet en lecture seule" })).toBeVisible();
    for (const name of ["Modifier", "Supprimer", "+ Nouveau bâtiment", "Finaliser le projet"]) {
      await expect(page.getByRole("button", { name, exact: true })).toHaveCount(0);
    }
  });
});

test.describe("Actions interdites — technicien", { tag: "@technician" }, () => {
  test("forbidden_actions_hidden_or_disabled_by_role_and_status", async ({ page }) => {
    const j = await st.journey("CLAIM");
    const claim = (await st.getClaim(j.claimId!))!;

    // Commercial screens are not reachable.
    for (const path of ["/admin/reservations", "/admin/sales", "/admin/projects", "/admin/notary-appointments"]) {
      await page.goto(path);
      await expect(page).not.toHaveURL(new RegExp(`${path}$`));
    }

    // Not assigned yet: the claim is not even listed.
    await page.goto("/admin/claims");
    await expect(page.getByRole("heading", { name: "Réclamations SAV" })).toBeVisible();
    await expect(page.getByRole("row").filter({ hasText: claim.title })).toHaveCount(0);

    // Assigned and resolved: works it, but never assigns, refuses nor validates.
    await st.advanceClaim(j, "RESOLVED", "technician");
    await page.reload();
    const row = page.getByRole("row").filter({ hasText: claim.title });
    await expect(row).toHaveCount(1);
    for (const name of ["Affecter un technicien", "Refuser", "Valider la clôture", "Résoudre", "Commencer l'examen"]) {
      await expect(row.getByRole("button", { name })).toHaveCount(0);
    }
  });
});

test.describe("Actions interdites — acheteur", { tag: "@buyer" }, () => {
  test("forbidden_actions_hidden_or_disabled_by_role_and_status", async ({ page }) => {
    // No back office at all.
    for (const path of ["/admin", "/admin/reservations", "/admin/claims", "/admin/projects"]) {
      await page.goto(path);
      await expect(page).not.toHaveURL(/\/admin/);
    }

    // SAV: no new claim offered on a unit that is not delivered.
    const sold = await st.journey("SOLD");
    await page.goto("/my/sav");
    await page.getByRole("button", { name: "Nouvelle réclamation" }).click();
    await expect(page.locator("option", { hasText: sold.project.name })).toHaveCount(0);

    // A resolved claim offers the buyer's answer, a closed one offers nothing.
    const c = await st.journey("CLAIM");
    await st.advanceClaim(c, "RESOLVED");
    const title = (await st.getClaim(c.claimId!))!.title;
    await page.goto("/my/sav");
    const row = page.getByRole("row").filter({ hasText: title });
    await expect(row.getByRole("button", { name: /Confirmer/ })).toBeVisible();
    const lead = await Api.as("techLead");
    await lead.put(`/api/after-sales/claims/${c.claimId}/status`, { claimId: c.claimId, newStatus: st.ClaimStatus.Closed, note: "Validé" });
    await page.reload();
    await expect(row.getByRole("button", { name: /Confirmer|Rouvrir/ })).toHaveCount(0);
    await row.getByRole("button", { name: "Détails" }).click();
    const dialog = page.getByRole("dialog", { name: `Réclamation — ${title}` });
    await expect(dialog.getByRole("button", { name: "Répondre" })).toHaveCount(0);
    await expect(dialog.getByLabel("Ajouter une pièce jointe")).toHaveCount(0);
  });
});

// ---------------------------------------------------------------------------
// ui_reloads_data_after_each_mutation
// ---------------------------------------------------------------------------
test.describe("Rechargement après mutation", { tag: "@projectAdmin" }, () => {
  test("ui_reloads_data_after_each_mutation", async ({ page }) => {
    acceptDialogs(page);
    const log = recordApi(page);
    const name = `Rechargement ${st.uid()}`;

    // Create.
    await page.goto("/admin/quartiers");
    await page.getByRole("button", { name: "+ Nouveau quartier" }).click();
    const create = page.getByRole("dialog", { name: "Nouveau quartier" });
    await field(create, "Nom").fill(name);
    await create.getByRole("button", { name: "Créer" }).click();
    await expectReloadAfter(log, { method: "POST", path: /\/api\/Projects\/quartiers$/ }, /\/api\/Projects\/quartiers\?/);
    await expect(page.getByRole("row").filter({ hasText: name })).toHaveCount(1);

    // Update.
    log.length = 0;
    await page.getByRole("row").filter({ hasText: name }).getByRole("button", { name: "Modifier" }).click();
    const edit = page.getByRole("dialog", { name: `Modifier — ${name}` });
    await field(edit, "Description").fill("Relue depuis l'API");
    await edit.getByRole("button", { name: "Enregistrer" }).click();
    await expectReloadAfter(log, { method: "PUT", path: /\/api\/Projects\/quartiers\// }, /\/api\/Projects\/quartiers\?/);
    await expect(page.getByRole("row").filter({ hasText: name })).toContainText("Relue depuis l'API");

    // Delete.
    log.length = 0;
    await page.getByRole("row").filter({ hasText: name }).getByRole("button", { name: "Supprimer" }).click();
    await expectReloadAfter(log, { method: "DELETE", path: /\/api\/Projects\/quartiers\// }, /\/api\/Projects\/quartiers\?/);
    await expect(page.getByRole("row").filter({ hasText: name })).toHaveCount(0);

    // A reservation approval re-reads the reservation list too.
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "SUBMITTED" });
    const detail = await openReservation(page, p.name, j.buyerLastName);
    log.length = 0;
    await detail.getByRole("button", { name: "Approuver" }).click();
    await expectReloadAfter(log, { method: "POST", path: /\/approve$/ }, /\/api\/Reservations\/list\?/);
    const admin = await Api.as("globalAdmin");
    expect((await admin.get<{ status: number }>(`/api/Reservations/${j.reservationId}`)).status).toBe(1);
  });
});

// ---------------------------------------------------------------------------
// buyer_pages_call_only_mine_endpoints
// ---------------------------------------------------------------------------
test.describe("Pages acheteur", { tag: "@buyer" }, () => {
  test("buyer_pages_call_only_mine_endpoints", async ({ page }) => {
    test.setTimeout(180_000);
    const j = await st.journey("CLAIM");
    const log = recordApi(page);
    for (const path of ["/my", "/my/properties", `/my/properties/${j.reservationId}`, "/my/sav", "/my/favorites", "/my/notifications", "/my/profile"]) {
      await page.goto(path);
      await page.waitForLoadState("networkidle");
    }
    const calls = [...new Set(log.map((e) => `${e.method} ${e.path.replace(/[0-9a-f]{8}-[0-9a-f-]{27}/gi, "{id}")}`))];
    expect(calls.length).toBeGreaterThan(5);

    // "mine" endpoints (identity from the token) or a single resource of the
    // buyer's own file, which the API checks for ownership (asserted below).
    const allowed = [
      /\/mine(\?|$)/,
      /^GET \/api\/after-sales\/claims\/eligible-units$/,
      /^GET \/api\/after-sales\/claims\/\{id\}$/,
      /^GET \/api\/(Handovers|final-visits|payments)\/reservations\/\{id\}\//,
      /^GET \/api\/construction\/units\/\{id\}\/title$/,
      /^GET \/api\/Reservations\/\{id\}\/document-checklist$/,
    ];
    const offending = calls.filter((c) => !allowed.some((re) => re.test(c)));
    expect(offending, `global / unfiltered endpoints called from buyer pages:\n${offending.join("\n")}`).toEqual([]);
    expect(calls.filter((c) => /[?&](UserId|BuyerId)=/i.test(c))).toEqual([]);

    // Every per-resource read is refused to another buyer.
    const other = await Api.as("buyerOther");
    const concrete = [...new Set(log.filter((e) => e.method === "GET" && /[0-9a-f]{8}-[0-9a-f-]{27}/i.test(e.path) && !/\/mine/.test(e.path)).map((e) => e.path))];
    expect(concrete.length).toBeGreaterThan(0);
    for (const path of concrete) {
      await expectRefused(await other.raw("GET", path), [403, 404], `other buyer GET ${path}`);
    }
  });
});

