    for (const path of ["/my", "/my/properties", `/my/properties/${j.reservationId}`, "/my/sav", "/my/favorites", "/my/notifications", "/my/profile"]) {
      await page.goto(path);
      await page.waitForLoadState("networkidle");
    }
    const calls = [...new Set(log.map((e) => `${e.method} ${e.path.replace(/[0-9a-f]{8}-[0-9a-f-]{27}/gi, "{id}")}`))];
    expect(calls.length).toBeGreaterThan(5);

    // "mine" endpoints (identity from the token) or a single resource of the
    // buyer's own file, which the API checks for ownership (asserted below).
    const allowed = [
      /\/mine(\?|$)/,
      /^GET \/api\/after-sales\/claims\/eligible-units$/,
      /^GET \/api\/after-sales\/claims\/\{id\}$/,
      /^GET \/api\/(Handovers|final-visits|payments)\/reservations\/\{id\}\//,
      /^GET \/api\/construction\/units\/\{id\}\/title$/,
      /^GET \/api\/Reservations\/\{id\}\/document-checklist$/,
    ];
