import { expect, test, type Page } from "@playwright/test";
import { Api, expectRefused } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, field, openReservation } from "./support/ui";

/** Scope 10 — Contraintes frontend (transverses). */

/** Records the ProjectAPI calls a page makes, in order. */
function recordApi(page: Page) {
  const log: { method: string; path: string; status: number; at: number }[] = [];
  page.on("response", (r) => {
    const url = new URL(r.url());
    if (url.port !== "48989" || r.request().method() === "OPTIONS") return;
    log.push({ method: r.request().method(), path: `${url.pathname}${url.search}`, status: r.status(), at: Date.now() });
  });
  return log;
}

/** Waits until a GET matching `list` completed after the mutation matching `mutation`. */
async function expectReloadAfter(log: ReturnType<typeof recordApi>, mutation: { method: string; path: RegExp }, list: RegExp) {
  await expect
    .poll(() => {
      const m = log.findIndex((e) => e.method === mutation.method && mutation.path.test(e.path) && e.status < 400);
      return m >= 0 && log.slice(m + 1).some((e) => e.method === "GET" && list.test(e.path) && e.status === 200);
    }, { message: `GET ${list} after ${mutation.method} ${mutation.path}` })
    .toBe(true);
}

