import { Link } from "react-router-dom";
import { favoritesApi } from "../../api/http/favoritesApi";
import { useAuth } from "../../context/AuthContext";
import { Async, Card, PageHeader, Table } from "../../components/ui";
import { useAsync } from "../../lib/useAsync";
import { formatDate } from "../../lib/format";

/** §8 "Favorites" — projects the buyer bookmarked from the public catalogue. */
export default function BuyerFavoritesPage() {
  const { user } = useAuth();
  const state = useAsync(() => (user ? favoritesApi.list(user.id) : Promise.resolve([])), [user?.id]);

  return (
    <div>
      <PageHeader title="Favoris" subtitle="Projets que vous suivez" />
      <Card>
        <Async state={state} isEmpty={(f) => f.length === 0} empty="Vous n'avez ajouté aucun projet à vos favoris.">
          {(favorites) => (
            <Table
              keyField={(f) => f.id}
              rows={favorites}
              columns={[
                { header: "Projet", render: (f) => f.projectName ?? f.projectId.slice(0, 8) },
                { header: "Localisation", render: (f) => f.projectLocation ?? "-" },
                { header: "Ajouté le", render: (f) => formatDate(f.likedAt) },
                {
                  header: "",
                  render: (f) => (
                    <Link to={`/properties/${f.projectId}`} className="btn btn-ghost">
                      Voir
                    </Link>
                  ),
                },
              ]}
            />
          )}
        </Async>
      </Card>
    </div>
  );
}
