/* --------------------------------------------------------------- favourite */

function FavouriteButton({ projectId, userId }: { projectId: string; userId?: string }) {
  const [isFavorite, setIsFavorite] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (!userId) {
      setIsFavorite(false);
      return;
    }
    favoritesApi
      .list(userId)
      .then((likes) => setIsFavorite(likes.some((l) => l.projectId === projectId)))
