import { expect, request, test } from "@playwright/test";
import { AUTH_API, PROJECT_API } from "./support/accounts";
import { Api, expectRefused } from "./support/api";
import * as st from "./support/state";
import { acceptDialogs, field } from "./support/ui";

/**
 * Workflow validation (docs/workflows/*.md in the backend repo): the workflows
 * not already exercised end to end by scopes 1-11.
 */

test.describe("Workflow — activation de compte acheteur", { tag: "@globalAdmin" }, () => {
  test("workflow_account_activation", async ({ browser }) => {
    test.setTimeout(150_000);
    const p = await st.createProject();
    const agent = await Api.as("agent");
    const suffix = st.uid();
    const email = `walkin.${suffix}@example.test`;

    // 1. A walk-in buyer without an account, approved by the admin.
    const created = await agent.post<{ reservationId: string }>("/api/Reservations/create", {
      name: "Nadia",
      lastName: `WalkIn-${suffix.slice(-6)}`,
      cin: `WK${suffix.slice(0, 6)}`,
      email,
      phoneNumber: "+212600445566",
      unitId: p.unitIds[0],
      agentId: agent.userId,
      totalPropertyPrice: 1250000,
      reservationAmount: 125000,
      isUnderConstruction: true,
      discount: 0,
    });
    const j = { project: p, unitId: p.unitIds[0], reservationId: created.reservationId, buyer: "buyer" as const, agent: "agent" as const, buyerLastName: `WalkIn-${suffix.slice(-6)}` };
    await st.approveReservation(j);

    // The approval issued a single-use invitation (no e-mail is sent: read it from the database).
    const token = st.runSql(`SELECT TOP 1 i.Token FROM AccountInvitations i WHERE i.Email = '${email}' AND i.AcceptedAt IS NULL AND i.RevokedAt IS NULL ORDER BY i.CreatedAt DESC`).trim();
    expect(token).toMatch(/^[0-9A-F]{64}$/);

    // 2-3. The invitee opens the link (no session) and sets a password.
    const context = await browser.newContext({ storageState: { cookies: [], origins: [] } });
    const page = await context.newPage();
    await page.goto(`/activate?token=${token}`);
    const password = `Walkin${suffix.slice(-6)}a`;
    await field(page, "Mot de passe").fill(password);
    await field(page, "Confirmer le mot de passe").fill(password);
    await page.getByRole("button", { name: "Activer mon compte" }).click();
    await expect(page.getByText(`Compte activé pour ${email}.`)).toBeVisible({ timeout: 30_000 });

    // 4-5. The account exists with BUYER, and the file created before it is now theirs.
    const login = await request.newContext();
    const res = await login.post(`${AUTH_API}/api/User/login`, { data: { userName: email, password } });
    expect(res.status()).toBe(200);
    const body = (await res.json()) as { accessToken: string; roles: string[] };
    expect(body.roles).toContain("BUYER");
    const buyer = await request.newContext({ extraHTTPHeaders: { Authorization: `Bearer ${body.accessToken}` } });
    const mine = (await (await buyer.get(`${PROJECT_API}/api/Reservations/mine`)).json()) as { id: string }[];
    expect(mine.map((r) => r.id)).toContain(created.reservationId);

    // The token is single-use.
    const again = await login.post(`${PROJECT_API}/api/invitations/accept`, { data: { token, password } });
    expect(again.status()).toBe(409);
    expect(await again.text()).toMatch(/INVITATION_ALREADY_ACCEPTED/);

    // And the buyer portal shows the file.
    await page.goto("/login");
    await page.getByLabel(/e-?mail|identifiant/i).first().fill(email);
    await page.getByLabel(/mot de passe/i).first().fill(password);
    await page.getByRole("button", { name: /connexion|se connecter/i }).click();
    await expect(page).toHaveURL(/\/my/, { timeout: 30_000 });
    await page.goto("/my/properties");
    await expect(page.getByText(p.name).first()).toBeVisible();
    await Promise.all([login.dispose(), buyer.dispose(), context.close()]);
  });
});

test.describe("Workflow — favori → lead", { tag: "@buyer" }, () => {
  test("workflow_favourite_to_lead", async ({ page }) => {
    const p = await st.createProject();
    const buyer = await Api.as("buyer");
    const likes = () => Number(st.runSql(`SELECT NumberLikes FROM Projects WHERE Id = '${p.id}'`).trim());
    const leads = () => Number(st.runSql(`SELECT COUNT(*) FROM Leads WHERE ProjectId = '${p.id}' AND UserId = '${buyer.userId}'`).trim());
    const rows = () => Number(st.runSql(`SELECT COUNT(*) FROM LikedProjects WHERE ProjectId = '${p.id}' AND UserId = '${buyer.userId}'`).trim());
    const likesBefore = likes();

    // 1. Favourite from the public page.
    await page.goto(`/properties/${p.id}`);
    const toggle = page.getByRole("button", { name: /Favori/ });
    await expect(toggle).toHaveAttribute("aria-pressed", "false");
    await toggle.click();
    await expect(toggle).toHaveAttribute("aria-pressed", "true");
    expect(rows()).toBe(1);
    expect(likes()).toBe(likesBefore + 1);
    const leadsAfterLike = leads();
    expect(leadsAfterLike).toBe(p.buildings.length);

    // Idempotent: a second like changes nothing.
    await buyer.post("/api/Projects/Like", { userId: buyer.userId, projectId: p.id });
    expect(rows()).toBe(1);
    expect(likes()).toBe(likesBefore + 1);
    expect(leads()).toBe(leadsAfterLike);

    // 2. Read favourites (own only, identity from the token).
    await page.goto("/my/favorites");
    await expect(page.getByRole("row").filter({ hasText: p.name })).toHaveCount(1);
    const other = await Api.as("buyerOther");
    const theirs = await other.get<{ data: { projectId: string }[] }>(`/api/Projects/LikedProjects?UserId=${buyer.userId}&PageSize=500`);
    expect(theirs.data.map((l) => l.projectId)).not.toContain(p.id);
    // Nobody can favourite on the buyer's behalf.
    const q = await st.createProject();
    await other.post("/api/Projects/Like", { userId: buyer.userId, projectId: q.id });
    expect(Number(st.runSql(`SELECT COUNT(*) FROM LikedProjects WHERE ProjectId = '${q.id}' AND UserId = '${buyer.userId}'`).trim())).toBe(0);

    // 3. Un-favourite walks everything back.
    await page.goto(`/properties/${p.id}`);
    await expect(toggle).toHaveAttribute("aria-pressed", "true");
    await toggle.click();
    await expect(toggle).toHaveAttribute("aria-pressed", "false");
    expect(rows()).toBe(0);
    expect(likes()).toBe(likesBefore);
    expect(leads()).toBe(0);
  });
});

test.describe("Workflow — suppression de projet", { tag: "@projectAdmin" }, () => {
  test("workflow_project_deletion_cascade", async ({ page }) => {
    acceptDialogs(page);
    const admin = await Api.as("globalAdmin");

    // A project with no commercial history is deleted with its buildings and units.
    const empty = await st.createProject();
    await page.goto(`/admin/projects/${empty.id}`);
    await page.getByRole("button", { name: "Supprimer", exact: true }).click();
    await expect(page).toHaveURL(/\/admin\/projects$/);
    const gone = await admin.get<{ data: unknown[] }>(`/api/Projects?Id=${empty.id}&PageSize=1`);
    expect(gone.data).toHaveLength(0);
    expect(Number(st.runSql(`SELECT COUNT(*) FROM Immeubles WHERE ProjectId = '${empty.id}'`).trim())).toBe(0);
    expect(Number(st.runSql(`SELECT COUNT(*) FROM Units WHERE Id IN ('${empty.unitIds.join("','")}')`).trim())).toBe(0);

    // A project with a reservation is refused and kept whole.
    const used = await st.createProject();
    const j = await st.createReservation(used, { state: "SUBMITTED" });
    await page.goto(`/admin/projects/${used.id}`);
    await page.getByRole("button", { name: "Supprimer", exact: true }).click();
    await expect(page.getByRole("alert")).toBeVisible();
    await expect(page).toHaveURL(new RegExp(`/admin/projects/${used.id}$`));
    expect((await st.getProject(used.id)).name).toBe(used.name);
    expect((await admin.get<{ id: string }>(`/api/Reservations/${j.reservationId}`)).id).toBe(j.reservationId);
    const direct = await admin.raw("DELETE", `/api/Projects/${used.id}`);
    await expectRefused(direct, [409], "delete project with reservation");

    // A building with a reservation is refused too; an empty building is deleted.
    await expectRefused(await admin.raw("DELETE", `/api/Immeuble/${used.immeubleId}`), [409], "delete building with reservation");
    const spare = await st.createProject({ layout: { buildings: [{ floors: [{ name: "RDC", units: [{}] }] }, { suffix: "B2", floors: [{ name: "RDC", units: [{}] }] }] } });
    const res = await admin.raw("DELETE", `/api/Immeuble/${spare.buildings[1].id}`);
    expect(res.status(), await res.text()).toBeLessThan(300);
    expect(Number(st.runSql(`SELECT COUNT(*) FROM Immeubles WHERE Id = '${spare.buildings[1].id}'`).trim())).toBe(0);
  });
});

