.pdp-hero { position: relative; isolation: isolate; margin-bottom: 8px; }
.pdp-hero-media { position: absolute; inset: 0; z-index: -2; overflow: hidden; }
.pdp-hero-media img { width: 100%; height: 100%; object-fit: cover; }
.pdp-hero-fallback { width: 100%; height: 100%; background: linear-gradient(140deg, var(--ink), #33465a); }
/* Scrim only over the lower half: the copy sits there, so the top of the
   photograph stays untouched instead of the whole image being dimmed. */
.pdp-hero-scrim {
  position: absolute; inset: 0; z-index: -1;
  background: linear-gradient(180deg, rgba(20,28,38,0.15) 0%, rgba(20,28,38,0.45) 45%, rgba(20,28,38,0.88) 100%);
}
.pdp-hero-inner { display: flex; align-items: flex-end; min-height: clamp(460px, 66vh, 680px); padding-block: 56px; }
.pdp-hero-copy { max-width: 680px; color: #fff; }

.pdp-hero-tags { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
.pdp-phase, .pdp-tag {
  padding: 6px 14px; border-radius: 999px; font-size: 11.5px; font-weight: 700;
  letter-spacing: 0.09em; text-transform: uppercase;
  background: rgba(255,255,255,0.14); border: 1px solid rgba(255,255,255,0.30); color: #fff;
  backdrop-filter: blur(6px);
}
/* The phase keeps a colour AND its own word, so it survives greyscale. */
.pdp-phase.phase-sur_plan { background: rgba(194,163,103,0.28); border-color: var(--brass); }
.pdp-phase.phase-en_livraison { background: rgba(46,160,87,0.26); border-color: #6fd694; }
.pdp-phase.phase-finalise { background: rgba(255,255,255,0.12); }
.pdp-phase.phase-suspended { background: rgba(192,57,43,0.30); border-color: #ef8a7f; }

.pdp-hero-copy h1 {
  margin: 0 0 14px; color: #fff; font-family: var(--font-display);
  font-size: clamp(36px, 5.4vw, 62px); line-height: 1.04; letter-spacing: -0.015em;
}
.pdp-hero-place { display: inline-flex; align-items: center; gap: 8px; margin: 0 0 16px; font-size: 15px; opacity: 0.92; }
.pdp-hero-lede { margin: 0 0 20px; max-width: 58ch; font-size: 16.5px; line-height: 1.65; opacity: 0.92; }
.pdp-hero-price { display: flex; align-items: baseline; gap: 10px; margin: 0 0 26px; }
.pdp-hero-price span { font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; opacity: 0.8; }
.pdp-hero-price strong { font-family: var(--font-display); font-size: clamp(26px, 3.2vw, 36px); }
.pdp-hero-actions { display: flex; flex-wrap: wrap; gap: 12px; }

/* One button language for the whole page — never a raw button/anchor default. */
.pdp-btn {
  display: inline-flex; align-items: center; gap: 9px; padding: 13px 26px; border-radius: 2px;
  font-family: var(--font-ui-pub); font-size: 12.5px; font-weight: 700;
  letter-spacing: 0.10em; text-transform: uppercase; text-decoration: none; cursor: pointer;
  border: 1px solid transparent; transition: background 0.22s var(--ease-out), color 0.22s, border-color 0.22s, transform 0.22s;
}
.pdp-btn-primary { background: var(--brass); color: #1b1300; }
.pdp-btn-primary:hover { background: #d4b87c; transform: translateY(-1px); }
/* Backdrop blur + a darker base so the ghost buttons stay legible over a pale
   sky or a white facade, not only over the dark part of the scrim. */
.pdp-btn-ghost {
  background: rgba(16,24,33,0.42); color: #fff; border-color: rgba(255,255,255,0.55);
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
}
.pdp-btn-ghost:hover { background: rgba(16,24,33,0.62); border-color: #fff; }
.pdp-btn:focus-visible { outline: 2px solid var(--brass); outline-offset: 3px; }
/* On the light body the ghost button inverts, so it stays readable off-hero. */
.container .pdp-btn-ghost { background: transparent; color: var(--charcoal); border-color: var(--greige-line); }
.container .pdp-btn-ghost:hover { border-color: var(--brass); color: var(--brass-text); background: #fff; }

/* ---------- facts band: lifted off the hero, not a bordered table ---------- */
.pdp-facts {
  position: relative; z-index: 2; margin: -58px 0 72px;
  display: grid; background: #fff; border-radius: 3px;
  box-shadow: 0 24px 60px rgba(20,28,38,0.16); overflow: hidden;
}

/* Balanced templates per fact count.
   An auto-fit grid fitted six cells on the first row and stranded the seventh
   ("Disponibilité") alone on a second row beside five empty columns. Driving
   the template from data-count makes every case deliberate, and the 12-column
   base lets 7 split as a clean 4 + 3 (4 x span-3, then 3 x span-4) with no
   orphan and no ragged edge. */
.pdp-facts[data-count="1"] { grid-template-columns: 1fr; }
.pdp-facts[data-count="2"] { grid-template-columns: repeat(2, 1fr); }
.pdp-facts[data-count="3"] { grid-template-columns: repeat(3, 1fr); }
