  { to: "/appointments/new", label: "Nous Contacter" },
];

export default function PublicLayout() {
  const [menuOpen, setMenuOpen] = useState(false);
  const location = useLocation();

  // F16 — the header overflowed at mobile widths because six nav items were
  // forced into one nowrap flex row (nav.public-nav measured 384px wide
  // against a 360px viewport). Below 640px those items now live in this
  // collapsible panel instead, closed on every navigation.
  useEffect(() => {
    setMenuOpen(false);
