test.use({ storageState: storageStateFor("buyer"), baseURL: "http://localhost:5173" });
test("fav", async ({ page }) => {
  const p = await st.createProject();
  let n = 0;
  page.on("request", (r) => { if (r.url().includes("LikedProjects")) n++; });
  await page.goto(`/properties/${p.id}`);
  await page.waitForTimeout(5000);
  const box1 = await page.getByRole("button", { name: /Favori/ }).boundingBox();
  await page.waitForTimeout(300);
  const box2 = await page.getByRole("button", { name: /Favori/ }).boundingBox();
  console.log("likes requests", n, JSON.stringify(box1), JSON.stringify(box2));
  const hit = await page.evaluate(() => { const b = [...document.querySelectorAll("button")].find((x) => x.textContent?.includes("Favori"))!; const r = b.getBoundingClientRect(); const el = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2); return el?.outerHTML.slice(0, 120) + " | scrollY=" + scrollY; });
  console.log("hit", hit);
});
