import { Link } from "react-router-dom";
import { reservationsApi } from "../../api";
import { Async, Card, PageHeader, RESERVATION_STATUS_LABEL, StatusBadge, Table } from "../../components/ui";
import { useAsync } from "../../lib/useAsync";
import { formatDate, formatMAD } from "../../lib/format";

/** §8 "My properties" — every reservation the buyer owns, one row each. */
export default function BuyerPropertiesPage() {
  const state = useAsync(() => reservationsApi.getMine(), []);

  return (
    <div>
      <PageHeader title="Mes biens" subtitle="Tous vos dossiers d'achat" />
      <Card>
        <Async state={state} isEmpty={(r) => r.length === 0} empty="Vous n'avez encore aucun dossier.">
          {(reservations) => (
            <Table
              keyField={(r) => r.id}
              rows={reservations}
              columns={[
                { header: "Bien", render: (r) => r.unitDetails ?? r.unitId.slice(0, 8) },
                { header: "Prix", render: (r) => formatMAD(r.totalPropertyPrice) },
                { header: "Réservé le", render: (r) => formatDate(r.reservationDate) },
                {
                  header: "Statut",
                  render: (r) => <StatusBadge status={r.status} label={RESERVATION_STATUS_LABEL[r.status]} />,
                },
                {
                  header: "",
                  render: (r) => (
                    <Link to={`/my/properties/${r.id}`} className="btn btn-ghost">
                      Voir le dossier
                    </Link>
                  ),
                },
              ]}
            />
          )}
        </Async>
      </Card>
    </div>
  );
}
