1	import { expect, request, test } from "@playwright/test";
2	import { PROJECT_API } from "./support/accounts";
3	import { Api, expectRefused } from "./support/api";
4	import * as st from "./support/state";
5	
6	/**
7	 * Scope 11 — Sécurité serveur (API seule).
8	 *
9	 * The frontend is never the guarantee: every call below goes straight to the
10	 * API with an unsuitable token (or none) and expects a refusal, then re-reads
11	 * the state to prove nothing changed.
12	 */
13	
14	const pdf = (label: string) => ({ name: `${label}.pdf`, mimeType: "application/pdf", buffer: Buffer.from(`%PDF-1.4 ${label}`) });
15	
16	test.describe("Sécurité serveur", { tag: "@globalAdmin" }, () => {
17	  test("api_rejects_role_violation", async () => {
18	    test.setTimeout(180_000);
19	    const p = await st.createProject({ constructionPct: 100 });
20	    const submitted = await st.createReservation(p, { state: "SUBMITTED" });
21	    const agent = await Api.as("agent");
22	    const buyer = await Api.as("buyer");
23	    const technician = await Api.as("technician");
24	    const notary = await Api.as("notary");
25	
26	    // Project creation / modification.
27	    for (const api of [agent, buyer, technician, notary]) {
28	      await expectRefused(await api.raw("POST", "/api/Projects", { name: `intrus-${st.uid()}`, location: "X", address: "X", images: [] }), [403], `${api.s.key} creates project`);
29	      await expectRefused(
30	        await api.raw("PUT", `/api/Projects/${p.id}`, { id: p.id, name: "Piraté", location: "X", address: "X", images: [] }),
31	        [403],
32	        `${api.s.key} edits project`,
33	      );
34	    }
35	    expect((await st.getProject(p.id)).name).toBe(p.name);
36	
37	    // Reservation approval.
38	    for (const api of [agent, buyer, technician, notary]) {
39	      await expectRefused(
40	        await api.raw("POST", `/api/Reservations/${submitted.reservationId}/approve`, { reservationId: submitted.reservationId, adminUserId: api.userId, documents: [] }),
41	        [403],
42	        `${api.s.key} approves reservation`,
43	      );
44	    }
45	    const admin = await Api.as("globalAdmin");
46	    expect((await admin.get<{ status: number }>(`/api/Reservations/${submitted.reservationId}`)).status).toBe(0);
