// Builds tests/REPORT.md from the Playwright JSON report of the final run.
const fs = require("fs");
const path = require("path");
const report = require(path.resolve(process.argv[2]));

const SCOPES = {
  "scope-01-roles.spec.ts": "1 — Rôles",
  "scope-02-projects-dashboard.spec.ts": "2 — Projet, construction, dashboard",
  "scope-03-quartiers-typebiens.spec.ts": "3 — Quartiers et types de biens",
  "scope-04-reservations.spec.ts": "4 — Réservations et documents",
  "scope-05-final-visit.spec.ts": "5 — Visite finale",
  "scope-06-sales.spec.ts": "6 — Vente",
  "scope-07-notary.spec.ts": "7 — Notaire",
  "scope-08-delivery-warranty.spec.ts": "8 — Livraison et garantie",
  "scope-09-claims.spec.ts": "9 — Réclamations",
  "scope-10-frontend-constraints.spec.ts": "10 — Contraintes frontend",
  "scope-11-server-security.spec.ts": "11 — Sécurité serveur",
  "scope-13-workflows.spec.ts": "Workflows (docs/workflows)",
};

const rows = [];
const walk = (suite, file) => {
  const f = suite.file || file;
  (suite.suites || []).forEach((s) => walk(s, f));
  (suite.specs || []).forEach((spec) =>
    spec.tests.forEach((t) => {
      const last = t.results[t.results.length - 1] || {};
      const status = t.status === "skipped" ? "fixme" : last.status === "passed" ? "passé" : "échoué";
      const error = last.error ? (last.error.message || "").replace(/\x1b\[[0-9;]*m/g, "").split("\n")[0].slice(0, 160) : "";
      rows.push({ file: spec.file || f, title: spec.title, project: t.projectName, status, error });
    }),
  );
};
report.suites.forEach((s) => walk(s, s.file));
const tests = rows.filter((r) => SCOPES[r.file]);

const count = (s) => tests.filter((r) => r.status === s).length;
const stats = report.stats || {};
let md = `# REPORT — suite Playwright UI (Projet → Réservation → Visite finale → Vente → Notaire → Livraison → Garantie → SAV)\n\n`;
md += `Exécution finale : ${new Date(stats.startTime || Date.now()).toISOString().slice(0, 16).replace("T", " ")} UTC — durée ${Math.round((stats.duration || 0) / 60000)} min — 2 workers.\n`;
md += `Pile : Vite (localhost:5173) · AuthenticationAPI (48988) · ProjectAPI (48989) · Azure SQL \`GPIA_Project\` (S2) / \`GPIA_Auth\`.\n\n`;
md += `**Résultat : ${count("passé")} passés · ${count("échoué")} échoués · ${count("fixme")} fixme** (${tests.length} exécutions de tests, un même test pouvant tourner pour plusieurs rôles ; + projet \`setup\`).\n\n`;
md += `Les écarts détectés pendant la campagne ont été **corrigés dans le code** (demande du propriétaire), puis revalidés : voir \`docs/fixes/\` (frontend et backend), \`docs/workflows/*.md\` (checklists « Validated ») et \`tests/GAPS.md\` (écarts restants, doublons, consolidation). Tests backend d'autorisation : 205/205.\n\n`;
md += `## Tableau des cas\n\n| Test | Scope | Rôle | Statut | Règle violée (si échec) |\n|---|---|---|---|---|\n`;
for (const r of tests.sort((a, b) => a.file.localeCompare(b.file) || a.title.localeCompare(b.title))) {
  md += `| \`${r.title}\` | ${SCOPES[r.file]} | ${r.project} | ${r.status === "passé" ? "✅ passé" : r.status === "fixme" ? "fixme" : "❌ échoué"} | ${r.error.replace(/\|/g, "\\|")} |\n`;
}
md += `\n## Principaux défauts corrigés pendant la campagne\n\n`;
md += [
  "Rôle TECH_LEAD absent ; technicien capable de clôturer ; machine d'état des réclamations dans le mauvais ordre ; pas de détail, commentaires ni photos avant/après.",
  "Finalisation en deux étapes (EN_LIVRAISON puis FINALISE) inexistante ; projet finalisé non en lecture seule (règle jamais appliquée) — garde transverse à l'enregistrement.",
  "Approbation sans documents obligatoires ; documents sans garde de statut ; aucun jeu de documents par défaut.",
  "Visite finale sans feedback / motif / action corrective ; RDV notaire non confirmable par l'agent, note non exigée.",
  "Vente : conditions non vérifiées côté UI ; PendingNotary jamais atteint ; brouillon non confirmé en place.",
  "Doublon du flux de livraison (api/deliveries) supprimé.",
  "Liste des projets en erreur 500 dès qu'un type de bien sans images intérieures est lié ; fiche projet introuvable au-delà de 500 projets.",
  "Suppression de projet impossible (toujours 409) ; suppression de bâtiment effaçant ventes et réservations — réécrites, transactionnelles, refusées en présence d'historique.",
  "Sécurité : pièces d'identité téléchargeables par les techniciens ; favoris de tous les utilisateurs lisibles ; médias du catalogue modifiables par un acheteur.",
  "Performance : liste des réservations chargée entièrement en mémoire à chaque page ; listes de périmètre inlinées en SQL (recompilations) ; numérotation des contacts CRM en collision.",
  "UI : informations projet / immeuble / étage / unité affichées partout ; cascades de filtres ; pagination complète ; erreurs affichées au lieu de spinners infinis ; bouton « Favori » masqué par le bandeau ; en-tête public ignorant la session.",
  "Base Azure mise à jour (6 migrations + fonctionnalités de quartier, sauvegardes préalables) et utilisée en développement.",
].map((l) => `- ${l}`).join("\n");
md += "\n";
fs.writeFileSync(path.resolve("tests/REPORT.md"), md);
console.log(`REPORT.md: ${tests.length} rows, ${count("passé")} passed, ${count("échoué")} failed`);

